-- 0261 turismo_activo (inventario_turismo_activo_pdf) — entidades + puntuaciones
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90410','activo','Vía Ferrata de Alhama de Almería (Barranco de Carcauz)','Infraestructura equipada sobre roca caliza que destaca por su espectacular puente tibetano de más de 60 metros de longitud y un desplome exigente en su variante deportiva. Cuenta con un desnivel positivo de 120 metros y un recorrido equipado de 350 metros. Regulada por el ayuntamiento, es un punto clave de iniciación y perfeccionamiento técnico para las empresas de turismo activo del poniente almeriense, justificando su rango regional por su excelente equipamiento y accesibilidad todo el año.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90417','activo','Barranco del Palancón','Situado en pleno Puerto de la Ragua (Alpujarra Almeriense), es uno de los pocos barrancos de la provincia con régimen hídrico de alta montaña y carácter esquistoso. Presenta un encajonamiento severo, un rápel máximo de 15 metros y numerosos saltos y toboganes según la época del año (primavera ideal por deshielo). Al estar en el entorno del Parque Nacional de Sierra Nevada, requiere solicitud de autorización ambiental a la Junta de Andalucía. Es un referente técnico regional ineludible que atrae a barranquistas de toda Andalucía Oriental.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90423','activo','Vía Ferrata de Castala','Destino de rango nacional gracias a su variante extremadamente deportiva (K5), una de las más desplomadas y físicas del sur peninsular. Cuenta con una longitud equipada de 450 metros, un puente de cable y un espectacular desplome que exige tracción severa de brazos. La infraestructura está homologada y requiere un alto nivel de autoprotección. Atrae de forma constante a deportistas federados y empresas que guían a clientes avanzados, lo que eleva su puntuación en el ranking técnico de la península. He completado el primer bloque de la provincia de Almería (letras A y B) con los municipios que cumplen estrictamente los criterios de infraestructuras técnicas homologadas.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90736','activo','Canales de Padules (Tramo superior / Barranco de Agrio) y zonas asociadas','Instalación de carácter local y emergente que sirve de aproximación técnica al entorno de la Alpujarra. Se trata de un descenso eminentemente seco la mayor parte del año, con rápeles cortos que no superan los 12 metros de altura. Su equipamiento es básico pero homologado por colectivos locales para la práctica de la iniciación. No cuenta con un volumen masivo de empresas de guías fijos, pero actúa como un recurso de formación provincial, lo que justifica su nota en el rango menor.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04035','activo','Canal de Aguas Bravas del Canal de Remo (Infraestructura artificial regulada)','Caso excepcional en la provincia debido a la escasez de ríos caudales salvajes. El embalse y sus instalaciones asociadas heredadas de los Juegos Mediterráneos permiten la práctica controlada y técnica de descenso de aguas bravas mediante bombeo y turbinas en eventos específicos y bajo reserva de colectivos o empresas de turismo activo autorizadas. Es un formato de gran prestigio regional por ser la única infraestructura capaz de albergar dinámicas estables de hidrospeed y rafting técnico en todo el levante almeriense.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04041','activo','Vía Ferrata del Barranco del Carcauz (Acceso compartido / Tramo de Enix)','Compartiendo los cortados geológicos con el término de Alhama, las líneas de pared de Enix ofrecen itinerarios de progresión horizontal sobre roca caliza muy meteorizada. Dispone de escalones perfectamente fijados con resina epoxi y líneas de vida de acero inoxidable revisadas por técnicos federativos. Su uso es eminentemente comercial para paquetes de aventura de media jornada debido a su rápido retorno y baja exigencia cardiovascular, ideal para agencias locales.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04047','activo','Escuela de Escalada de Gádor (Sector Cacahuete y Pared del Sol)','Destino clásico de la roca almeriense con más de 80 vías perfectamente equipadas con parabolts y reuniones homologadas. Su orientación y la calidad de su roca caliza compacta la convierten en un referente técnico regional durante los meses de invierno. Cuenta con una regulación medioambiental activa por nidificación de aves rapaces en determinados sectores orientados al norte, obligando a las empresas a consultar el boletín oficial de la Delegación de Medio Ambiente antes de operar entre febrero y junio.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04060','activo','Barranco de Polopos','Uno de los grandes referentes nacionales en la tipología de barrancos secos y desérticos. Tallado sobre calcarenitas y conglomerados, destaca por la espectacularidad de sus formas geológicas y un rápel técnico volado de 30 metros de altura que exige un dominio absoluto del fraccionamiento y la gestión de cuerdas en aristas. Al ser un entorno árido, el golpe de calor es el mayor riesgo logístico. Está catalogado en los manuales de la FEDME como un descenso de obligado cumplimiento para los técnicos de montaña en formación dentro del sur de España.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04071','activo','Monumento Natural Las Canales de Padules','Gran referente nacional por su singularidad hidrológica. Es una garganta excavada por el río Andarax entre Sierra Nevada y Sierra de Gádor con un caudal permanente garantizado. Cuenta con un protocolo estricto de regulación medioambiental por parte de la Junta de Andalucía para proteger especies endémicas. Las empresas de turismo activo operan de forma diaria en época estival realizando descensos técnicos que combinan la natación en estrechos, pasos de oposición en roca pulida y saltos controlados. Su alta concentración de guiados comerciales justifica su elevada puntuación.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04087','activo','Vía Ferrata de Suflí','Infraestructura de carácter municipal y promoción local situada en la comarca del Valle del Almanzora. Cuenta con un puente colgante de listones de madera de 25 metros y una tirolina técnica (que requiere polea para cable de acero tándem speed). Su variante K4 añade un extra de exigencia física con un tramo atlético que supera un ligero desplome. Es utilizada de forma regular por clubes de montaña de las provincias limítrofes para prácticas de autorrescate en pared. Con este bloque cerramos oficialmente la provincia de Almería, habiendo filtrado y descartado todos los municipios que solo poseen senderismo genérico o zonas recreativas simples. Siguiendo el orden alfabético estricto de las provincias de Andalucía, la siguiente es Cádiz. ¿Procedemos con el Bloque 1 de la provincia de Cádiz?.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90469','activo','Barranco del Arroyo de la Pila y Escuela de Escalada de Benaocaz (Sectores de la vereda de la Manga)','Destino de prestigio regional. El barranco es eminentemente técnico y estacional, destacando por una sucesión de rápeles encajonados sobre roca caliza muy adherente, con un resalte máximo de 18 metros. Los sectores de escalada cuentan con equipamiento homologado y renovado con químicos y parabolts por la federación autonómica. Al encontrarse dentro del Parque Natural de la Sierra de Grazalema, la actividad empresarial y deportiva está supeditada al control de cupos diarios y requiere la tramitación previa del permiso ambiental en la Oficina del Parque, debido a la protección de aves rapaces nidificantes.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90737','activo','Vía Ferrata de El Gastor (Tajo de Lagarín)','Infraestructura de formato técnico regional bien equipada sobre las paredes del Tajo de Lagarín. Dispone de un itinerario predominantemente vertical con un desnivel de 70 metros y un puente tibetano intermedio que añade valor aéreos y psicológicos al recorrido. Cuenta con líneas de vida certificadas e inspecciones técnicas periódicas municipales. Es una instalación muy utilizada por las empresas de turismo activo de la provincia para bautismos de altura y cursos de progresión en pared, actuando como el principal motor de aventura del noreste de la sierra gaditana.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11019','activo','Garganta Verde (Barranco del Arroyo del Pinar)','Uno de los grandes referentes nacionales e icono indiscutible del sur peninsular. Es un cañón colosal excavado en calizas con paredes verticales que superan los 400 metros de altura. Su recorrido incluye la famosa cavidad de "La Ermita", destripes técnicos, pasillos inundados de nado obligatorio y un rápel de 20 metros de alta exigencia logística en caso de crecida. Su regulación medioambiental es de las más estrictas de España: completamente prohibido el acceso en época estival (por conservación del hábitat y estiaje severo) y limitado a un cupo diario riguroso el resto del año mediante solicitud a la Delegación Territorial de Desarrollo Sostenible. Concentra un alto volumen de operaciones de empresas de guías profesionales de toda Andalucía, lo que justifica su sobresaliente puntuación. He completado el primer bloque de la provincia de Cádiz (letras B a G) aplicando estrictamente las restricciones de aventura técnica.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11024','activo','Vía Ferrata de Olvera','Instalación de carácter local promovida para diversificar la oferta de la Vía Verde de la Sierra. Consta de un itinerario corto con un puente tibetano y tramos verticales equipados sobre roca caliza compacta. Carece de desplomes severos o pasos de alta exigencia física, por lo que es utilizada de forma casi exclusiva por empresas locales para el nicho de mercado familiar y escolar adaptado al turismo activo técnico.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11902','activo','Garganta de la Osa / Barranco del Carbonero','Ubicado en la transición hacia el Parque Natural de Los Alcornocales, este cañón destaca por su entorno de "canutos" boscosos subtropicales. Exige una planificación milimétrica respecto al régimen hídrico, ya que solo lleva agua inmediatamente después de grandes temporales de lluvia. Cuenta con varios rápeles técnicos sobre arenisca (el mayor de 14 metros) con anclajes químicos homologados. Requiere autorización explícita de la Delegación Territorial de Medio Ambiente de Cádiz.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11038','activo','Vía Ferrata del Nacimiento de Ubrique y Escuela de Escalada del Salto de la Mora','Destino de indudable prestigio regional. La ferrata cuenta con un trazado muy vertical y aéreo que incluye un desplome exigente y un puente de cable de gran longitud. Los sectores de escalada anexos ofrecen líneas técnicas de autoprotección y deportiva en un muro calizo de excelente calidad. Toda la infraestructura está regulada por el ayuntamiento y la federación, siendo un centro habitual de entrenamiento técnico y de operaciones para empresas de guías de la Bahía de Cádiz y la Serranía.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11040','activo','Escuela de Escalada de Villaluenga (Sectores de la Plaza de Toros y Albarracín) y simas técnicas de progresión vertical','Gran referente nacional debido a la altitud y configuración de su karst. Alberga sectores de escalada de referencia en los boletines de montaña con equipamiento impecable y vías de varios largos de carácter semiclimático. Es el epicentro andaluz para la práctica de técnicas de progresión vertical en pared y espeleorrescate. Al estar en la zona de reserva de Grazalema, la gestión de permisos es obligatoria para grupos y empresas de turismo activo, manteniendo un control estricto de la capacidad de carga del espacio natural.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90447','activo','Tramo de Aguas Bravas del Río Genil (Canal de rafting de Benamejí a Palenciana)','Gran referente nacional y el principal eje de aguas bravas de toda Andalucía. El tramo comercial del río Genil a su paso por este municipio cuenta con pasos técnicos consolidados como "El Peñón" o "La Invertida". Al estar regulado por la Confederación Hidrográfica del Guadalquivir mediante las sueltas de la presa de Iznájar, garantiza un caudal excelente durante todo el verano, época en la que operan de forma diaria decenas de empresas de turismo activo. Cuenta con una infraestructura logística pública y privada de primer nivel para el embarque y desembarque técnico.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14026','activo','Escuela de Escalada de Espiel (Sectores de la Sierra del Castillo)','Un auténtico icono de la aventura en el sur de España y un gran referente nacional. Es una inmensa muralla de roca caliza de excelente adherencia situada junto al embalse de Puente Nuevo. Cuenta con un equipamiento exhaustivo, homologado y revisado de forma continua por la federación y colectivos locales. Su orientación permite escalar durante todo el año, lo que atrae a escaladores de toda Europa y sirve de base de operaciones fija para múltiples técnicos deportivos y empresas de formación en montaña. Posee zonas reguladas temporalmente por nidificación de avifauna.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14039','activo','Vía Ferrata de Luque (Tajo del Algarrobo)','Instalación de rango local/ regional ubicada en las estribaciones de las Sierras Subbéticas. El recorrido discurre por una aguja caliza calcárea con un equipamiento de seguridad moderno que incluye grapas tratadas contra la corrosión y una línea de vida continua. Cuenta con pasos de notable verticalidad pero sin desplomes atléticos, lo que la convierte en una infraestructura ideal para cursos de técnicos de senderismo que dan el salto a las vías ferratas y para el guiado comercial de iniciación en la provincia de Córdoba.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14055','activo','Vías Ferratas de Priego (Ferrata del Esparragal y Ferrata de la Tiñosa)','Destino de prestigio regional con proyección nacional. La red de ferratas del municipio ofrece desde itinerarios asequibles hasta tramos severamente desplomados en las proximidades del pico más alto de la provincia (La Tiñosa). Las instalaciones cuentan con puentes colgantes de cables y pasos técnicos que exigen el uso de disipadores de energía de última generación y guantes de protección. Su gestión está coordinada con los planes de protección del Parque Natural de las Sierras Subbéticas, requiriendo registro previo para el control de accesos de las empresas comerciales. Hemos completado exhaustivamente las provincias de Cádiz y Córdoba, aplicando el filtro estricto de excluir cualquier actividad que no sea de aventura técnica en roca o agua. Siguiendo el orden alfabético de Andalucía, la siguiente provincia es Granada (que cuenta con grandes iconos como el Barranco de Trevélez, Poqueira o la Ferrata de Loja). ¿Procedemos con el bloque único de la provincia de Granada?.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90495','activo','Vía Ferrata de Alicún de Ortega (Tajo de las Palomas)','Infraestructura de rango local y de carácter emergente situada en el norte provincial, integrada en el Geoparque de Granada. Está equipada sobre paredes de caliza fosilífera y cuenta con una progresión vertical limpia, un puente tibetano de unos 15 metros y pasos aéreos bien asegurados con línea de vida continua. Su uso principal está enfocado al dinamismo del turismo rural local y a bautismos de altura para empresas que operan con clientes de la comarca de Guadix y Baza.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18047','activo','Tramo Técnico del Río Genil (Cenes de la Vega a Granada capital)','Formato de prestigio regional debido a su dependencia directa del deshielo alpino de Sierra Nevada durante la primavera. Es un tramo fluvial corto y rápido, con fuerte pendiente y obstáculos de bloques de piedra que exigen maniobras de navegación precisas. Utilizado de forma intensa por los clubes locales de piragüismo y empresas de aventura durante los meses de mayo y junio para cursos de aguas bravas antes de que el caudal descienda de nivel en el periodo estival.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18116','activo','Barranco del Río Lanjarón (Tramo técnico) y Vía Ferrata de Lanjarón','Referente nacional de aventura. Su barranco es un descenso de alta montaña con un régimen hídrico muy severo marcado por el deshielo y aguas frías, con rápeles técnicos expuestos a la fuerza de la corriente. La vía ferrata municipal complementa la oferta con un recorrido aéreo sobre esquistos que incluye puentes tibetanos y líneas de vida revisadas. Al ubicarse en el Espacio Natural de Sierra Nevada (Parque Natural y Nacional), la actividad de las empresas está sujeta a una estricta declaración responsable y control ambiental de grupos.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18122','activo','Vía Ferrata de Loja (Cueva de los Gorriones)','Prestigio regional con alto tráfico de guiado comercial. La instalación destaca por su espectacularidad geológica al rodear formaciones kársticas y cuevas abiertas en el Tajo de los Gorriones. El tramo avanzado es sumamente físico, con un desplome prolongado que pone a prueba la fuerza de brazos y la técnica de progresión con bagas de disipación. Dispone de un puente de cables de gran longitud suspendido a gran altura, atrayendo de forma recurrente a empresas de la zona centro de Andalucía.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18134','activo','Escuela de Escalada de Los Cahorros de Monachil','Gran referente nacional y uno de los destinos históricos de escalada en roca más famosos de España. Un cañón de caliza caliza y dolomítica con paredes verticales y desplomes de renombre internacional. Cuenta con centenares de vías equipadas con los máximos estándares técnicos. La fisonomía del cañón, cruzada por puentes colgantes peatonales (turísticos), obliga a las empresas de turismo activo a realizar una logística limpia y coordinada para no interferir con los senderistas. Es el centro operativo de formación técnica y entrenamiento de los mejores escaladores de la región.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18147','activo','Barranco del Río Poqueira (Tramo inferior)','Gran referente nacional rozando el impacto internacional por su extremada exigencia. El río Poqueira recoge las aguas de las cumbres más altas de Sierra Nevada (Mulhacén y Veleta). Este tramo es un descenso alpino sumamente peligroso con caudales elevados, caracterizado por movimientos de agua violentos (rebufos, dromos y sifones), rápeles guiados obligatorios y pasos estrechos de alta presión hídrica. Solo es abordable de forma comercial por empresas con guías con titulación técnica superior (TD2/TD3) y clientes experimentados a finales de verano o principios de otoño. Requiere permisos ambientales obligatorios.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18148','activo','Barranco de Río Verde','Impacto Internacional / Icono de Aventura. Río Verde es considerado unánimemente el mejor barranco de carácter calizo y aguas cristalinas de todo el sur de Europa. Cuenta con un caudal permanente garantizado todo el año, aguas templadas de tonalidades turquesas, saltos técnicos de hasta 12 metros, toboganes naturales de gran longitud y rápeles espectaculares (como la mítica cascada de la Yedra o el rápel de los de la doble cascada). Alberga una densidad masiva de empresas de turismo activo que operan diariamente de marzo a octubre. El acceso terrestre está regulado mediante una cooperativa local de propietarios y la Junta de Andalucía, existiendo una tasa de control de capacidad de carga ecoturística.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18164','activo','Vía Ferrata de la Sagra (Piedra de la Rendija)','Instalación técnica de prestigio regional debido a su aislamiento geográfico y su entorno alpino a los pies del macizo de La Sagra. Su trazado aprovecha los callejones rocosos y fisuras de la Piedra de la Rendija, ofreciendo pasos aéreos con un equipamiento de acero de alta calidad y un puente de tablas suspendido. Exige una planificación climatológica rigurosa al tratarse de una zona propensa a nevadas y vientos severos en época invernal. Utilizada por los guías de montaña para programas de progresión en entornos aislados.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18180','activo','Barranco del Río Trevélez','Impacto Internacional / Icono de Aventura. Es uno de los descensos más peligrosos, técnicos y respetados de toda la península ibérica. Sus aguas ferruginosas de color rojizo ocultan por completo la visibilidad del fondo, lo que obliga a una lectura de corrientes y movimientos de agua perfecta. Sus estrechos son auténticas trampas hidráulicas con rápeles bajo cascadas atronadoras y pasillos con movimientos muy hostiles. Exige un nivel deportivo excepcional y equipos de rescate autónomos. El volumen de guías que operan comercialmente es muy reducido debido a la extrema siniestralidad si no se domina el caudal. Protegido rigurosamente bajo las leyes del Parque Nacional de Sierra Nevada.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18184','activo','Escuela de Escalada del Azud (Tajos de la Virgen) y Barranco de la Luna','Formato de prestigio regional. Los Tajos de la Virgen ofrecen paredes calizas de gran calidad a escasos kilómetros de la costa, ideales para la escuela de escalada invernal y cursos formativos de técnicas avanzadas. Por su parte, el Barranco de la Luna es un estrecho kárstico efímero de enorme belleza geológica que, aunque técnicamente sencillo, requiere el uso de cuerdas y técnicas de oposición en pasillos sumamente angostos. Muy explotado comercialmente por las empresas de aventura de la Costa Tropical debido a su alta rentabilidad logística y atractivo visual. Hemos completado la provincia de Granada integrando sus grandes colosos y descartando los municipios carentes de infraestructuras técnicas reguladas en roca y agua. Siguiendo el orden alfabético estricto de las provincias de Andalucía, la siguiente es Huelva (con entornos fluviales e instalaciones de aventura más limitadas pero existentes). ¿Procedemos con el bloque único de la provincia de Huelva?.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22001','activo','Vía Ferrata de Almonaster la Real (Cerro de San Cristóbal)','Instalación de rango local construida sobre un afloramiento de roca compacta en las proximidades del Cerro de San Cristóbal. Cuenta con una línea de vida continua de cable de acero inoxidable y escalones de progresión homologados que salvan un desnivel vertical modesto. Dispone de un pequeño puente colgante de cables que aporta sensación aérea. Al estar dentro del Parque Natural de la Sierra de Aracena y Picos de Aroche, su gestión medioambiental vigila que la afluencia de usuarios no interfiera con las aves locales. Es un recurso emergente explotado por empresas de aventura para grupos escolares y turismo familiar técnico que busca una aproximación segura a la verticalidad.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21067','activo','Zona de Escalada de los Riscos de Levante y Barranco Fluvial del Bosque de las Letras (Tramo de rápel regulado de los Chorros de Joyarancón)','Infraestructura de carácter local y emergente. Los Riscos de Levante ofrecen pequeñas paredes equipadas para la práctica de la escalada deportiva de baja dificultad con anclajes modernos para la formación básica de nudos y aseguramiento. En las inmediaciones, el salto de agua estacional de los Chorros de Joyarancón cuenta con reuniones equipadas con parabolts en su cabecera para permitir la práctica técnica del rápel sobre pared vertical húmeda tras lluvias intensas. La instalación está sujeta a la normativa de ordenación turística del ayuntamiento y del Parque Natural, funcionando como el principal núcleo de formación técnica en roca de la comarca serrana onubense. Hemos completado la provincia de Huelva, habiendo purgado y descartado todos los municipios que solo poseen atractivos de senderismo simple o turismo paisajístico sin instalaciones técnicas homologadas. Siguiendo el orden alfabético de las provincias de Andalucía, la siguiente es Jaén (un coloso de la roca y el agua gracias a las Sierras de Cazorla, Segura y Las Villas y la Sierra Mágina). ¿Procedemos con el bloque único de la provincia de Jaén?.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23018','activo','Escuela de Escalada de Cambil (Sectores del Frente de Cambil)','Destino calizo de gran relevancia en el ámbito regional y andaluz, ubicado en Sierra Mágina. Cuenta con desplomes técnicos de continuidad y placas verticales perfectamente equipadas con parabolts y reuniones homologadas. Su regulación ambiental está sujeta a restricciones temporales por la Consejería de Sostenibilidad y Medio Ambiente para salvaguardar la nidificación de rapaces. Las empresas de guiado utilizan estos sectores de forma habitual para cursos de perfeccionamiento en roca y escalada de continuidad.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23028','activo','Barranco del Río Cerezuelo y Vía Ferrata de la Mocha','Prestigio regional e importante motor comercial. El barranco del Cerezuelo es de carácter estacional, con un entorno encajonado de gran belleza caliza y rápeles cortos que no superan los 12 metros. La Vía Ferrata de la Mocha ofrece un recorrido aéreo espectacular sobre una cresta rocosa caliza, equipada con un puente tibetano e impecables líneas de vida. Ambas infraestructuras se localizan dentro del Parque Natural, por lo que las empresas de turismo activo operan bajo estrictas autorizaciones previas y cupos específicos diarios que gestiona la oficina medioambiental local.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23030','activo','Barranco de la Cerrada de la Canaliega','Cañón calizo estacional de formato técnico provincial y regional. Ofrece una progresión encajonada con una sucesión de rápeles secos en verano y con caudal dinámico en primavera, exigiendo un rápel máximo de unos 20 metros en cabeceras expuestas. Su equipamiento técnico cuenta con instalaciones fijas de anclajes aprobados por la federación de montaña. Su gestión logística está estrechamente coordinada con los guardas forestales del parque debido a la susceptibilidad de los accesos terrestres en zonas boscosas protegidas.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23034','activo','Vía Ferrata del Desfiladero del Guadalhorce (Sector Fuensanta)','Instalación de promoción municipal y rango eminentemente provincial. Dispone de un itinerario vertical limpio sobre paredes de roca caliza compacta con un equipamiento de acero inoxidable moderno. El recorrido añade un puente tibetano corto y pasos ligeramente desplomados que requieren buena tracción de brazos. Sirve como centro base de iniciación y entrenamiento logístico para clubes de la provincia y pequeñas agencias que organizan salidas técnicas de media jornada de duración.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23043','activo','Barranco del Arroyo de la Garganta','Destino de gran prestigio en la sierra segureña. El barranco es un descenso encajonado y muy geológico con rápeles técnicos, el mayor de los cuales alcanza los 25 metros de altura en caída vertical. Requiere una adecuada gestión de cuerdas en cabeceras húmedas. Las operaciones comerciales están reguladas de manera minuciosa por el Parque Natural de Cazorla, Segura y Las Villas, exigiendo declaración responsable. Su morfología técnica atrae a deportistas experimentados de toda la comunidad andaluza y de la Región de Murcia.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23050','activo','Escuela de Escalada de Reguchillo y Barranco de la Mella','Grande referente nacional en el sector de la roca. La pared caliza de Reguchillo es una de las escuelas de escalada más célebres del sur de España, albergando cientos de vías con equipamiento técnico homologado y actualizado. El Barranco de la Mella aporta valor técnico con rápeles verticales e independientes sobre roca caliza desértica ideales para entrenar fraccionamientos. Concentra una alta actividad formativa y es un núcleo logístico insustituible para empresas que titulan a guías de montaña de toda España, registrando alta afluencia anual.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23047','activo','Barranco de la Cerrada del Utrero y Vía Ferrata del Castillo de La Iruela','Gran referente nacional y uno de los mayores polos económicos de turismo activo de Jaén. La Cerrada del Utrero, excavada por el río Guadalquivir maduro, ofrece un caudal permanente regulado por el embalse superior, convirtiéndose en un descenso acuático continuo con saltos, toboganes y un rápel de 15 metros junto a la imponente cascada de Linarejos. La ferrata, que progresa bajo el cortado del histórico castillo, aporta un trazado aéreo técnico impecable. Los accesos están sujetos a una regulación estricta, cupos diarios rígidos y la obligatoriedad de que las empresas estén dadas de alta en el registro oficial de la Junta de Andalucía.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23060','activo','Escuela de Escalada de la Peña de Martos','Monolito calizo de prestigio regional que domina visualmente la comarca. Cuenta con itinerarios de escalada clásica autoprotegida y vías de varios largos, además de sectores de escalada deportiva totalmente reequipados con anclajes de seguridad. La regulación para escalar está supeditada a las directrices de Medio Ambiente por avifauna en las caras norte y noroeste. Es una infraestructura clave para la formación técnica en maniobras de varios largos y descensos en rápel en la provincia.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23070','activo','Barranco del Río Guadalentín (Tramos Superior e Inferior)','Impacto Internacional / Icono de Aventura. El tramo superior del Guadalentín es considerado uno de los cañones más espectaculares, oscuros y técnicos de España. Es un cañón kárstico de pasillos hiperencajonados ("caos de bloques") donde la luz solar apenas penetra, con rápeles encajados y movimientos de agua severos debido a las sueltas de la presa de la Bolera. Exige un dominio absoluto de técnicas de fortuna, instalación de pasamanos y lectura de turbulencias. Es operado comercialmente de forma muy selectiva por guías avanzados con clientes de nivel técnico contrastado. Es un recurso regulado con un estricto protocolo medioambiental y de seguridad.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23904','activo','Barranco del Río Segura (Nacimiento / Estrechos de la Cerrada de la Losa)','Grande referente nacional debido a la calidad de sus aguas y su encajonamiento geológico. La Cerrada de la Losa cuenta con un descenso alpino y calizo que arrastra aguas muy frías a gran presión en épocas de deshielo o lluvias fuertes, obligando al uso de técnicas de guiado de cuerdas y nado defensivo en estrechos de gran envergadura. Está sujeto a un exhaustivo control de permisos y autorizaciones por parte de las autoridades medioambientales del Parque Natural. Es explotado con regularidad por empresas especializadas en barrancos alpinos de toda la Península Ibérica.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23082','activo','Vía Ferrata de Siles (Peña del Olivar)','Infraestructura de rango local y desarrollo emergente en el límite septentrional del parque. Está bien equipada con peldaños de acero cincado y cables de seguridad que salvan una pared vertical con excelente roca. Dispone de pasos con notables vistas al valle pero sin exigencias físicas extremas. Muy vinculada a los programas de campamentos de aventura, turismo escolar de montaña y actividades guiadas por empresas locales para la dinamización técnica de la Sierra de Segura. Hemos completado íntegramente la provincia de Jaén, cribando todos los términos municipales y dejando únicamente aquellos con infraestructuras técnicas contrastadas en el sector de la roca y los deportes de aventura acuática. Siguiendo el riguroso orden alfabético global de las provincias de Andalucía, la siguiente es Málaga (donde se encuentran grandes enclaves técnicos como el Chorro, la Ferrata de Benaoján, el Caminito del Rey técnico o el Barranco de Almanchares). Si lo deseas, indícame si puedo proceder con el bloque provincial completo de Málaga.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32025','activo','Escuela de Escalada de El Chorro (Sectores compartidos: Las Encantadas, Poema Roca, Corral) y Vía Ferrata de El Chorro','Impacto Internacional / Icono de Aventura. El núcleo de El Chorro es un referente mundial de la escalada en roca. Cuenta con miles de vías perfectamente equipadas sobre caliza excelente. La Vía Ferrata incluye un puente tibetano, un puente de mono y una espectacular tirolina de más de 30 metros de longitud que requiere polea tándem de velocidad. Al estar ubicado en el Paraje Natural Desfiladero de los Gaitanes, las restricciones por nidificación de avifauna (buitre leonado, águila de Bonelli) son muy estrictas y están reguladas por la Junta de Andalucía. Concentra decenas de empresas de guías internacionales todo el año.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90443','activo','Vía Ferrata de la Pozancón','Instalación de formato técnico regional situada en la Serranía de Ronda. Se compone de un itinerario vertical muy estético sobre roca caliza que supera un desnivel de 50 metros. Cuenta con un puente tibetano intermedio y una salida atlética que exige una ligera tracción. Está regulada a nivel municipal y se utiliza con frecuencia por empresas locales como complemento técnico de media jornada combinado con el entorno espeleológico de la zona.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32002','activo','Vía Ferrata de El Torcal y Complejo de Escalada Deportiva','Destino de prestigio regional. La ferrata progresa de manera muy aérea sobre el característico paisaje kárstico de calizas tableadas. Presenta un desplome exigente de grado K4 que requiere fuerza de brazos y una correcta gestión de los cabos de anclaje. Al encontrarse junto al Sitio de los Dólmenes y el Paraje Natural de El Torcal, cuenta con una severa regulación medioambiental y arqueológica, requiriendo un estricto control de acceso y autorizaciones para las empresas de turismo activo.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32003','activo','Vía Ferrata del Cerro de la Virgen de Gracia','Instalación homologada de rango provincial y regional. Ofrece dos tramos bien diferenciados; el segundo es una variante deportiva con un paso extraplomado corto pero intenso. La infraestructura cuenta con cables de seguridad de acero inoxidable y peldaños ensayados contra fatiga. Es un recurso muy valioso para bautismos de altura y formaciones técnicas de clubes de montaña procedentes de las provincias de Málaga, Córdoba y Granada debido a su céntrica ubicación geográfica.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29021','activo','Vía Ferrata de Atajate','Infraestructura de rango local situada en el Valle del Genal. Destaca por contar con un puente de mono de 15 metros y un puente tibetano de 20 metros de longitud que aportan un fuerte carácter aéreo. Su nivel de esfuerzo físico es moderado, lo que la convierte en una instalación muy rentable para las empresas de aventura locales orientadas al guiado de grupos comerciales de iniciación técnica o perfeccionamiento básico en progresión horizontal y vertical.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29022','activo','Vía Ferrata de Benadalid','Gran referente nacional en la tipología de ferratas sumamente físicas y atléticas. Cuenta con un muro completamente vertical de 80 metros de altura sobre roca caliza compacta, jalonado por dos desplomes severos (extraplomos) consecutivos que exigen una excelente técnica de progresión, fuerza de core y uso de baga de descanso técnica. Homologada por la federación y regulada municipalmente, es un punto de paso obligado para deportistas avanzados y entrenamientos de técnicos de montaña.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29023','activo','Barranco de las Angosturas del Río Guadalmina','Formato de prestigio regional y uno de los cañones con mayor volumen de facturación comercial de Andalucía. Aunque técnicamente es sencillo en cuanto a rápeles (cuenta con uno de 4 metros opcional), es un cañón acuático permanente muy encajonado que exige tramos largos de natación obligatoria, pasos de oposición en paredes pulidas y saltos de hasta 5 metros a pozas profundas. Cuenta con un plan de autoprotección municipal y una regulación medioambiental que vigila de forma diaria la capacidad de carga debido al masivo flujo estival de agencias de la Costa del Sol.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29028','activo','Vía Ferrata de Benaoján (Ferrata Infantil y Ferrata del Nacimiento)','Destino calizo de gran relevancia en el entorno del Parque Natural de la Sierra de Grazalema. El tramo del Nacimiento cuenta con un desplome técnico a mitad de recorrido y un puente tibetano a gran altura perfectamente tensado. La presencia de la ferrata infantil homologada la convierte en una infraestructura única a nivel regional para la docencia y formación de menores en técnicas de seguridad vertical por parte de escuelas de montaña y empresas especializadas.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29033','activo','Barranco de Almanchares','Referente nacional de barranquismo en el Parque Natural de las Sierras de Tejeda, Almijara y Alhama. Es un descenso calizo de carácter estacional y torrencial que cuenta con más de una docena de rápeles consecutivos, destacando el colosal rápel final de 60 metros de altura completamente volado sobre la pared de la cascada. Exige un riguroso dominio de las maniobras de recuperación de cuerda y gestión de roces. Requiere obligatoriamente la autorización ambiental de la Junta de Andalucía para empresas y particulares.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29044','activo','Vías Ferratas de Comares (Ferrata de la Fuente Gorda, Cueva de la Ventana y Puerta del Agua) y Tirolina de Comares','Prestigio regional gracias a su completo entramado de infraestructuras de aventura en roca sobre el gran risco calizo que corona el pueblo. La red conecta tres ferratas distintas con puentes colgantes, pasos de repisa aéreos y una espectacular tirolina de 436 metros de longitud suspendida a más de 100 metros de altura (gestionada de forma regulada). Atrae un volumen constante de operaciones de turismo activo de toda la comarca de la Axarquía, sirviendo como modelo de gestión de infraestructuras de aventura municipales.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29046','activo','Cañón de las Buitreras (Tramo compartido / Acceso técnico)','Impacto Internacional / Icono de Aventura. Conocido como la "Catedral del Barranquismo Andaluz". Un desfiladero colosal excavado por el río Guadiaro con paredes verticales de más de 100 metros de altura y pasillos que apenas alcanzan un metro de anchura. Cuenta con rápeles técnicos, caos de bloques colosales, sifones, corrientes y tramos de nado sombríos e hiperencajonados donde el uso del neopreno completo es vital debido a la hipotermia. La regulación medioambiental exige permisos específicos de la Junta de Andalucía y prohíbe el acceso en determinadas épocas por protección del buitre leonado y crecidas torrenciales incontrolables por los embalses superiores. Solo operan guías de montaña de alto nivel técnico.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29049','activo','Vía Ferrata de Cuevas de San Marcos (Falla de la Sierra de la Camorra)','Instalación local bien equipada sobre calizas jurásicas de la Sierra de la Camorra. Dispone de tramos verticales escalonados, pasos de flanqueo lateral y un puente de cables corto. Su mayor interés radica en el entorno geológico de fallas tectónicas. Es explotada de forma regular por empresas locales para paquetes de multiaventura técnica que combinan la ferrata con el descenso en kayak o rafting en el tramo colindante del Río Genil.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29053','activo','Barranco del Río Higuerón','Formato de prestigio regional en la Axarquía. Cañón calizo caracterizado por sus llamativas formaciones de travertinos y rápeles encajonados que requieren el dominio de técnicas de cabecera. Lleva agua principalmente tras episodios lluviosos intensos de otoño e invierno. Su acceso terrestre y desarrollo de la actividad están supeditados a la normativa reguladora del Parque Natural de las Sierras de Tejeda, Almijara y Alhama, obligando a las empresas a tramitar el permiso ambiental correspondiente y controlar el volumen de los grupos guiados.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29056','activo','Vía Ferrata del Castillo del Águila','Gran referente nacional y una de las ferratas más espectaculares de España. El itinerario recorre las paredes de roca caliza situadas bajo el Castillo del Águila. Cuenta con una verticalidad absoluta, pasos extraplomados atléticos y, fundamentalmente, un puente de mono de cable de gran longitud extremadamente aéreo y expuesto al viento que requiere una gran resistencia psicológica y un uso impecable de los disipadores. Exige el pago de una tasa municipal o registro de seguridad gestionado por el ayuntamiento para el control de deportistas y empresas.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29060','activo','Vía Ferrata de Igualeja','Instalación de rango local en la cabecera del Río Genal. Ofrece un trazado vertical corto pero exigente, equipado con escalones de acero cincado y una línea de vida perfectamente anclada a la pared caliza. Carece de grandes puentes colgantes, pero cuenta con un pequeño desplome técnico que sirve para evaluar la capacidad física de los clientes de turismo activo antes de afrontar ferratas de mayor envergadura en la comarca rondeña.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29063','activo','Tramo Fluvial de Aguas Bravas del Río Guadiaro (Estación de Benaoján a Jimera de Líbar)','Prestigio regional. Es uno de los pocos tramos fluviales aptos para el descenso comercial de aguas bravas en balsa de rafting en la provincia de Málaga durante los meses de invierno y primavera. Presenta rápidos técnicos, pasos entre vegetación de ribera (trenes de olas) y zonas de maniobra de nado defensivo. Está estrictamente regulado debido a que discurre por el Parque Natural de la Sierra de Grazalema, exigiendo una coordinación de cupos y fechas para evitar el impacto ambiental sobre la fauna acuática del Guadiaro.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29074','activo','Vía Ferrata de Montejaque y Escuela de Escalada de la Cuenca del Hundidero','Referente nacional de primer orden. La Vía Ferrata es célebre por contar con una gran tirolina técnica (requiere polea específica y cabo de anclaje regulable) y una sección vertical con un fuerte extraplomo que exige una excelente fuerza en los brazos. Los sectores de escalada del Hundidero ofrecen muros calizos de dimensiones colosales con equipamiento de la máxima calidad. El espacio cuenta con severas restricciones medioambientales debido a la proximidad de la cueva del Hundidero, un enclave crítico para la protección de colonias de murciélagos cavernícolas.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29075','activo','Barranco del Río Chillar (Tramo superior encajonado / Los Cahorros técnicos)','Prestigio regional con un marco normativo muy estricto. A diferencia del tramo inferior netamente turístico y recreativo, los estrechos calizos superiores requieren equipos técnicos de progresión, calzado con alta adherencia para roca mojada calcárea pulida y gestión de la seguridad en pasillos donde las corrientes de agua pueden ser intensas tras tormentas en la sierra. Debido a la masificación histórica, el ayuntamiento y la Junta de Andalucía mantienen una regulación rigurosa sobre el acceso de empresas de turismo activo, prohibiendo temporalmente las actividades comerciales en épocas de sequía extrema o riesgo ecológico.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29084','activo','Vías Ferratas del Tajo de Ronda (Ferrata de la Sevillana y Ferrata del Tajo)','Grande referente nacional debido a su inigualable ubicación geológica y relevancia histórica (son consideradas de las primeras ferratas instaladas en Andalucía para los obreros de la luz). El recorrido discurre por el interior del monumental Tajo de Ronda, ofreciendo una perspectiva aérea impactante del puente y los muros verticales de más de 100 metros de altura. Totalmente reequipadas con líneas de vida e instalaciones modernas homologadas por las autoridades de turismo activo. Su uso comercial por empresas de guías de toda España es masivo, operando bajo normativas municipales estrictas de conservación del patrimonio histórico y paisajístico.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29096','activo','Escuela de Escalada de Villanueva del Rosario (Sector Chilam Balam)','Impacto Internacional / Icono de Aventura. Este municipio alberga la mítica vía "Chilam Balam", uno de los templos de la escalada deportiva mundial que atrae a los mejores escaladores de todo el planeta. Es una inmensa cueva caliza con techos y desplomes de estalactitas y chorreras infinitas que exigen una resistencia física y técnica extrema. Todo el equipamiento técnico está certificado con los estándares internacionales más exigentes de la FEDME y la IFSC. Cuenta con regulaciones específicas coordinadas por los colectivos locales y la administración ambiental para garantizar la limpieza de las líneas de roca y el control del vivac de los deportistas internacionales. Hemos completado exhaustivamente la provincia de Málaga, incluyendo todas sus infraestructuras técnicas certificadas en roca y agua y aplicando de forma inflexible las reglas de exclusión del proyecto. La siguiente provincia de Andalucía en orden alfabético global es Sevilla (la última de la comunidad, que cuenta con instalaciones muy específicas en la Sierra Norte). ¿Procedemos con el bloque provincial completo de Sevilla.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40001','activo','Vía Ferrata de Alanís (Cerro del Castillo)','Instalación de rango local y carácter promocional emergente, ubicada en el Parque Natural de la Sierra Norte de Sevilla. Presenta un trazado corto y de baja exigencia física sobre roca granítica, equipado con escalones de acero galvanizado y una línea de vida continua. Cuenta con un pequeño puente tibetano de unos 12 metros de longitud. Es utilizada de forma regular por empresas de la provincia para bautismos de altura, actividades escolares y cursos básicos de progresión vertical adaptados, funcionando bajo control de la normativa del espacio protegido.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41032','activo','Escuela de Escalada de Cazalla (Sectores de las Laderas del Huéznar)','Destino clásico de formato técnico regional para los escaladores de la provincia de Sevilla. Las paredes graníticas y calizas de las laderas del río Huéznar albergan más de 50 vías reequipadas con parabolts y reuniones de seguridad homologadas. La actividad está sujeta a la normativa ambiental del Parque Natural de la Sierra Norte, obligando a las agencias a verificar los periodos de nidificación de avifauna antes de operar con clientes entre febrero y junio. Es el principal centro de formación técnica para los clubes de montaña sevillanos.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41065','activo','Escuela de Escalada de la Sierra de Líjar (Sectores de la Cantera y Pared del Eco - Zona limítrofe)','Prestigio regional. Es un imponente macizo calizo situado en las estribaciones de la Sierra Sur que cuenta con una excelente calidad de roca caliza compacta. Ofrece itinerarios deportivos exigentes de continuidad y algunas líneas clásicas que requieren el uso de empotradores y "friends" para la autoprotección. Dispone de reuniones homologadas y anclajes químicos revisados por colectivos locales y la federación andaluza. Cuenta con una estricta regulación medioambiental de la Junta de Andalucía debido a la presencia de grandes colonias de buitre leonado.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41088','activo','Cerro del Hierro (Complejo Técnico de Escalada, Vía Ferrata y Espeleología de Aventura)','Gran Referente Nacional e icono de la aventura en la provincia de Sevilla. Es un antiguo paleokarst explotado como mina a cielo abierto, lo que ha generado un laberinto colosal de agujas calcáreas, túneles, pasadizos y paredes completamente verticales. Cuenta con una red de vías ferratas interiores adaptadas para la progresión en cavidades y simas, puentes de cable y más de un centenar de vías de escalada perfectamente equipadas. Al estar catalogado como Monumento Natural y Zona de Reserva del Parque Natural, su regulación es exhaustiva: las empresas de turismo activo deben disponer de autorizaciones previas del Parque, estar inscritas en el registro oficial y respetar rigurosamente los senderos técnicos delimitados para evitar la erosión y proteger la flora endémica. Con esta provincia damos por concluida oficialmente la Comunidad Autónoma de Andalucía, habiendo catalogado y puntuado alfabéticamente todas sus provincias y municipios con infraestructuras técnicas reales de roca y agua. Siguiendo el orden alfabético estricto de las Comunidades Autónomas de España, la siguiente es Aragón, que inicia con la provincia de Huesca (uno de los mayores núcleos de impacto internacional y cuna del barranquismo y la escalada en Europa, con enclaves como Alquézar/Guara, Broto/Ordesa o Benasque). ¿Procedemos con el bloque único de la provincia de Huesca para abrir la comunidad aragonesa?.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23001','activo','Río Cinca y Río Ara (Tramos de aguas bravas) y sectores de escalada de aventura asociados','Gran referente nacional y nudo logístico del pirineo central. El río Ara a su paso por el término ofrece uno de los mejores tramos de rafting virgen (sin presas) de la península, con rápidos técnicos que exigen maniobras de lectura hidráulica complejas durante el deshielo primaveral. Las empresas de turismo activo operan de forma masiva utilizando Aínsa como base de operaciones para distribuir clientes hacia los cañones de Añisclo y Bielsa. Cuenta con regulaciones de la Confederación Hidrográfica del Ebro (CHE).','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90272','activo','Barranco del Río Vero, Barranco de la Peonera, Barranco de Formiga y Pasarelas Técnicas del Vero','Impacto Internacional / Icono Supremo de Aventura. Epicentro mundial del barranquismo situado en el Parque Natural de la Sierra y Cañones de Guara. Alquézar concentra la mayor densidad de empresas de guías y deportistas internacionales de toda Europa central. El cañón del Vero es una colosal garganta kárstica con pasillos de caliza esculpida y caos de bloques gigantescos; la Peonera destaca por sus movimientos de agua técnicos (rebufos y sifones en las "Ancorchas"). La normativa ambiental de la DGA (Diputación General de Aragón) es exhaustiva: control de neoprenos, prohibición de grupos mayores a 10 personas y tasas específicas de control ecotustístico.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22054','activo','Barranco de Aigualluts, Vía Ferrata de Sacs y Escuela de Escalada de Benasque','Impacto Internacional / Icono de Aventura. Situado bajo el macizo del Aneto (Parque Natural Posets-Maladeta). La Ferrata de Sacs es una de las más alpinas y largas del Pirineo, salvando un desnivel vertical severo con equipamiento de alta resistencia al invierno. Los barrancos de la zona son de carácter netamente alpino: aguas gélidas procedentes directamente de glaciares, caudales extremos y rápeles bajo cascadas atronadoras que requieren dominio absoluto de nudos de liberación bajo tensión. Es la sede de los cursos de formación de guías de alta montaña de España (TD3).','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22058','activo','Barranco del Río Alcanadre (Tramo del Salto de Bierge y Gorgas Negras)','Impacto Internacional / Icono de Aventura. Bierge alberga el tramo de "Gorgas Negras", considerado el descenso de resistencia más técnico, largo y frío de la Sierra de Guara (entre 8 y 10 horas de actividad ininterrumpida en un desfiladero colosal). Requiere una logística militar y equipos de vivac de emergencia. La mítica cabecera del Salto de Bierge está fuertemente regulada por el Parque Natural de Guara y el ayuntamiento, con guardas forestales permanentes para controlar el acceso, los seguros de responsabilidad civil de las empresas de turismo activo y los cupos de entrada al río.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22057','activo','Barranco de Barrosa y Barranco de Trigoniero','Gran referente nacional con fuerte proyección europea. Situado en la frontera con Francia, el barranco de Barrosa es un icono del pirineísmo técnico: un descenso sobre granito con un caudal muy potente, toboganes naturales de gran velocidad y un rápel final técnico. Trigoniero complementa la zona con resaltes encajonados sobre esquistos. Toda la actividad empresarial se rige por las alertas hidrogeológicas del Pirineo, operando casi en exclusividad durante los meses de verano cuando descienden los caudales de deshielo.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22069','activo','Vía Ferrata de la Cascada de Sorrosal y Barranco de Sorrosal','Impacto Internacional / Icono de Aventura. Situado a las puertas del Parque Nacional de Ordesa y Monte Perdido. La Vía Ferrata de Sorrosal es una de las infraestructuras de aventura más espectaculares y fotografiadas del mundo; progresa directamente por el lateral de una cascada colosal de más de 100 metros de altura, superando formaciones geológicas de flysch mediante escaleras colgadas, un túnel interior excavado en roca y puentes tibetanos. El barranco superior exige técnicas avanzadas de rápel guiado en grandes verticales. La gestión está regulada por el ayuntamiento mediante el pago de una tasa ecológica obligatoria para el mantenimiento y seguro de las líneas de vida.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22074','activo','Río Ésera (Tramo de Aguas Bravas: Desfiladero de Olvena / Silla del Caballo)','Gran referente nacional para las actividades de aguas bravas. El tramo conocido como "La Pirámide" o "La Silla del Caballo" en el río Ésera ofrece trenes de olas colosales, rulos de gran fuerza hidráulica y contras muy marcadas que exigen un guiado experto en balsas de rafting comerciales. El régimen hídrico está garantizado durante todo el verano gracias a los desembolses programados de la central hidroeléctrica superior, convirtiendo a Campo en el epicentro comercial de aguas bravas de la comarca de la Ribagorza con una altísima densidad de empresas de turismo activo operando simultáneamente.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22078','activo','Barranco de los Estrechos de los Fayos y Escuela de Escalada de Canfranc','Prestigio regional. Ubicado en el valle del Aragón, el barranco de los Estrechos ofrece pasillos de roca caliza muy fríos, con rápeles técnicos expuestos a corrientes tras lluvias alpinas. Los sectores de escalada cuentan con equipamiento homologado y revisiones por parte de los colectivos de montaña de la Jacetania. La actividad logística empresarial está supeditada al control del entorno transfronterizo de los Pirineos y los planes de protección de los valles de alta montaña.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50185','activo','Río Gállego (Tramo de Aguas Bravas de Murillo a Santa Eulalia) y Vías Ferratas de los Mallos de Riglos (Entorno limítrofe)','Impacto Internacional / Icono de Aventura. El río Gállego a su paso por el monumental cañón de los Mallos de Riglos es el gran templo del rafting del oeste aragonés. Presenta rápidos legendarios como "El Embudo" o "La Sima", operando de forma continua de primavera a otoño mediante caudales regulados. En los muros del entorno se practica una de las escaladas de aventura en conglomerado más exigentes del mundo (con los famosos "bolos" de Riglos). Alberga una macroinfraestructura pública y privada de empresas de turismo activo y guías titulados. Cuenta con planes especiales de protección de aves rapaces (que prohíben la escalada en determinados mallos de enero a julio).','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22163','activo','Barranco de San Martín de la Val d''Onsera y Escuela de Escalada de Arguis (Entorno compartido)','Prestigio regional. San Martín de la Val d''Onsera es un descenso de carácter kárstico y seco de enorme espectacularidad visual, encajonado entre paredes colosales de conglomerado en la Sierra de Guara. Cuenta con rápeles volados muy técnicos de hasta 30 metros de altura que exigen dominio de cabeceras voladas. Las aproximaciones y retornos son duros, lo que eleva el compromiso logístico de los guías de turismo activo. Su uso está estrictamente regulado en el Plan de Ordenación de los Recursos Naturales (PORN) de la Sierra de Guara.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22170','activo','Vías Ferratas de Panticosa (Ferrata de Escalarilla y Ferrata de O Frato), Barranco del Caldarés y Barranco de Fornocal (Valle de Tena). *','Impacto Internacional / Icono de Aventura. El barranco del Caldarés es uno de los descensos graníticos más técnicos e intensos del Pirineo Aragonés, caracterizado por una pendiente brutal, rápeles en cascadas de gran presión hídrica y movimientos de agua muy peligrosos si el embalse superior desagua de forma imprevista. La Vía Ferrata de O Frato destaca por sus pasos extraplomados, un muro completamente vertical y desplomado calificado como K5 y un puente tibetano suspendido a gran altura sobre el vacío. La red de ferratas municipal requiere el registro y cumplimiento estricto del protocolo de seguridad de turismo activo aragonés.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22251','activo','Tramo Técnico del Río Flumen/ Alcanadre Bajo (Zonas de Kayak e iniciación técnica de aventura)','Instalación local emergente situada en el sur provincial (Monegros). Ofrece tramos regulados para la práctica del kayak de iniciación y técnicas de autorrescate fluvial sobre corrientes bajas. Su equipamiento técnico consiste en puntos de embarque homologados y controlados. No cuenta con un volumen masivo de guías profesionales fijos, pero sirve de desahogo logístico y formación para las empresas de la provincia de Huesca durante los meses en los que los ríos del Pirineo Central van saturados de caudal o cerrados por seguridad invernal. He unificado e integrado toda la provincia de Huesca en este bloque completo de la A a la Z, filtrando rigurosamente los destinos conforme a las normas de infraestructuras homologadas en roca y agua. La siguiente provincia de Aragón por orden alfabético estricto es Teruel (que alberga enclaves de gran nivel técnico regional y nacional como los estrechos del Guadalope, la Ferrata de Castellote o los barrancos de los Puertos de Beceite). ¿Me das el visto bueno para proceder con la provincia completa de Teruel?.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43001','activo','Escuela de Escalada en Bloque de Albarracín (Sectores de los Pinares de Rodeno)','Impacto Internacional / Icono de Aventura. Es uno de los templos de la escalada en bloque más importantes de todo el continente europeo. Sus estructuras de arenisca roja (rodeno) ofrecen desplomes, techos y romos de una calidad excepcional distribuidos en más de quince sectores homologados. La regulación medioambiental es extremadamente rigurosa al ubicarse en el Paisaje Protegido de los Pinares de Rodeno: está estrictamente prohibido el uso de magnesio líquido de baja calidad, el cepillado agresivo de la roca, escalar de noche y pernoctar fuera de zonas habilitadas. Cuenta con control permanente de agentes de protección de la naturaleza de la DGA y un volumen diario masivo de guías y escuelas internacionales.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44017','activo','Vía Ferrata del Parque Geológico de Aliaga (Ferrata de la Olla de Aliaga)','Formato de prestigio regional integrado en el Parque Geológico. El itinerario progresa sobre espectaculares estratos calizos verticales y subverticales del Cretácico. Cuenta con un puente tibetano suspendido a gran altura de unos 18 metros y pasos expuestos que exigen una buena gestión del material disipador. La infraestructura está homologada y mantenida con fondos municipales y comarcales, sirviendo de gancho de aventura técnica para empresas locales del Maestrazgo que complementan la actividad con rutas geológicas avanzadas.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44037','activo','Barranco del Matarraña (Estrechos del Parrizal - Tramo técnico superior) y Barranco de las Tinas','Destino de prestigio regional con proyección nacional en los Puertos de Beceite. El tramo superior del Parrizal ofrece pasillos calcáreos hiperencajonados con badinas profundas de nado obligatorio y rápeles técnicos sobre roca caliza erosionada. Cuenta con una estricta regulación de acceso y aforo gestionada por el ayuntamiento, requiriendo el pago de tasas de control y autorizaciones previas para empresas de turismo activo. Está terminantemente prohibido el baño libre recreativo fuera de los descensos técnicos regulados para salvaguardar el ecosistema fluvial y las colonias de cangrejo autóctono.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44071','activo','Vía Ferrata del Guadalope (Ferrata del Embalse de Santolea) y Agujas de las sotas','Grandes Referentes Nacionales. Es una de las ferratas más largas, aéreas y técnicas de la provincia, instalada sobre las impresionantes agujas rocosas calcáreas que flanquean el entorno del río Guadalope. Cuenta con un largo puente de tablas (tibetano), desplomes severos que ponen a prueba la resistencia de brazos y un tendido de cable de acero inoxidable certificado periódicamente según normativas europeas. Es un punto de atracción recurrente para clubes excursionistas avanzados y empresas de guías profesionales que operan en el Bajo Aragón.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44114','activo','Tirolina Gigante de Fuentespalda (Infraestructura técnica de aventura) y sectores menores de escalada','Prestigio regional por albergar la tirolina doble más larga de Europa en modalidad monocable, con 1.980 metros de longitud y más de 120 metros de altura sobre el suelo. Requiere un riguroso protocolo de seguridad homologado, uso de arneses de suspensión supina de alta resistencia, poleas industriales específicas para cable de alta tensión y sistemas automatizados de freno magnético en la torre de recepción. Su explotación comercial está regulada de forma estricta por inspecciones de ingeniería industrial y es un gran motor económico de aventura en la comarca del Matarraña.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44125','activo','Vía Ferrata de Huesa del Común (Ferrata del Castillo / Almadeo)','Infraestructura de formato técnico regional bien asentada. Cuenta con un puente de mono de 12 metros, un puente tibetano y un tramo de escalada limpia obligatoria integrada en la línea de vida de la ferrata. Los sectores de escalada anexos disponen de anclajes químicos revisados por colectivos locales de montaña. La regulación de uso obliga al registro y respeto de las colonias de aves rapaces que anidan en los paredones calcáreos opuestos al núcleo urbano durante la primavera.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44135','activo','Vía Ferrata de Libros (Peña del Mortero)','Instalación de rango local construida sobre los cortados de yesos y calizas de la Peña del Mortero, junto al cauce del río Turia. Dispone de escalones fijados con resina epoxi de alta resistencia, líneas de vida continuas bien distribuidas y un pequeño desplome técnico de salida. Es una infraestructura muy accesible durante todo el año, ideal para bautismos de altura y formación de técnicos deportivos de iniciación en la provincia de Teruel.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44171','activo','Escuela de Escalada del Estrecho de Olba (Valle del Mijares)','Prestigio regional con notable afluencia nacional, especialmente debido a su cercanía con la provincia de Castellón. Sus muros calizos de excelente adherencia a orillas del río Mijares ofrecen más de un centenar de vías reequipadas con anclajes químicos y parabolts certificados. Cuenta con restricciones temporales y zonas reguladas por nidificación de rapaces forestales controladas por la Consejería de Medio Ambiente aragonesa, sirviendo de base técnica estacional para empresas y escuelas de escalada de toda la Comunidad Valenciana y Aragón. Hemos completado la provincia de Teruel bajo los filtros más estrictos de este catálogo de aventura técnica en roca y agua. La siguiente provincia de Aragón por orden alfabético estricto es Zaragoza (la última de esta Comunidad Autónoma, con zonas técnicas clave como los Mallos de Murillo/Agüero limítrofes, Morata de Jalón o el Moncayo técnico). ¿Me autorizas a proceder con la provincia completa de Zaragoza.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50069','activo','Escuela de Escalada de Calcena (Sectores de la Cara Oculta del Moncayo) y Vía Ferrata de Calcena (Ferrata de la Sima)','Grandes Referentes Nacionales. Ubicada en el Parque Natural del Moncayo, es una de las escuelas de escalada más densas y completas de la provincia, con más de 450 vías equipadas sobre caliza excelente. La Vía Ferrata de la Sima complementa la zona con un recorrido técnico aéreo que introduce al deportista en una fractura geológica con pasos de oposición. Toda la actividad está sujeta a la estricta regulación del Plan de Ordenación de los Recursos Naturales (PORN) del Moncayo, con prohibiciones específicas de escalada en sectores sensibles de nidificación de avifauna entre febrero y agosto. Es la base de operaciones invernal de los clubes zaragozanos.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50175','activo','Escuela de Escalada de Morata de Jalón (Sectores de las Paredes de Alí, El Reloj y la Gran Placa)','Grandes Referentes Nacionales. Es la cuna histórica e indiscutible de la escalada en la provincia de Zaragoza. Sus imponentes paredes calcáreas a orillas del río Jalón albergan cientos de itinerarios totalmente reequipados con anclajes químicos y parabolts homologados por la Federación Aragonesa de Montañismo (FAM). Ofrece tanto escalada deportiva técnica de placa como itinerarios clásicos autoprotegidos de varios largos ideales para cursos de formación de Técnicos Deportivos en Montaña (TD). Cuenta con un protocolo medioambiental activo coordinado con el Gobierno de Aragón por protección de aves rapaces nidificantes (búho real y alimoche) en las paredes orientadas al cañón.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50192','activo','Escuela de Escalada de Nuévalos (Hoces del Río Piedra)','Formato de prestigio regional. El encajonamiento kárstico del río Piedra, aguas abajo del Monasterio de Piedra, ha esculpido unos muros de caliza rojiza de excelente calidad con desplomes y chorreras técnicas de gran continuidad física. Cuenta con reuniones con argolla y parabolts ensayados contra fatiga. Al tratarse de un ecosistema fluvial encajonado de gran fragilidad biológica, las empresas de turismo activo deben tramitar permisos anuales específicos ante la Delegación Territorial de Medio Ambiente para operar con grupos de alumnos o clientes guiados.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50221','activo','Vía Ferrata de Purujosa (Barranco de la Virgen)','Instalación de rango local y desarrollo regional estratégico para combatir la despoblación en el llamado "nido de águilas del Moncayo". Es una ferrata muy aérea pero excelentemente equipada sobre un espolón calizo calcáreo vertical. Cuenta con líneas de vida continuas de acero inoxidable y grapas bien dimensionadas que permiten una progresión limpia. El retorno técnico requiere descender por una canal pedregosa que exige calzado de alta montaña. Su gestión logística está integrada en las directrices ambientales del Parque Natural del Moncayo.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50243','activo','Vía Ferrata de Sestrica','Infraestructura de rango local promovida por el ayuntamiento en la Sierra de la Virgen. Dispone de un itinerario vertical sobre roca caliza compacta con un puente de cable corto y tramos aéreos bien asegurados. La variante avanzada introduce pequeños desplomes que exigen una correcta técnica de cambio de mosquetones en tensión. Es un recurso muy explotado por empresas de aventura de la comarca del Aranda para paquetes combinados de iniciación a las técnicas de progresión vertical en pared.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50264','activo','Escuela de Escalada de Tosos (Las peñas de Tosos / Entorno del Embalse de las Torcas)','Infraestructura caliza de prestigio regional consolidada sobre las caprichosas formas de conglomerado y caliza caliza que flanquean el río Huerva. Sus sectores ofrecen vías de adherencia y fisuras que requieren una buena gestión de la técnica gestual. El equipamiento ha sido revisado minuciosamente por colectivos locales para eliminar anclajes obsoletos. Cuenta con regulaciones medioambientales estrictas por nidificación de grandes rapaces asociadas a los cantiles rocosos del embalse, requiriendo parada biológica en varios sectores durante la primavera. Con esta provincia cerramos oficialmente la Comunidad Autónoma de Aragón, habiendo depurado todos sus municipios bajo la estricta premisa de admitir únicamente infraestructuras reales de roca y agua destinadas al turismo activo técnico. Siguiendo el estricto orden alfabético global de las Comunidades Autónomas de España, la siguiente es el Principado de Asturias. Al ser una comunidad uniprovincial.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05001','activo','Barranco del Río Dobra (Tramos del Sellaño y Carangas) y Vía Ferrata del Desfiladero de los Beyos (Tramo compartido)','Grandes Referentes Nacionales. El cañón de Carangas ofrece un descenso alpino severo con aguas hiperfrías, rápeles técnicos de hasta 30 metros bajo cascadas atronadoras y pasillos con fuertes corrientes de empuje. La vía ferrata de los Beyos, compartida en la garganta del río Sella, cuenta con un equipamiento de acero de máxima resistencia a la corrosión cantábrica, puentes tibetanos expuestos y desplomes atléticos. Al situarse en el entorno de los Picos de Europa, las autorizaciones ambientales de la Consejería de Medio Rural son rigurosas y exigen el registro oficial de las empresas de turismo activo operantes.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05004','activo','Escuela de Escalada de Sotres y Bulnes (Accesos a las caras del Naranjo de Bulnes / Pico Urriellu), y Barranco de Rumiada','Impacto Internacional / Icono de Aventura. Epicentro logístico de la escalada clásica de dificultad en España debido a las vías de acceso a las paredes del Picu Urriellu (Naranjo de Bulnes). Cuenta con itinerarios históricos de varios largos sobre caliza perfecta que requieren el uso exclusivo de empotradores, "friends" y gestión de reuniones en entornos de alta montaña aislados. El barranco de Rumiada aporta valor técnico con un descenso calizo encajonado de fuerte verticalidad. Al estar en el corazón del Parque Nacional de los Picos de Europa, la actividad empresarial está monitorizada al milímetro por los guardas del parque, estando prohibido el reequipamiento sin aprobación del comité técnico del Parque Nacional.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05005','activo','Río Sella (Tramo de Aguas Bravas superior: Puente de la Salmonera) y Barranco de la Molina','Grandes Referentes Nacionales. Es el núcleo neurálgico del turismo activo fluvial en el norte de España. El tramo superior del río Sella ofrece rápidos técnicos comerciales con trenes de olas muy marcados ("El Escañorio") ideales para el rafting de primavera. El barranco de la Molina complementa el término con badinas profundas de nado obligatorio y saltos técnicos a pozas. Las empresas operan bajo las normativas de la Confederación Hidrográfica del Cantábrico (CHC) y los planes de ordenación del Parque Nacional, regulando de forma férrea los puntos de embarque oficiales para no dañar las frezaderas de salmón.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90641','activo','Barranco del Río Nalón (Tramo superior / Desfiladero de los Arrudos)','Formato de prestigio regional ubicado en el Parque Natural de Redes (Reserva de la Biosfera). Es un descenso calcáreo y forestal sumamente técnico que exige una ventana climatológica muy precisa, ya que recoge de forma torrencial las lluvias de las cumbres de Redes. Cuenta con rápeles en cascadas encajonadas y pasajes estrechos propensos a sobrecaudales peligrosos. Las empresas de guiado deben tramitar un visado ambiental anual especial debido a la extrema protección de la fauna endémica de la cuenca alta del Nalón.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33035','activo','Escuela de Escalada de la Cantera de Santofirme','Infraestructura de rango local y emergente situada en el centro de la región asturiana. Se trata de un antiguo frente de cantera caliza recuperado y equipado de forma exhaustiva con parabolts y reuniones con mosquetón por federaciones y clubes asturianos. Al carecer de grandes desniveles o itinerarios clásicos de aventura, funciona como el principal centro docente para bautismos de escalada, prácticas de autorrescate en pared y entrenamientos de media jornada para agencias de la zona central de Asturias.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33038','activo','Escuela de Escalada de Otura (Monsacro)','Grandes Referentes Nacionales. Las impresionantes murallas de caliza gris del Monsacro albergan una de las escuelas de escalada deportiva de continuidad más exigentes y famosas del norte de España. Cuenta con sectores con chorreras, desplomes atléticos y placas técnicas perfectamente equipadas con químicos certificados. Dispone de regulaciones medioambientales estrictas coordinadas por el Principado de Asturias por la nidificación estacional de aves rapaces (águila real y alimoche), suspendiendo la escalada en las paredes orientadas al norte entre marzo y julio.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33046','activo','Vía Ferrata de El Mazuco y Escuela de Escalada de Alles','Prestigio regional con excelente proyección deportiva. La Vía Ferrata destaca por un trazado puramente vertical y muy aéreo que supera un resalte calizo expuesto mediante líneas de vida de alta tensión y peldaños cincados con tratamiento anti-humedad. Los sectores de escalada de Alles aportan líneas técnicas de placa de excelente adherencia caliza. Ambas instalaciones son reguladas comarcalmente para controlar el impacto en los valles del norte de Picos de Europa, sirviendo como núcleo de entrenamiento para técnicos e itinerarios guiados avanzados.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33050','activo','Barranco de Viboli, Barranco de Carangas (Tramo superior) y Vía Ferrata de Ponga','Impacto Internacional / Icono de Aventura. El barranco de Viboli es considerado uno de los grandes templos del barranquismo técnico en el norte de España: una garganta hiperencajonada con rápeles técnicos bajo cascadas brutales, resaltes resbaladizos de caliza pulida y un compromiso logístico extremo (una vez dentro no hay escapatorias posibles). La ferrata de Ponga complementa el entorno con un desplome deportivo severo y puentes de cable de gran longitud. Ubicado en el Parque Natural de Ponga, la actividad comercial se rige por un estricto cupo diario de deportistas y empresas registradas para proteger los ecosistemas fluviales de alta montaña.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33053','activo','Escuela de Escalada de Quirós (Sectores de El Llano)','Grandes Referentes Nacionales con alta proyección internacional. Quirós es la escuela histórica de escalada en roca de Asturias por excelencia. Sus inmensas placas e itinerarios de caliza gris perfecta cuentan con más de 300 vías totalmente equipadas y mantenidas por el refugio de montaña local y la federación asturiana (FEMA). Ofrece desde vías de varios largos autoprotegidas hasta placas técnicas de adherencia microscópica. Cuenta con un protocolo estricto de regulación de la Consejería de Medio Ambiente por nidificación de rapaces en los sectores superiores del Tenebredo, siendo el centro operativo base de formación de guías e instructores del norte del país.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33055','activo','Escuela de Escalada de La Hermida (Sectores compartidos / Entrada asturiana)','Formato de prestigio regional en el límite costero-montañoso de Asturias con Cantabria. Los contrafuertes calizos de la entrada al desfiladero de La Hermida ofrecen muros de excelente roca caliza muy compacta con equipamiento homologado mediante parabolts inoxidables de métrica 12. Al estar influenciada por la humedad costera cantábrica, exige una lectura precisa del tacto de la roca. Su uso comercial por agencias locales está regulado por las directrices ambientales del litoral y el desfiladero.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33064','activo','Vía Ferrata de Santo Adriano (Desfiladero de Buyera) y Escuela de Escalada de Tuñón','Prestigio regional. Ubicada estratégicamente en las inmediaciones de la Senda del Oso, esta infraestructura ofrece un recorrido técnico vertical equipado con escalones de acero cincado y línea de vida continua que supera un desnivel de 90 metros sobre roca caliza. Cuenta con un puente tibetano intermedio de 15 metros de longitud. La instalación está regulada municipalmente y es intensamente explotada por las empresas de turismo activo del centro de Asturias para bautismos de pared avanzada y eventos formativos corporativos.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33072','activo','Escuela de Escalada de Teverga (Sectores de Entrago, Vigas, Pared de la Estrechura)','Impacto Internacional / Icono de Aventura. Teverga es actualmente la mayor macroescuela de escalada deportiva de toda la cornisa cantábrica, atrayendo a escaladores de toda Europa durante todo el año gracias a sus variadas orientaciones. Alberga una inmensa concentración de muros calizos de todas las tipologías: desplomes de chorreras, placas de regletas y techos extremos perfectamente homologados y reequipados periódicamente con anclajes químicos de alta gama. Cuenta con regulaciones de estacionamiento de furgonetas camperizadas y vivac coordinadas con el ayuntamiento y el Parque Natural de Las Ubiñas-La Mesa, además de restricciones biológicas temporales por nidificación del oso pardo y rapaces en sectores específicos.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33034','activo','Barranco del Río Esva (Hoces del Esva - Tramo Técnico superior)','Instalación de rango local y formato provincial situada en el occidente asturiano. Lejos del karst calizo del oriente, este cañón progresa sobre cuarcitas y pizarras duras, ofreciendo un paisaje encajonado de gran belleza con rápeles cortos (resaltes máximos de 12 metros) equipados con reuniones fijas de acero inoxidable. Al estar catalogado como Monumento Natural de las Hoces del Esva, la actividad de las empresas está limitada a pequeños grupos controlados mediante permisos ambientales estacionales para evitar el impacto sobre las poblaciones de nutria y avifauna de ribera. Hemos completado el Principado de Asturias en un bloque exhaustivo de la A a la Z, filtrando con precisión de auditor todas las localidades activas. Siguiendo el orden alfabético estricto de las Comunidades Autónomas de España, la siguiente es las Islas Baleares (con la isla de Mallorca a la cabeza, un gigante del barranquismo calizo de impacto mundial y de la escalada en la modalidad de Psicobloc/ Deep Water Soloing en acantilados marinos). ¿Me concedes la autorización para proceder con el bloque único de las Islas Baleares?.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90018','activo','Escuela de Psicobloc de Cala Serena y acantilados de El Toro (Zonas técnicas de Deep Water Soloing)','Gran Referente Nacional con fuerte proyección internacional. Sus acantilados de roca caliza desplomada sobre el mar Mediterráneo ofrecen líneas espectaculares de escalada libre donde la única protección es la profundidad del agua (se exige comprobar batimetrías y fondos antes de operar). Las empresas de turismo activo gestionan la aproximación mediante embarcaciones tarteras o kayaks técnicos. Cuenta con regulaciones marítimo-terrestres estrictas por la Demarcación de Costas y el Parque Natural de la Isla del Toro para evitar la degradación de los nidos de cormorán moñudo.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90020','activo','Torrent de sa Coma (Barranco de sa Coma de Deià)','Destino de prestigio regional con alta exigencia física en la Sierra de Tramuntana. Es un cañón seco la mayor parte del año pero extremadamente vertical, caracterizado por una sucesión de más de 15 rápeles sobre caliza muy pulida, destacando un resalte vertical encajonado de 35 metros de altura. Al ser una torrentera de fuerte pendiente, el retorno técnico es duro. Requiere un control absoluto de las técnicas de recuperación de cuerdas. La normativa de la Consejería de Medio Ambiente balear exige permisos de acceso al discurrir por el Paraje Natural de la Serra de Tramuntana.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90654','activo','Torrent de Pareis (Sa Fosca), Torrent de Mortitx, Torrent de Na Mora y Vía Ferrata de Mortitx','Impacto Internacional / Icono Supremo de Aventura. El cañón de Sa Fosca (tramo superior del Torrent de Pareis) está catalogado en las guías técnicas europeas como uno de los barrancos más espectaculares, técnicos e impresionantes del planeta. Presenta un tramo central completamente subterráneo ("Fosca") de casi dos kilómetros donde la luz solar es nula, exigiendo progresión con frontales, neoprenos completos por aguas estancadas gélidas y una gestión psicológica extrema (compromiso V, sin escapatorias). El municipio suma Mortitx (con su ferrata de retorno técnica) y Na Mora (que desemboca directamente en el mar). La regulación del Gobierno Balear y del Plan de Ordenación de los Recursos Naturales (PORN) es total, exigiendo declaración responsable diaria, prohibición de grupos grandes y un seguro de rescate especial. Concentra empresas de guías de toda Europa.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90656','activo','Torrent de Son Galcerán (Barranco de Estellencs)','Grandes Referentes Nacionales. Es un cañón torrencial espectacular que cuenta con una sucesión de rápeles verticales, el mayor de ellos un salto colosal de 45 metros que deposita al barranquista directamente sobre la playa de cantos rodados del litoral. Exige una planificación marina milimétrica: si hay temporal de norte o tramontana, el oleaje impide el retorno técnico a pie por la costa o la recogida en embarcación, convirtiéndolo en una trampa. Operado de forma regular por empresas especializadas en aventura costera avanzada bajo los permisos regulatorios del Paraje Natural de la Serra de Tramuntana.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07012','activo','Escuela de Psicobloc de Porto Cristo (Sectores Cova del Diablo y Cala Barques)','Impacto Internacional / Icono de Aventura. La Cova del Diablo en Porto Cristo es considerada unánimemente la meca mundial de la escalada en modalidad de Psicobloc, popularizada a nivel global por leyendas de la roca como Chris Sharma. Ofrece muros colosales calizos de color anaranjado repletos de chorreras y techos horizontales perfectos suspendidos a más de 15 metros de altura sobre aguas profundas y limpias. La logística exige embarcaciones de seguridad (Zodiacs o tablas de SUP de rescate) por parte de las escuelas y guías profesionales. La regulación ambiental es estricta para evitar basuras y ruidos en las calas, estando monitorizado por los agentes de medio ambiente de las islas.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07017','activo','Torrent de Ternelles (Gorg Blau inferior), Escuela de Escalada de la Creveta y Es Pas de Mula','Grandes Referentes Nacionales con alta proyección internacional. El Gorg Blau es un desfiladero kárstico estrecho y sombrío que exige técnicas avanzadas de oposición y gestión de caudales regulados por las presas superiores de la isla. Por su parte, la pared de la Creveta en el Cap de Formentor ofrece placas de caliza gris de una adherencia excelente y equipamiento moderno revisado por la Federación Balear de Montañismo. Los permisos de acceso para Ternelles están estrictamente limitados a un cupo numerado bajísimo por propiedad privada y conservación del águila pescadora y el buitre negro, obligando a las empresas de turismo activo a reservar con meses de antelación.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07020','activo','Arco de Es Pontàs (Escalada técnica de Psicobloc de dificultad extrema)','Impacto Internacional / Icono de Aventura. Es Pontàs es un arco natural de roca caliza de dimensiones colosales que emerge exento directamente del fondo del mar. Alberga algunas de las líneas de Psicobloc más difíciles del planeta, caracterizadas por lanzamientos dinámicos al vacío y techos brutales a gran altura. No es apto para iniciación comercial; funciona como un centro de alto rendimiento natural para escaladores de élite mundial y rodajes de productoras de aventura. Su uso y aproximación están estrictamente regulados dentro de las directrices del Plan de Gestión de la Red Natura 2000 del litoral sur de Mallorca.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07023','activo','Torrent de Biniaraix (Barranco de l''Ofre)','Grandes Referentes Nacionales. Situado en pleno corazón del valle de Sóller, el barranco de l''Ofre es uno de los descensos acuáticos más bellos, estables y frecuentados de las Islas Baleares. Cuenta con una sucesión de rápeles técnicos bien equipados con químicos inoxidables (el mayor de 40 metros de altura en cascada), toboganes naturales y saltos limpios a pozas de agua transparente. Es la base de operaciones formativas y comerciales por excelencia de las agencias de turismo activo de la isla durante el invierno y la primavera. Exige la tramitación de la tasa y el permiso ambiental del Paraje Natural de la Serra de Tramuntana. Hemos completado exhaustivamente las Islas Baleares en este bloque único provincial, filtrando con rigurosidad de auditor y conservando solo las joyas de la roca vertical y los cañones profundos de las islas. Siguiendo el orden alfabético estricto de las Comunidades Autónomas de España, la siguiente es Canarias (un archipiélago de origen volcánico que alberga barrancos secos colosales de basalto negro pulido, rápeles kilométricos y escuelas de escalada de aventura sobre estructuras de fonolitas y traquitas). ¿Me autorizas a proceder con el bloque único de la Comunidad Autónoma de Canarias?.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38001','activo','Barranco del Infierno (Tramo superior técnico / Cárcavas de los Riscos)','Prestigio regional con estricto control de acceso. El cauce superior ofrece un descenso encajonado sobre lavas basálticas meteorizadas con una sucesión de rápeles que exigen un dominio preciso de los roces y cantos vivos de la roca volcánica. Al ubicarse en la Reserva Natural Especial del Barranco del Infierno, la normativa ambiental es de las más restrictivas de Canarias: el aforo diario está limitado al milímetro para evitar el impacto sobre los endemismos botánicos y la avifauna. Las empresas de turismo activo operan bajo cupos preestablecidos y autorizaciones específicas del Cabildo de Tenerife.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90626','activo','Barranco de Guayedra','Formato de prestigio regional. Es un descenso abrupto de carácter árido y volcánico que discurre en el noroeste de Gran Canaria, desembocando en el mar. Destaca por la espectacularidad de sus paredes basálticas y rápeles técnicos encadenados, con un resalte máximo que ronda los 28 metros. El compromiso logístico es elevado debido a las altas temperaturas estivales y la exposición a los vientos alisios. Requiere la correspondiente autorización del Cabildo de Gran Canaria al transcurrir por entornos protegidos.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90627','activo','Escuela de Escalada del Barranco de Guayadeque (Sectores de roca volcánica)','Grandes Referentes Nacionales. Es una de las escuelas de escalada más espectaculares y con mayor solera del archipiélago canario. Sus imponentes paredes de basalto y traquita ofrecen una escalada física sobre agujeros, desplomes y fisuras perfectas totalmente equipadas con parabolts y químicos inoxidables homologados. Su orientación en el cañón permite escalar todo el año, lo que atrae a deportistas nacionales e internacionales. Cuenta con regulaciones del Cabildo insular para proteger los importantes yacimientos arqueológicos aborígenes integrados en las cuevas del propio barranco, prohibiéndose la apertura de vías en áreas de valor patrimonial.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38032','activo','Vía Ferrata de El Pinsapo (Entorno de la Corona Forestal)','Infraestructura de rango regional bien equipada sobre paredes rocosas de origen volcánico en la zona de transición hacia la alta montaña de Tenerife. Dispone de un itinerario vertical limpio con escalones bien dimensionados y líneas de vida de alta tensión continuas. Cuenta con un pequeño puente colgante y pasos aéreos que sirven de excelente plataforma docente para las empresas que realizan cursos de iniciación a las técnicas verticales. Regulada por el área de Medio Ambiente del Cabildo de Tenerife dentro de la Corona Forestal.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38017','activo','Escuela de Escalada del Barranco del Río','Prestigio regional. Es uno de los sectores de escalada en roca más importantes de la vertiente sur de Tenerife, caracterizado por la presencia de una roca volcánica (ignimbrita y traquita) de coloración clara y excelente adherencia que difiere del basalto común. Ofrece vías de placa técnica y fisuras muy estéticas perfectamente reequipadas por los colectivos canarios y federaciones. Las empresas locales operan de forma continua durante los meses de invierno aprovechando el clima benigno de la zona.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38026','activo','Barranco de los Arcos de Chimoche','Grandes Referentes Nacionales. Es uno de los descensos más fotogénicos y famosos de toda España debido a su singularidad geológica. El barranco ha esculpido la toba volcánica de color naranja y ceniza, creando unos espectaculares arcos naturales y pasillos sinuosos ("cañones de ranura" al estilo americano) pulidos por el agua efímera. Cuenta con una decena de rápeles cortos e impecablemente equipados con químicos. Es un recurso explotado intensamente por todas las empresas de turismo activo de la isla. El acceso está estrictamente regulado mediante un sistema de autorizaciones digitales del Cabildo de Tenerife debido a la fragilidad del entorno de la Corona Forestal.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35012','activo','Vía Ferrata de Primera Luna (Extraplomo) y Ferrata de La Guagua (El Berriel - Zona limítrofe)','Impacto Internacional / Icono de Aventura. El suroeste de Gran Canaria alberga uno de los complejos de vías ferratas más difíciles, largos y exigentes del planeta. "La Guagua" es una ferrata de enormes dimensiones con más de 800 metros de recorrido equipado y pasos muy aéreos. Por su parte, los tramos de "Primera Luna" albergan techos y desplomes brutales calificados como K6 que exigen una fuerza de brazos extrema, material disipador de última generación y técnicas avanzadas de autorrescate en pared. Es un polo de atracción para deportistas de toda Europa central durante el invierno. Cuenta con regulaciones municipales y del Cabildo para asegurar la inspección periódica de los anclajes estructurales expuestos a la aridez del clima.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38023','activo','Barranco del Río (Anaga) y sectores de escalada en conglomerado volcánico','Prestigio regional con proyección nacional. Este descenso recoge las aguas de las cumbres de Anaga y ofrece un itinerario encajonado de gran envergadura con cascadas que requieren el uso dinámico de cuerdas y rápeles guiados para evitar movimientos de agua estacionales. Cuenta con reuniones dobles fijadas con resina epoxi de alta resistencia. La actividad empresarial requiere la tramitación previa de permisos en la Oficina del Parque Rural de Anaga, vigilando estrechamente el número de clientes por guía de montaña.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38036','activo','Escuela de Escalada de aventura de los Roques de la Gomera (Roque de Agando Restricciones severas / Vías clásicas de aventura)','Formato histórico de prestigio regional en el ámbito de la escalada clásica de aventura sobre fonolitas. El Roque de Agando y las estructuras de los domos volcánicos del entorno albergan itinerarios legendarios de varios largos abiertos por pioneros de la montaña. Actualmente, la regulación medioambiental es sumamente estricta y restrictiva por parte del Parque Nacional de Garajonay y el Cabildo de La Gomera, estando prohibida la escalada deportiva común y requiriéndose permisos científicos o deportivos especiales justificados de alta montaña debido a la protección de flora endémica rupícola única en el mundo y aves rapaces.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35021','activo','Barranco de las Goteras (Tramo técnico calderiforme). *','Instalación de rango local y emergente. Ofrece una fisonomía de cauce volcánico seco con rápeles cortos sobre resaltes basálticos encadenados que sirven de toma de contacto para las escuelas y clubes locales de la isla. Dispone de anclajes de seguridad revisados. Su uso comercial por agencias de turismo activo es moderado, actuando principalmente como un recurso de proximidad para formaciones de técnicos y maniobras básicas de progresión vertical seca en la comarca centro-oriental de Gran Canaria.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35025','activo','Escuela de Escalada del Roque Nublo y sectores asociados de la Caldera de Tejeda','Grandes Referentes Nacionales e icono sagrado de la geografía canaria. El Roque Nublo es un colosal monolito de brecha volcánica de 80 metros de altura que se alza sobre la gran Caldera de Tejeda. Alberga vías clásicas históricas de varios largos de enorme exposición y exigencia psicológica (como la mítica vía Alemana), que requieren el uso de empotradores, "friends" y la gestión del viento en reuniones suspendidas en el vacío. Su regulación por parte del Cabildo de Gran Canaria prohíbe taxativamente cualquier modificación del equipamiento histórico y vigila estrictamente las actividades de las empresas para salvaguardar el Monumento Natural y el Paisaje Protegido de las Cumbres. Hemos completado la Comunidad Autónoma de Canarias en este bloque unificado de la A a la Z, filtrando rigurosamente todas las localidades y manteniendo exclusivamente los grandes templos del basalto vertical y las torrenteras volcánicas de las islas. Siguiendo el orden alfabético estricto de las Comunidades Autónomas de España, la siguiente es Cantabria (un territorio colosal del norte peninsular marcado por el karst calcáreo profundo, el desfiladero de La Hermida, grandes circuitos de vías ferratas de gran longitud y ríos caudalosos de montaña). ¿Me das la conformidad para proceder con el bloque único provincial de Cantabria?.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90636','activo','Barranco del Río Asón (Nacimiento), Barranco de Socueva y Vía Ferrata de Socueva','Grandes Referentes Nacionales. Capital del karst cántabro. La Vía Ferrata de Socueva es un itinerario sumamente físico, famoso por un primer muro vertical y desplomado (K5) que exige gran resistencia y el uso de técnicas de descanso activo. El barranco del nacimiento del Asón destaca por sus rápeles bajo cascadas de gran presión hídrica. Ubicado en el Parque Natural de los Collados del Asón, las actividades están reguladas por la Consejería de Desarrollo Rural, Ganadería, Pesca y Alimentación de Cantabria, requiriendo comunicación previa para empresas de turismo activo y controlando la capacidad de carga.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39015','activo','Vía Ferrata de Los Llanos (Camaleño) y sectores de escalada de aventura de los Picos de Europa','Destino de prestigio nacional en la comarca de Liébana. La Ferrata de Los Llanos ofrece tres tramos bien diferenciados con puentes tibetanos y una línea de vida continua de última generación. Su uso comercial por parte de las empresas que operan en el entorno de Fuente Dé es muy elevado. Al encontrarse en el área de influencia del Parque Nacional de los Picos de Europa, la infraestructura cumple rigurosas normativas de integración paisajística y seguridad técnica, monitorizadas de forma periódica por el ayuntamiento y técnicos de montaña.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39022','activo','Vía Ferrata de la Hermida (Tramo de Cillorigo / Puentes colgantes), Escuela de Escalada del Desfiladero de la Hermida (Sectores compartidos) y Río Deva','Impacto Internacional / Icono de Aventura. Este municipio alberga gran parte de la mítica Vía Ferrata de La Hermida, la primera instalada en Cantabria, célebre por sus kilométricos cables de acero y sus impresionantes puentes tibetanos y de mono suspendidos a más de 100 metros sobre el río Deva. Sus sectores de escalada en caliza gris atraen a deportistas europeos durante todo el año. Las empresas de turismo activo explotan el río Deva de forma masiva para rafting comercial. Toda la actividad está coordinada bajo un plan técnico ambiental riguroso de la Red Natura 2000 por la conservación del salmón atlántico y aves rapaces.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39045','activo','Escuela de Escalada de Miera (Sectores de el Resconorio) y Vía Ferrata de el Muro de Peñarrubia (Entorno compartido)','Prestigio regional. El Valle del Miera ofrece impresionantes murallas calizas que configuran una escuela de escalada muy técnica con equipamiento homologado en expansión. Las líneas de vida e instalaciones verticales están revisadas por la Federación Cántabra de Deportes de Montaña y Escalada (FCDME). Cuenta con paradas biológicas temporales decretadas por el Gobierno de Cantabria debido a la nidificación de aves rupícolas (alimoche y buitre leonado), obligando a las empresas a consultar el boletín oficial de restricciones de la cornisa de forma estacional.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39049','activo','Vía Ferrata de El Maza (La Hermida) y Vía Ferrata de El rastrojo','Grandes Referentes Nacionales. Ubicada estratégicamente en el corazón del Desfiladero de La Hermida. La ferrata de El Maza (también conocida como de la Escalera al Cielo) destaca por un tramo vertical expuesto y una imponente escalera de peldaños colgada al vacío que genera un fuerte compromiso psicológico. Cuenta con una exhaustiva revisión de ingeniería estructural de cables y anclajes químicos epoxi debido a las rigurosas condiciones climáticas invernales del norte. Las empresas locales operan de manera continua bajo autorizaciones y tasas de mantenimiento municipal.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39055','activo','Centro Logístico de Guías de los Picos de Europa / Accesos Técnicos a los Barrancos de Liébana (Barranco de Navedo y Barranco de Cicera)','Impacto Internacional / Icono de Aventura. Aunque los cañones se distribuyen físicamente por los valles colindantes de la comarca, Potes es la capital indiscutible de los deportes de aventura de los Picos de Europa y el centro receptor masivo de deportistas de toda Europa. El barranco de Navedo es un cañón de caliza pulida con un caudal permanente muy divertido, toboganes rápidos y un rápel de 20 metros muy técnico. Alberga la mayor concentración de empresas de guías titulados (TD2) del norte de España. Las regulaciones medioambientales vigilan la capacidad de carga de los ríos de Liébana de forma diaria en época estival.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39057','activo','Escuela de Escalada de Ramales (Pared de la Eco, el Calera) y Vías Ferratas de Ramales (Ferrata de El Cáliz y Ferrata de El Espejo)','Grandes Referentes Nacionales con proyección internacional. Ramales es uno de los santuarios de la roca en el norte peninsular. La Vía Ferrata de El Espejo es corta pero de una dificultad técnica extrema debido a su total verticalidad y a un desplome severo (K4+) sobre caliza compacta que requiere fuerza de brazos y el uso obligado de tercera baga de descanso. Los sectores de escalada cuentan con equipamiento impecable mediante tensores químicos. Existe una estrecha vigilancia y regulación por nidificación de rapaces forestales regulada por la Consejería de Medio Ambiente.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39067','activo','Barranco del Río Gándara y Complejo de Espeleología Técnica del Valle de Matienzo (Entorno compartido)','Grandes Referentes Nacionales. El cañón del río Gándara ofrece un descenso de fuerte caudal estacional con espectaculares badinas, nado en corrientes y saltos técnicos a pozas profundas que exigen un buen nivel de natación defensiva. El entorno kárstico del subsuelo es un referente internacional para la espeleología técnica y el entrenamiento de técnicas de progresión vertical con bloqueadores (Croll y Jumar). Regulado de forma estricta por la Confederación Hidrográfica del Cantábrico y los planes de protección de cuencas del norte.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39072','activo','Barranco de Aján (Tramos Superior e Inferior)','Formato de prestigio regional consolidado en los Valles Pasiegos. El barranco de Aján es un clásico del norte peninsular tallado sobre calizas y areniscas duras. Ofrece un recorrido muy dinámico y acuático con rápeles técnicos encajonados de hasta 15 metros, saltos expuestos y toboganes naturales de gran velocidad según la época del año. Exige una lectura hidráulica precisa debido a las crecidas repentinas asociadas al clima atlántico. Las empresas operan de forma regular bajo las directrices ambientales del Gobierno de Cantabria.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39094','activo','Río Ebro (Tramo de Aguas Bravas del Cañón del Ebro / Ruerrero)','Prestigio regional en el extremo sur de Cantabria. El río Ebro se encajona en este término ofreciendo trenes de olas, rebufos y corrientes marcadas aptas para el descenso técnico comercial de balsas de rafting. Su caudal está completamente garantizado durante los meses de verano gracias a la regulación hidroeléctrica del Embalse del Ebro, convirtiéndose en un recurso técnico valioso para las agencias cántabras y castellanas. Regulado por la Confederación Hidrográfica del Ebro (CHE).','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39097','activo','Barranco de Yera (Tramos del túnel de la Engaña) y zonas de rápel técnico asociadas. *','Instalación de rango local en el corazón pasiego. Es un descenso calizo estacional que destaca por su entorno paisajístico y rápeles cortos que sirven de aproximación formativa. Cuenta con anclajes inoxidables instalados por colectivos de montaña locales. Su explotación comercial se concentra en la primavera y el otoño, periodos en los que el caudal es el idóneo para cursos de iniciación al turismo activo de aventura en roca y agua, respetando las directrices de los planes forestales de la comarca. Hemos completado la Comunidad Autónoma de Cantabria de forma rigurosa, listando únicamente las localidades con instalaciones técnicas reales y descartando los destinos meramente recreativos. Siguiendo el orden alfabético estricto de las Comunidades Autónomas de España, la siguiente es Castilla-La Mancha (un territorio inmenso que inicia con la provincia de Albacete, poseedora de grandes enclaves de roca y agua como el cañón del río Mundo, el río Júcar técnico o las escuelas de escalada de Ayna). ¿Continuamos con el bloque único de la provincia de Albacete?.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02003','activo','Río Júcar (Cañón de las Hoces del Júcar - Tramo técnico de aguas bravas) y Barranco del Tranco del Lobo (Entorno compartido)','Destino de prestigio regional y gran motor económico del turismo activo en Albacete. Las profundas hoces del río Júcar ofrecen un tramo de corrientes dinámicas, trenes de olas y rulos técnicos regulados por los desembolses de las centrales hidroeléctricas superiores, garantizando caudal técnico en la época estival. El barranco seco asociado cuenta con instalaciones homologadas de rápel sobre caliza. Concentra un alto volumen de empresas de guías profesionales. La actividad está regulada por la Confederación Hidrográfica del Júcar (CHJ) mediante declaraciones responsables estrictas.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02006','activo','Escuela de Escalada de Ayna (Sectores de la Pared de los Espejos, El Estrecho y Cañón del Mundo)','Grandes Referentes Nacionales. Conocida técnicamente como "La Suiza Manchega", es la escuela de escalada en roca caliza más importante y clásica de la provincia de Albacete. Sus muros verticales y desplomados flanquean de forma espectacular el río Mundo, ofreciendo líneas de continuidad sobre una caliza de excelente adherencia y tacto. La infraestructura de anclajes cuenta con químicos y parabolts homologados mantenidos por el colectivo local y la federación castellano-manchega. Dispone de una estricta regulación ambiental coordinada con la delegación provincial de Desarrollo Sostenible debido a la nidificación de grandes aves rapaces (águila real y buitre leonado), clausurando sectores sensibles de febrero a julio.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90343','activo','Barranco del Arroyo del Madera y zonas de escalada deportiva menores','Formato técnico de prestigio regional en la Sierra del Segura. El barranco es de carácter torrencial y calizo, destacando por su entorno encajonado de pinar que exige una planificación milimétrica respecto a las lluvias estacionales. Cuenta con una sucesión de 6 rápeles técnicos (con un resalte máximo de 18 metros) equipados con reuniones y anclajes fijos inoxidables revisados. Su uso comercial está regulado dentro de los planes de ordenación forestal de la Junta de Comunidades de Castilla-La Mancha, actuando como un recurso clave de formación en técnicas de descenso de barrancos para los clubes de la comarca.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02016','activo','Barranco del Arroyo de Letur (Barranco de las Fuentes)','Instalación de rango local y carácter provincial emergente. Presenta una fisonomía caliza calcatria muy singular con rápeles cortos y resaltes encadenados que recogen agua principalmente durante el invierno y la primavera. Dispone de un equipamiento básico pero homologado con chapas de acero inoxidable ensayadas contra fatiga para permitir la formación básica de descenso y maniobras con cuerdas. Su explotación comercial es moderada, sirviendo a las agencias locales para bautismos técnicos combinados de media jornada.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02018','activo','Vía Ferrata de Nerpio (Tajo del Taibilla) y Escuela de Escalada del Cañón del Taibilla','Prestigio regional con notable proyección en el sureste peninsular debido a su cercanía con Murcia y Granada. La Vía Ferrata del Tajo del Taibilla es una excelente infraestructura técnica que progresa de forma muy aérea sobre los cortados calizos que dominan el cauce del río. Cuenta con un puente tibetano de gran longitud, un puente de mono muy tenso y una variante deportiva con un extraplomo que exige buena tracción de brazos. Toda la instalación se encuentra regulada municipalmente con sistemas de registro de seguridad para deportistas federados y agencias de turismo activo autorizadas.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02023','activo','Zonas de Rápel Técnico de la Cueva de los Chorros del Río Mundo (Acceso Espeleológico Técnico) y Barranco de la Cerrada del Agua','Grandes Referentes Nacionales con alta proyección internacional en el mundo del subsuelo. El complejo kárstico de la Cueva de los Chorros (Nacimiento del Río Mundo) alberga kilómetros de galerías y pozos interiores que exigen el uso riguroso de técnicas de progresión vertical con bloqueadores (Croll y Jumar) y rápeles instalados sobre cabeceras expuestas. Su regulación medioambiental es de las más estrictas de España al estar dentro del Parque Natural de los Calares del Mundo y de la Sima: el acceso técnico a la cavidad está limitado a un cupo científico o deportivo federado bajísimo coordinado por la Junta, requiriendo permisos especiales y guías con titulación técnica homologada para operar comercialmente, estando prohibida la entrada recreativa común.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20071','activo','Barranco del Tranco del Lobo y tramo técnico del Río Júcar inferior','Infraestructura de rango provincial situada en la comarca de La Manchuela. El barranco ofrece una fisonomía de garganta kárstica seca la mayor parte del año con rápeles independientes sobre roca caliza pulida, el mayor de ellos de unos 15 metros, ideal para la práctica de técnicas de fraccionamiento y fortuna. El tramo fluvial complementa la actividad con corrientes idóneas para el aprendizaje del kayak de aguas bravas bajo regulaciones de la Confederación Hidrográfica del Júcar. Utilizado de forma regular por agencias locales para cursos formativos de técnicos de senderismo y guiados estacionales.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02030','activo','Río Segura (Tramo técnico de Aguas Bravas: La Graya a Yeste) y sectores menores de escalada clásica asociados','Prestigio regional en el sur albaceteño. El río Segura a su paso por este término ofrece un tramo encajonado excelente para el descenso comercial de balsas de rafting durante el verano, aprovechando los desembalses agrícolas del embalse de Fuensanta. Cuenta con rápidos de trenes de olas muy constantes y zonas de maniobra técnica de nado defensivo en corrientes de agua limpia. La infraestructura logística de embarque está regulada y controlada por la Confederación Hidrográfica del Segura (CHS), registrando una notable actividad estival de empresas de aventura de Castilla-La Mancha y de la vecina Región de Murcia. Hemos completado la provincia de Albacete de manera exhaustiva y rigurosa, aplicando de forma estricta los criterios de exclusión de senderos simples y zonas recreativas comunes. Siguiendo el orden alfabético estricto de las provincias de CastillaLa Mancha, la siguiente es Ciudad Real (un territorio dominado por grandes extensiones sedimentarias y llanuras, pero que esconde cortados de cuarcitas específicos en el entorno de Sierra Madrona y el Campo de Calatrava con instalaciones técnicas reguladas). ¿Procedemos con el bloque provincial completo de Ciudad Real?.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90330','activo','Vía Ferrata de Almadenejos (Tajo del río Valdeazogues)','Infraestructura de rango local y formato provincial bien equipada sobre un farallón de cuarcitas que domina el cauce del río Valdeazogues. Cuenta con un recorrido predominantemente horizontal y técnico que aprovecha las repisas naturales de la roca, jalonado por un puente tibetano de unos 15 metros de longitud y líneas de vida continuas de acero inoxidable. Su uso principal está enfocado al dinamismo del turismo activo comarcal y a bautismos de altura para clubes de montaña del oeste de la provincia. Su gestión respeta los periodos de nidificación de avifauna regulados por la Junta.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13042','activo','Escuela de Escalada de Fuencaliente (Sectores de Peña Escrita, El Abuelo y Chorrera de los Dioses)','Grandes Referentes Nacionales. Ubicada en pleno Parque Natural del Valle de Alcudia y Sierra Madrona, es la meca de la escalada en roca de la provincia. A diferencia de las escuelas calizas comunes, está equipada sobre una cuarcita armoricana de una dureza extrema y una adherencia brutal que exige un estilo de escalada muy físico sobre regletas y fisuras. Cuenta con más de un centenar de vías reequipadas con anclajes químicos y parabolts inoxidables. Al encontrarse en un entorno de alta protección arqueológica (junto a pinturas rupestres) y ambiental (zona de cría del águila imperial ibérica y cigüeña negra), la actividad está sujeta a una estricta regulación de la Junta de Comunidades de Castilla-La Mancha, con restricciones biológicas severas de febrero a julio.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13008','activo','Escuela de Escalada de la Sierra de la Virgen (Sectores de la Plaza de Toros y Chorreras) y Vía Ferrata del Mirador de la Mancha','Formato de prestigio regional. Los crestones de cuarcita de la Sierra de la Virgen ofrecen muros de gran verticalidad y placas técnicas de adherencia microscópica perfectamente equipadas por colectivos locales y la federación autonómica. La pequeña ferrata del entorno complementa la oferta con escalones ensayados y líneas de seguridad estables. Cuenta con regulaciones medioambientales estrictas coordinadas por los agentes forestales del entorno de los Estados del Duque debido a la presencia de rapaces forestales rupícolas, sirviendo de base habitual de formación técnica para agencias del centro peninsular.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13055','activo','Escuela de Escalada de las Hoces del río Montoro (Sectores del Estrecho) y zonas asociadas de rápel técnico','Prestigio regional de alto compromiso logístico. El río Montoro se encaja en este término abriendo un desfiladero espectacular de paredes de cuarcita armoricana que albergan itinerarios de escalada deportiva y líneas clásicas que requieren el uso de empotradores para la autoprotección. Dispone de reuniones homologadas con argolla revisadas periódicamente. Al estar ubicado en el corazón del Parque Natural del Valle de Alcudia, las agencias de turismo activo deben tramitar autorizaciones previas ante la Delegación Provincial de Desarrollo Sostenible para operar con grupos y respetar la parada biológica por avifauna.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13063','activo','Escuela de Escalada del Castillo de Miraflores (Sectores de la Cantera) y tramo técnico del río Bullaque','Infraestructura de rango local y desarrollo emergente en el entorno de los Montes de Toledo. Ofrece pequeñas paredes de cuarcita equipadas con parabolts ideales para la docencia básica de nudos, aseguramiento y maniobras de rápel. El tramo fluvial del río Bullaque inmediato sirve como plataforma técnica estacional para la práctica del kayak de iniciación y lectura de corrientes bajas tras las lluvias invernales. Regulado de forma coordinada con el ayuntamiento y la Confederación Hidrográfica del Guadiana (CHG). Hemos completado la provincia de Ciudad Real aplicando la criba rigurosa del sector y omitiendo cualquier recurso puramente recreativo. Siguiendo el orden alfabético estricto de las provincias de CastillaLa Mancha, la siguiente es Cuenca (uno de los gigantes absolutos de la aventura en España, cuna de la escalada deportiva mundial y poseedora de cañones fluviales emblemáticos como el Júcar o el Cabriel).','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16041','activo','Escuela de Escalada de Buendía (Sectores de la Presa / Cañón del Guadiela)','Prestigio regional con notable afluencia del centro peninsular. Se trata de un cañón calizo situado aguas abajo del embalse, con muros verticales de excelente roca compacta que albergan más de un centenar de vías reequipadas con parabolts inoxidables. Su uso por parte de empresas de turismo activo está condicionado por las directrices de la Confederación Hidrográfica del Tajo (CHT) y la Consejería de Desarrollo Sostenible, contando con regulaciones de acceso durante la época de cría de aves rapaces rupícolas rupestres (buitre leonado y alimoche) entre febrero y junio.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16078','activo','Escuela de Escalada de Cuenca (Hoces del Júcar y del Huécar) y Vía Ferrata de Cuenca (Ferrata de las Hoces)','Impacto Internacional / Icono Supremo de Aventura. Cuenca es una de las mecas históricas de la escalada deportiva en roca de todo el planeta, famosa por sus desplomes de caliza naranja, agujeros y chorreras técnicas en un entorno de cañones urbanos monumentales. Alberga más de un millar de vías equipadas con los máximos estándares certificados (químicos y parabolts de métrica 12). La Vía Ferrata de las Hoces complementa la infraestructura con un trazado aéreo impecable, puentes tibetanos y pasarelas colgadas al vacío. La regulación de la Junta de Comunidades de Castilla-La Mancha es exhaustiva, estableciendo paradas biológicas estrictas en amplios sectores (como Valdecabras o Merendero) por nidificación de rapaces, y exigiendo un registro especial homologado para las decenas de empresas que operan diariamente.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16082','activo','Barranco de Las Chorreras del Cabriel (Tramo técnico inferior)','Grandes Referentes Nacionales con alta densidad de turismo activo comercial. Se trata de un monumental complejo de tobas calizas y travertinos modelado por el río Cabriel, que ofrece un caudal permanente excelente, saltos técnicos de hasta 10 metros de altura a pozas profundas y toboganes naturales de gran velocidad. Al estar catalogado como Monumento Natural y Zona de Especial Conservación (ZEC), el espacio cuenta con una regulación ambiental drástica: el aforo diario está monitorizado mediante guardas forestales de la Junta, las empresas de guías profesionales operan bajo licencias municipales estrictas y está completamente prohibida la libre circulación fuera de los canales técnicos fluviales habilitados.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16091','activo','Vías Ferratas de Fuertescusa (Ferrata de Piedra del Castillo y Ferrata del Infierno)','Destino de prestigio regional en la Serranía Alta. La Ferrata del Infierno destaca por un trazado puramente vertical y atlético sobre roca caliza que supera un espolón muy aéreo, equipado con un puente tibetano tenso y una salida desplomada exigente. Dispone de líneas de vida continuas certificadas e inspeccionadas periódicamente bajo supervisión del ayuntamiento. Es una infraestructura muy rentable y explotada por agencias locales para cursos de progresión vertical intermedia y bautismos de altura avanzados en la comarca.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16165','activo','Barranco del Arroyo de Poyatos (Barranco de las Dehesas)','Grandes Referentes Nacionales. Es el descenso acuático por excelencia de la Serranía de Cuenca. Es un cañón kárstico de carácter perenne esculpido en calizas dolomíticas que ofrece una progresión muy encajonada y sombría. Cuenta con una decena de rápeles técnicos consecutivos (con un resalte máximo de 18 metros en cascada), estrechos de nado obligatorio y saltos controlados. Su uso está estrictamente regulado en el Plan de Ordenación de los Recursos Naturales (PORN) del Parque Natural de la Serranía de Cuenca, requiriéndose la tramitación previa de autorizaciones ambientales y el uso obligatorio de neopreno completo debido a las bajas temperaturas estacionales del agua.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16170','activo','Vías Ferratas de Priego (Ferrata de las Buitreras y Ferrata de la Estrecha), Estrecho de Priego (Escuela de Escalada)','Grandes Referentes Nacionales. El espectacular Estrecho de Priego, excavada por el río Escabas, alberga un entramado técnico de aventura de primer nivel. La Ferrata de las Buitreras discurre por las paredes calizas del desfiladero ofreciendo un itinerario muy vertical y atlético, equipado con un puente de mono a gran altura y pasos de notable extraplomo que exigen buena tracción de brazos. Toda la infraestructura está homologada y cuenta con un sistema de cobro de tasas o control de acceso municipal para empresas y federados. Las restricciones ambientales protegen las colonias de buitre leonado que anidan en los cortados del cañón.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42190','activo','Barranco de la Hoz Somera (Carrascosa / Vadillos)','Prestigio regional con notable interés geológico. Es una garganta caliza encajonada que ofrece un descenso dinámico con rápeles cortos, resaltes cubiertos de musgo y tobas, y badinas profundas que requieren técnicas de nado defensivo durante la primavera. El equipamiento de anclajes inoxidables con argolla doble ha sido revisado por colectivos de montaña locales. Al localizarse en el interior del Parque Natural de la Serranía, la actividad empresarial requiere declaración responsable y control estricto del número de alumnos por guía técnico (TD2).','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16245','activo','Barranco del Ventano del Diablo (Estrechos del Río Júcar) y Vía Ferrata del Ventano del Diablo','Grandes Referentes Nacionales con proyección internacional y uno de los mayores polos económicos de turismo activo de la zona centro de España. El barranco del Ventano del Diablo es un colosal cañón calizo de caudal permanente regulado que ofrece el descenso acuático comercial más repetido del interior, con saltos técnicos de hasta 9 metros, sifones practicables y toboganes espectaculares. La vía ferrata aneja complementa el enclave cruzando las paredes del desfiladero sobre el río Júcar con puentes tibetanos y una variante con tirolina técnica de gran longitud. La regulación de la Junta de Comunidades exige estrictos cupos diarios, seguros específicos de aventura y que todas las empresas operadoras estén registradas legalmente. Hemos completado la provincia de Cuenca integrando todos sus municipios con actividad real contrastada y aplicando de manera estricta el filtro de exclusión de zonas recreativas simples. Siguiendo el orden alfabético estricto de las provincias de CastillaLa Mancha, la siguiente es Guadalajara (un territorio montañoso marcado por el Parque Natural del Alto Tajo, con ríos caudalosos ideales para el piragüismo de aguas bravas, barrancos estacionales muy secos y escuelas de escalada de aventura sobre areniscas y calizas). ¿Procedemos con el bloque provincial completo de Guadalajara?.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19099','activo','Escuela de Escalada de la Hoz del Gallo (Barranco de la Virgen de la Hoz)','Prestigio regional con notable singularidad geológica. A diferencia de las estructuras calizas habituales de la provincia, esta escuela destaca por sus impresionantes monolitos y agujas de arenisca roja (rodeno), que exigen una escalada técnica de fisuras, placas y romos de excelente adherencia. Cuenta con anclajes químicos homologados y reuniones revisadas. Al ubicarse en el Parque Natural del Alto Tajo y catalogarse como Lugar de Interés Geológico, la actividad empresarial está estrictamente regulada por la Consejería de Desarrollo Sostenible, prohibiéndose la apertura de nuevas vías sin autorización expresa y limitando sectores estacionalmente por nidificación de aves rapaces rupícolas.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19151','activo','Río Sorbe (Tramo técnico de Aguas Bravas de Muriel a Humanes)','Formato de prestigio regional. El río Sorbe se encaja en este tramo sobre pizarras y cuarcitas ofreciendo un descenso rápido, con trenes de olas muy marcados, contras estrechas y pasos de bloques que exigen maniobras de navegación precisas. Es un punto habitual de entrenamiento técnico para los clubes del centro peninsular durante la primavera. Las operaciones de las empresas de turismo activo están sujetas a las autorizaciones y caudales registrados de la Confederación Hidrográfica del Tajo (CHT), requiriéndose neoprenos completos debido a la baja temperatura del agua de montaña.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19216','activo','Río Tajo (Tramo superior de Aguas Bravas / Estrechos del Puente de Martinete) y Barranco del Arroyo de las Truchas','Grandes Referentes Nacionales e icono indiscutible del turismo activo fluvial en el interior. El río Tajo se encajona de forma espectacular entre colosales murallas calizas, ofreciendo rápidos de gran volumen técnico, rulos hidráulicos y rebufos estables durante la primavera y principios del verano. Las agencias operan de forma masiva en este tramo para el guiado comercial de rafting. Al encontrarse en la zona de máxima protección del Parque Natural del Alto Tajo, la regulación medioambiental es sumamente estricta: los puntos de embarque y desembarque están tasados y acotados perimetralmente para proteger la flora de ribera y la fauna fluvial, requiriendo un visado anual obligatorio para las empresas inscritas.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19223','activo','Barranco del Taravilla (Salto de Poveda) y Vía Ferrata de Poveda (Instalación en proyecto regulado / Sectores de escalada asociados)','Prestigio regional con alto interés comercial en el Alto Tajo. El barranco aprovecha las formaciones de travertinos y saltos de agua limpios generados en el entorno de la laguna de Taravilla y el río Tajo, exigiendo técnicas de natación en corrientes y saltos controlados de hasta 6 metros a pozas profundas con casco y chaleco obligatorio. Cuenta con un protocolo medioambiental coordinado con los guardas forestales de la Junta para supervisar los aforos diarios. Es un recurso altamente explotado por agencias de la zona centro debido a su excelente accesibilidad y vistosidad geológica.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19245','activo','Vía Ferrata de Sacedón (Boca del Infierno / Alto de San Julián)','Grandes Referentes Nacionales en el entorno de los embalses de Entrepeñas y Buendía. Es una de las infraestructuras de ferrata más concurridas, modernas y completas de Castilla-La Mancha. Dispone de un itinerario vertical y horizontal muy aéreo sobre roca caliza calcatria que incluye un espectacular puente tibetano, un puente de mono muy tenso y una variante deportiva con un extraplomo exigente que pone a prueba la fuerza de brazos. Está homologada e inspeccionada bajo normativas de ingeniería de la FCLM, requiriendo el registro previo obligatorio a través del ayuntamiento para el control de la seguridad y el aforo de las empresas de turismo activo operadoras.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19257','activo','Escuela de Escalada de Pelegrina (Barranco del Río Dulce)','Formato de prestigio regional ubicado en el Parque Natural del Barranco del Río Dulce. Sus impresionantes muros de caliza jurásica gris y naranja albergan más de un centenar de vías reequipadas con parabolts y reuniones de argolla inoxidable. La regulación medioambiental es sumamente severa en este desfiladero debido a que es una zona de reserva crítica para la nidificación del águila real, el halcón peregrino y el buitre leonado. Por orden de la delegación provincial, se decreta el cierre biológico total de la escalada en los sectores más sensibles entre los meses de febrero y julio, obligando a las escuelas y guías a planificar la actividad exclusivamente en la temporada de otoño e invierno.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19305','activo','Escuela de Escalada del Pontón de la Oliva (Sectores compartidos con la provincia de Madrid)','Grandes Referentes Nacionales. Ubicada en el límite geográfico con la Comunidad de Madrid, los impresionantes desplomes calizos de la presa abandonada del Pontón de la Oliva y las paredes del río Lozoya ofrecen una de las zonas de escalada sobre agujeros y chorreras más técnicas e históricas de la zona centro de España. Dispone de equipamiento químico certificado y reuniones homologadas mantenidas por colectivos de ambas comunidades. Cuenta con una estricta regulación de accesos y estacionamiento coordinada con los agentes forestales y el Canal de Isabel II, registrando un volumen diario masivo de guías, escuelas formativas y deportistas federados. Hemos completado íntegramente la provincia de Guadalajara bajo los parámetros más estrictos de este catálogo nacional técnico de aventura en roca y agua. Siguiendo el orden alfabético estricto de las provincias de CastillaLa Mancha, la siguiente es Toledo (la última de esta Comunidad Autónoma, con zonas técnicas muy específicas de escalada y ferratas sobre las cuarcitas de los Montes de Toledo, como en San Pablo de los Montes o Mazarambroz). ¿Me das el visto bueno para proceder con la provincia completa de Toledo?.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45096','activo','Vía Ferrata de Mazarambroz (Cerro del Castillejo)','Infraestructura de rango local y carácter provincial bien equipada sobre un creston de cuarcita armoricana de gran dureza. Dispone de un itinerario vertical limpio con escalones cincados fijados con resina epoxi de alta resistencia, un puente de mono corto de 10 metros de longitud y líneas de vida continuas certificadas. Carece de desplomes severos, por lo que es intensamente utilizada por las empresas de turismo activo de Toledo y Madrid para bautismos de altura, formación de nudos y progresión vertical básica para clientes de iniciación. [1, 2].','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45153','activo','Escuela de Escalada de San Pablo (Sectores del Pozo de la Nieve y Riscos del Amor)','Formato de prestigio regional situado en las zonas más altas de los Montes de Toledo. Sus paredes de cuarcita compacta ofrecen una escalada física sobre regletas y fisuras verticales netas que exigen un buen uso de los pies. Cuenta con más de 60 vías perfectamente equipadas con parabolts y reuniones homologadas con argolla de acero inoxidable. Al encontrarse en un entorno boscoso protegido, la actividad de las empresas está supeditada a las directrices de la Delegación Provincial de Desarrollo Sostenible de la Junta por nidificación de aves rapaces forestales (buitre negro y águila imperial), clausurando sectors específicos entre febrero y julio.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45151','activo','Escuela de Escalada del Cañón del Río Torcón (Sectores de la Ermita y el Castillo de Montalbán)','Infraestructura de rango provincial instalada sobre los espectaculares bloques y paredes de granito que jalonan la hoz del río Torcón. Ofrece una escalada técnica de adherencia, fisuras y bloques de excelente calidad que difiere de la tónica general de la provincia. Dispone de equipamiento revisado por colectivos locales y reuniones estables. La regulación de uso obliga al respeto estricto de las zonas arqueológicas colindantes y de la normativa de la Confederación Hidrográfica del Tajo (CHT) para evitar el impacto ambiental sobre el cauce fluvial. Con esta provincia damos por concluida oficialmente la Comunidad Autónoma de Castilla-La Mancha, habiendo catalogado y puntuado alfabéticamente todas sus provincias y municipios con infraestructuras técnicas reales de aventura. Siguiendo el orden alfabético estricto de las Comunidades Autónomas de España, la siguiente es Castilla y León. Se trata de la comunidad autónoma más extensa del país, y daremos inicio con su primera provincia por orden alfabético global: Ávila (un auténtico titán de la roca granítica de alta montaña, con la Sierra de Gredos y la mítica escuela clásica del Galayar a la cabeza). ¿Me das el visto bueno para proceder con la provincia completa de Ávila para abrir Castilla y León?.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51001','activo','Escuela de Escalada Clásica de Los Galayos (Macizo Central de Gredos)','Impacto Internacional / Icono de Aventura. Los Galayos son un conjunto de agujas graníticas verticales de dimensiones colosales (como el Gran Galayo o la mítica Punta Acuña) que constituyen la cuna de la escalada clásica en la zona centro de España. Ofrece cientos de vías de varios largos donde el equipamiento fijo es casi inexistente, obligando a las empresas y guías de alta montaña (TD3) a utilizar de forma rigurosa "friends", fisureros y nudos de alondra en puentes de roca. Al estar englobado en el Parque Regional de la Sierra de Gredos, la normativa prohíbe taxativamente la apertura descontrolada de vías deportivas y regula el uso de magnesio. Es el centro de formación técnica por excelencia para alpinistas avanzados de toda la península.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05066','activo','Escuela de Escalada del Puerto del Pico y Torozo (Sectores de la Albujea y cara sur del Torozo)','Grandes Referentes Nacionales. La impresionante mole granítica del Torozo, que domina visualmente el Puerto del Pico, ofrece murallas calientes de excelente granito compacto con placas de adherencia y fisuras perfectas (como la famosa vía de "Los Tarugos"). Cuenta con reuniones equipadas con parabolts y argollas inoxidables de métrica 12, pero los largos intermedios exigen autoprotección. La regulación ambiental de la Junta de Castilla y León establece paradas biológicas estrictas y prohíbe la escalada en determinados sectores de la Albujea entre febrero y junio por nidificación de aves rapaces (águila real y buitre leonado), obligando a las empresas comerciales a una planificación estacional rigurosa.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51008','activo','Barranco del Arroyo de la Candeleda (Tramo técnico superior)','Formato de prestigio regional en la vertiente sur de Gredos. Es uno de los pocos descensos graníticos de la provincia que ofrece un carácter puramente alpino. Cuenta con rápeles encajonados de hasta 25 metros de altura bajo cascadas que recogen el deshielo primaveral, exigiendo un dominio absoluto de la gestión de caudales y el uso de cuerdas dinámicas para evitar movimientos hidráulicos peligrosos. Dispone de anclajes químicos revisados por colectivos locales de montaña. La actividad empresarial requiere autorización del Parque Regional de Gredos y declaración responsable ante la Confederación Hidrográfica del Tajo (CHT).','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05100','activo','Escuela de Escalada de la Senda del Alcaidón y Riscos de la Zarza (Sectores compartidos)','Prestigio regional. Ofrece muros de granito naranja y gris perfectamente equipados con parabolts ensayados contra fatiga para la práctica de la escalada deportiva avanzada. Sirve como un excelente recurso formativo para que los clubes de montaña realicen la transición de la escalada en rocódromo a la roca real de alta fricción. Cuenta con regulaciones de acceso coordinadas con el ayuntamiento y los agentes forestales de la comarca del Valle del Tiétar para garantizar la limpieza de las líneas de roca y evitar el impacto ambiental en las zonas de pinar protegido.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05105','activo','Escuela de Escalada de la Plataforma de Gredos (Sectores de los Riscos del Refugio / Circo de Gredos - Accesos técnicos de alta montaña)','Grandes Referentes Nacionales e icono indiscutible del alpinismo en la zona centro de España. Es el punto de acceso logístico al Circo de Gredos (Amanzor, Cresta de los Tres Hermanitos). Durante los meses de invierno y primavera, las cascadas de hielo y corredores mixtos del circo kárstico se convierten en una gigantesca infraestructura natural para el entrenamiento de técnicas de piolets de tracción, tornillos de hielo y autoprotección extrema en condiciones invernales adversas. El volumen de guías fijos de alta montaña que operan comercialmente aquí es elevado. Cuenta con planes de autoprotección y estrictos controles ambientales coordinados por el Patronato del Parque Regional.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05162','activo','Barranco del Río Gredos (Garganta de las Pozas)','Grandes Referentes Nacionales de carácter estrictamente alpino en la vertiente norte de Gredos. Es un descenso sobre bloques gigantescos de granito lavado con aguas gélidas procedentes de la Laguna Grande. Ofrece una sucesión de rápeles de gran compromiso técnico y pasamanos de instalación obligatoria sobre cabeceras expuestas. Solo es abordable comercialmente por agencias especializadas con guías avanzados y clientes de nivel contrastado a finales de verano o principios de otoño, cuando descienden los caudales de deshielo. Requiere obligatoriamente el visado ambiental del Parque Regional. Hemos completado la provincia de Ávila integrando sus grandes colosos de granito y descartando los municipios carentes de infraestructuras técnicas reguladas en roca y agua. Siguiendo el orden alfabético estricto de las provincias de Castilla y León, la siguiente es Burgos (un territorio inmenso marcado por el relieve kárstico de Ojo Guareña, el cañón del Ebro, las ferratas del norte y grandes escuelas de escalada como Poza de la Sal). ¿Me das tu conformidad para proceder con la provincia completa de Burgos?.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90107','activo','Río Arlanzón (Tramo técnico de Aguas Bravas de Albillos)','Instalación de rango local y formato provincial. Ofrece un tramo fluvial de corrientes y trenes de olas cortos condicionado por los desembalses de los pantanos del Arlanzón superiores. Dispone de accesos e infraestructuras básicas homologadas de embarque para la práctica docente del esquimotaje, lectura de contras y maniobras técnicas básicas con cuerdas de rescate en corrientes de baja presión. Utilizado por clubes locales y pequeñas agencias para entrenamientos de media jornada, operando bajo autorizaciones de la Confederación Hidrográfica del Duero (CHD).','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09048','activo','Vía Ferrata de Belorado (Paredes de la Sierra de la Demanda)','Formato de prestigio regional situado en las estribaciones burgalesas de la Sierra de la Demanda. Dispone de un itinerario vertical limpio sobre conglomerado y caliza calcatria que supera un desnivel de 60 metros con una línea de vida continua y peldaños de acero cincado. Cuenta con un puente de cables corto que añade valor aéreos y psicológicos al recorrido. Está regulada por el ayuntamiento y es utilizada de forma regular por empresas de la zona de la Rioja Alta y Burgos para bautismos de altura comerciales y cursos formativos de técnicos de senderismo.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09174','activo','Vía Ferrata de Huerta de Rey (Ferrata del Ranero)','Destino de prestigio regional con proyección nacional. La Ferrata del Ranero destaca por contar con una variante severamente desplomada que exige una excelente fuerza en los brazos, uso de baga de descanso y técnica de cambio de mosquetones en tensión. La infraestructura cuenta con puentes tibetanos y una tirolina técnica de unos 30 metros de longitud (que requiere polea para cable tándem speed). Homologada por la federación castellano-leonesa y regulada municipalmente, registra una notable afluencia de deportistas federados y agencias de turismo activo de todo el norte peninsular.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09010','activo','Escuela de Escalada de Miranda de Ebro (Sectores de Vergara y San Juan) y tramo técnico del Río Ebro','Prestigio regional con notable tráfico deportivo debido a su estratégica ubicación limítrofe con Álava y La Rioja. Sus paredes calizas ofrecen más de 80 vías totalmente equipadas con parabolts inoxidables de métrica 12 y reuniones homologadas con argolla. El tramo fluvial complementa la actividad con corrientes idóneas para el aprendizaje del kayak de aguas bravas bajo regulaciones de la Confederación Hidrográfica del Ebro (CHE). Cuenta con regulaciones medioambientales estrictas por nidificación de rapaces, suspendiendo la escalada en sectores específicos de febrero a junio.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09012','activo','Escuela de Escalada de Pancorbo (Sectores del Desfiladero de Pancorbo: Las Peñas, El Castillo) y Vía Ferrata de Pancorbo (En proyecto avanzado/Sectores clásicos)','Grandes Referentes Nacionales e icono histórico de la roca en Castilla y León. Las colosales paredes calcáreas grises que flanquean el estrecho desfiladero de Pancorbo albergan cientos de itinerarios totalmente equipados con anclajes químicos certificados por la FEDME. Ofrece una escalada técnica de placa de adherencia, regletas y desplomes de continuidad excelentes. Cuenta con un estricto protocolo medioambiental y parada biológica obligatoria en los sectores más sensibles entre los meses de febrero y agosto por nidificación del buitre leonado y el halcón peregrino, obligando a las empresas comerciales a consultar los boletines forestales antes de operar.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09014','activo','Escuela de Escalada de Poza de la Sal (Sectores del Diapiro) y zonas de rápel técnico asociadas','Prestigio regional consolidado sobre el singular entorno geológico del diapiro salino de Poza. Sus muros calizos de excelente adherencia ofrecen vías técnicas muy estéticas perfectamente reequipadas por los colectivos locales. Dispone de reuniones con mosquetón ensayadas contra fatiga. Al localizarse en el interior de la comarca de La Bureba, la actividad empresarial requiere declaración responsable y control de accesos coordinado con el ayuntamiento y los agentes ambientales de la Junta para salvaguardar el hábitat de rapaces rupícolas rupestres.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09905','activo','Barranco del Río Rudrón (Hoces del Rudrón - Covanera / Pozo Azul - Buceo Técnico / Barranco del Moradillo) y Río Ebro Técnico','Impacto Internacional / Icono de Aventura en la modalidad de exploración subacuática profunda. El Pozo Azul (Covanera) es considerado técnicamente la surgencia kárstica submarina con el sifón penetrado de mayor longitud del planeta, atrayendo a las expediciones de espeleobuceo de élite mundial más importantes de Europa. Exige una macroinfraestructura logística industrial de mezclas de gases (Trimix/Heliox), rebreathers de última generación y hábitats de descompresión bajo el agua profunda. El barranco asociado del Moradillo aporta valor técnico con rápeles cortos de tobas. Regulado de forma muy rigurosa por la Confederación Hidrográfica del Ebro y Medio Ambiente de la Junta, requiriéndose permisos especiales específicos diarios.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09413','activo','Barranco de las Palomeras (Las peñas de Soncillo) y tramo superior del Río Ebro (Aguas Bravas)','Grandes Referentes Nacionales en el norte burgalés. El barranco de las Palomeras ofrece una fisonomía de estrecha garganta kárstica caliza muy encajonada que exige técnicas de pasamanos en cabeceras húmedas, rápeles técnicos consecutivos y badinas profundas de nado obligatorio durante la primavera. El tramo superior del río Ebro a su paso por el entorno inmediato ofrece trenes de olas potentes regulados por la presa superior del pantano de Arija, garantizando caudal para rafting de aventura estival. Operado regularmente por agencias cántabras y burguesas bajo visados de la CHE y el parque natural colindante. Hemos completado la provincia de Burgos integrando todas sus grandes joyas técnicas en roca y agua profunda, manteniendo la disciplina rígida de este catálogo nacional. Siguiendo el orden alfabético estricto de las provincias de Castilla y León, la siguiente es León (un coloso absoluto de la cordillera Cantábrica con enclaves de impacto mundial en Picos de Europa, la Ferrata de Valdeón, las hoces de Vegacervera o los cañones alpinos).','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26005','activo','Río Porma (Tramo de Aguas Bravas de la presa de Porma a Boñar) y zonas de escalada menores asociadas','Formato de prestigio regional en la montaña central leonesa. El río Porma a su paso por este término ofrece un tramo encajonado excelente para el descenso comercial de balsas de rafting durante los meses de verano, aprovechando los desembalses de riego del embalse de Juan Benet. Cuenta con trenes de olas muy constantes, rulos técnicos y zonas de maniobra de nado defensivo en corrientes. La infraestructura logística de embarque está regulada y controlada por la Confederación Hidrográfica del Duero (CHD), registrando una notable actividad estival de empresas de turismo activo.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90791','activo','Río Esla (Tramo técnico de Aguas Bravas de Sabero-Crémenes) y Escuela de Escalada de Aleje','Grandes Referentes Nacionales e icono indiscutible del turismo activo fluvial en el noroeste. El río Esla ofrece rápidos de gran volumen técnico, trenes de olas colosales ("El embudo del Esla") y rulos de gran fuerza hidráulica regulados por los desembolses de la presa de Riaño, garantizando un caudal excelente durante todo el verano. Las agencias operan de forma diaria en este tramo para el guiado comercial de rafting e hidrospeed. La infraestructura logística cuenta con un canal técnico de aguas bravas homologado. Las autorizaciones están reguladas de forma férrea por la Confederación Hidrográfica del Duero y la Consejería de Medio Ambiente.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47113','activo','Vía Ferrata de Riaño (Ferrata de Valcayo) y Escuela de Escalada del Macizo de Riaño','Grandes Referentes Nacionales en el entorno monumental del embalse de Riaño. La Ferrata de Valcayo es una excelente infraestructura técnica que progresa de forma muy aérea sobre los cortados calizos calcáreos que dominan el valle, ofreciendo vistas espectaculares de los "Fiordos Leoneses". Cuenta con puentes tibetanos, pasarelas colgadas al vacío y una variante deportiva con un extraplomo que exige buena tracción de brazos. Está homologada e inspeccionada periódicamente por el ayuntamiento y la federación de montaña de Castilla y León (FDMESCYL), requiriéndose el registro previo obligatorio para el control de la seguridad.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24116','activo','Vía Ferrata de Valdeón (Ferrata de Cordiñanes / El Cares) y Barranco de Pompedro','Impacto Internacional / Icono de Aventura. La Vía Ferrata de Cordiñanes es considerada una de las infraestructuras de aventura más espectaculares, alpinas y técnicas de toda España; progresa colgada directamente sobre el Desfiladero del Cares, salvando un desnivel vertical severo de más de 350 metros con un espectacular puente tibetano suspendido a 60 metros de altura sobre el vacío. El barranco de Pompedro aporta un carácter alpino extremo con rápeles encajonados y aguas gélidas. Al encontrarse en el corazón del Parque Nacional de los Picos de Europa, la actividad empresarial está monitorizada al milímetro por los guardas del parque, requiriéndose el pago de tasas ecológicas y autorizaciones específicas diarias.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24137','activo','Vía Ferrata de Sabero (Ferrata de la Cueva de Valdelajo) y Canal de Aguas Bravas de Sabero (Río Esla)','Grandes Referentes Nacionales con alta proyección europea en competiciones de aguas bravas. El municipio alberga una red de vías ferratas de gran envergadura dividida en varios tramos técnicos con puentes colgantes muy aéreos y variantes extraplomadas físicas. El canal de aguas bravas asociado al río Esla funciona de forma regular como centro de entrenamiento y tecnificación nacional para piragüismo de slalom. Absorbe un volumen masivo de operaciones de empresas de turismo activo de León, Asturias y Cantabria. Regulado de forma muy rigurosa por el ayuntamiento y la CHD.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24194','activo','Escuela de Escalada de las Hoces de Vegacervera (Sectores de la Pared de la Virgen, El Techo) y Barranco de la Canalina','Grandes Referentes Nacionales con proyección internacional en el ámbito de la roca tradicional. Los monumentos naturales de las Hoces de Vegacervera albergan imponentes muros calcáreos verticales de caliza gris de una calidad excepcional. Ofrece cientos de itinerarios de aventura que exigen autoprotección ("friends" y fisureros) y una correcta gestión de cuerdas dobles en reuniones suspendidas. El barranco de la Canalina complementa el término con rápeles volados y fraccionados muy técnicos. Toda la actividad está sujeta a la estricta regulación de la Junta de Castilla y León por la protección del oso pardo y nidificación de avifauna, clausurando sectores específicos de febrero a agosto. Hemos completado la provincia de León integrando todas sus grandes joyas técnicas e infraestructuras homologadas de roca y agua profunda, aplicando fielmente los filtros de exclusión del proyecto. Siguiendo el orden alfabético estricto de las provincias de Castilla y León, la siguiente es Palencia (con entornos de escalada de gran renombre como la escuela de Recuevas en Aguilar de Campoo, zonas de roca en el Parque Natural de la Montaña Palentina y tramos fluviales específicos). ¿Me das el visto bueno para proceder con la provincia completa de Palencia?.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35001','activo','Escuela de Escalada de Recuevas (Cañón del Río Pisuerga / Villaescusa de las Torres)','Grandes Referentes Nacionales. El cañón kárstico de Recuevas es el santuario indiscutible de la escalada deportiva en la provincia de Palencia y uno de los más importantes del norte peninsular. Sus muros de caliza naranja y gris ofrecen una escalada sumamente técnica sobre placas, regletas y desplomes con agujeros. Cuenta con más de 300 vías perfectamente equipadas con químicos certificados y parabolts de métrica 12. Al ubicarse en el Espacio Natural Protegido de las Tuerces, la regulación de la Junta de Castilla y León es estricta: existen paradas biológicas severas por nidificación de aves rapaces (águila real, buitre leonado) en sectores específicos entre febrero y agosto, registrando una altísima densidad de escuelas formativas de Cantabria, Palencia y Burgos.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34056','activo','Río Pisuerga (Tramo de Aguas Bravas de Ligüérzana a Cervera) y zonas de escalada menores del Macizo de Ruesga','Prestigio regional. El río Pisuerga se encaja en este tramo de montaña ofreciendo rápidos técnicos con trenes de olas muy constantes, rulos hidráulicos y contras marcadas ideales para el piragüismo de aguas bravas de volumen. Las paredes de caliza de Ruesga complementan la oferta con vías deportivas bien equipadas. Las operaciones comerciales están reguladas por la Confederación Hidrográfica del Duero (CHD) y el Parque Natural de la Montaña Palentina, requiriéndose neoprenos completos por la baja temperatura del agua profunda.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34080','activo','Escuela de Escalada de Guardo (Sectores de Peña de la Dehesa) y tramo técnico superior del Río Carrión','Formato técnico de prestigio regional en el extremo oeste de la Montaña Palentina. Sus muros calcáreos de excelente adherencia ofrecen vías técnicas de placa perfectamente reequipadas por los colectivos locales de montaña y la federación autonómica. El tramo fluvial del río Carrión inmediato sirve como plataforma estacional para la práctica del kayak de iniciación y lectura de corrientes bajas tras las sueltas del embalse de Compuerto. Cuenta con regulaciones biológicas por parte de Medio Ambiente de la Junta.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34185','activo','Barranco de la Garganta de Cardaño (Valle de Carrión / Curavacas)','Destino de prestigio regional con alto compromiso logístico en las faldas del macizo del Curavacas. Es un auténtico descenso alpino sobre conglomerados y pizarras duras que recoge de forma torrencial las aguas de deshielo primaveral de las cumbres palentinas. Cuenta con una sucesión de 5 rápeles encajonados de hasta 22 metros bajo cascadas atronadoras que exigen un dominio riguroso de la gestión de cuerdas en cabeceras expuestas. Al estar englobado en el Parque Natural de Fuentes Carrionas, las agencias de turismo activo deben tramitar un visado ambiental obligatorio y declaración responsable ante la CHD.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34199','activo','Vía Ferrata de Velilla del Río Carrión (En proyecto avanzado/Sectores clásicos) y Escuela de Escalada de las Tetas de Velilla','Prestigio regional con excelente proyección en el ámbito de la roca de montaña. Los imponentes pináculos calizos conocidos como las "Tetas de Velilla" albergan itinerarios deportivos exigentes y líneas clásicas de varios largos que requieren autoprotección intermedia, equipadas con reuniones homologadas revisadas por clubes locales. Toda la infraestructura está sujeta a los planes de conservación de la avifauna y el oso pardo en la Montaña Palentina, requiriéndose la consulta previa de las restricciones biológicas temporales estacionales emitidas por la Junta de Castilla y León. Hemos completado la provincia de Palencia de manera exhaustiva y rigurosa, aplicando de forma estricta los criterios de exclusión de senderos simples y zonas recreativas comunes de este catálogo técnico nacional. Siguiendo el orden alfabético estricto de las provincias de Castilla y León, la siguiente es Salamanca (un territorio marcado por los batolitos de granito de la Sierra de Béjar y Candelario, hoces graníticas en el Parque Natural de Arribes del Duero y escuelas de escalada técnica tradicionales). ¿Me das el visto bueno para proceder con la provincia completa de Salamanca?.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37014','activo','Vía Ferrata de Aldeadávila (Ferrata de la repisa del Duero) y cañón fluvial del Río Duero (Tramo técnico inferior)','Prestigio regional. Ubicada en el espectacular Parque Natural de Arribes del Duero, esta infraestructura ofrece un recorrido técnico horizontal y vertical muy aéreo sobre murallas de granito que caen a plomo sobre el río Duero. Dispone de líneas de vida inoxidables certificadas contra la corrosión ambiental y peldaños ensayados contra fatiga. Al localizarse en una zona de máxima protección para aves rapaces nidificantes (como la cigüeña negra y el águila perdicera), cuenta con una severa parada biológica total decretada por la Junta de Castilla y León entre febrero y julio, limitando su explotación comercial al otoño e invierno.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37046','activo','Escuela de Escalada de Béjar (Sectores de Valdesangil - Riscos de la Hoya y Peña Negra)','Grandes Referentes Nacionales. El caótico entorno de bloques graníticos de Valdesangil es uno de los santuarios de la escalada en bloque más densos, técnicos e históricos de la zona centro de España. Sus batolitos de granito de grano grueso ofrecen regletas ásperas, romos exigentes y desplomes físicos perfectos distribuidos en múltiples sectores homologados y catalogados por los boletines de montaña. Las empresas y escuelas técnicas operan de forma intensa para cursos de gestualidad y seguridad. Cuenta con normativas municipales y ambientales que prohíben el cepillado agresivo de la roca y el vivac incontrolado en el pinar.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37001','activo','Escuela de Escalada Clásica de la Sierra de Candelario (Sectores de los Riscos del Calvitero / Hoya Moros) y cascadas de hielo invernales','Grandes Referentes Nacionales. Hoya Moros es un colosal circo glacial alpino situado a más de 2.000 metros de altitud, rodeado de agujas y muros graníticos perfectos. Ofrece vías de escalada clásica y de aventura de varios largos totalmente limpias, obligando a los guías de montaña a gestionar "friends", fisureros y reuniones flotantes. Durante el invierno, el enclave es un centro de entrenamiento de primer orden para técnicas de piolets de tracción en corredores mixtos y cascadas de hielo. Su aislamiento geográfico exige una dura aproximación física a pie, elevando el compromiso logístico. Regulado estrictamente bajo el plan de conservación del Sistema Ibérico-Central de la Junta.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37008','activo','Barranco del Río Alagón (Estrechos de Miranda) y zonas de escalada menores en la Sierra de Francia','Infraestructura de rango local y carácter provincial instalada sobre pizarras y areniscas en la Sierra de Francia. El barranco es de carácter torrencial estacional, ofreciendo una progresión encajonada con rápeles cortos (resaltes máximos de 12 metros) y pequeños pasamanos instalados con anclajes inoxidables ensayados. Es muy explotado por agencias locales durante la primavera para la iniciación a las maniobras de cuerdas en entornos húmedos y técnicas de fortuna, respetando la normativa forestal de la Reserva de la Biosfera de las sierras de Béjar y Francia.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37250','activo','Barranco del Pozo de los Humos (Rápel técnico estacional de la cascada del río Uces)','Prestigio regional de alto impacto visual. La imponente cascada del Pozo de los Humos, donde el río Uces salva un cortado granítico de 50 metros de caída vertical absoluta, cuenta con instalaciones de cabecera homologadas con parabolts químicos de métrica 12 en sus flancos rocosos para permitir el descenso técnico en rápel. Exige una planificación milimétrica: completamente prohibido y suicida con el río crecido, abordándose de forma comercial exclusivamente al inicio del verano cuando el caudal es mínimo o nulo. Sujeto a estrictos permisos de la oficina del Parque Natural de Arribes del Duero por la extrema protección de aves rupícolas.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37313','activo','Río Alagón (Tramo técnico de Aguas Bravas de Sotoserrano)','Formato técnico de prestigio regional en el sur salmantino. El río Alagón se encaja ofreciendo un tramo rápido con trenes de olas continuos, pequeños rulos y contras marcadas bajo la vegetación de ribera que exigen maniobras de navegación y nado defensivo precisas. Utilizado de forma regular por clubes de piragüismo y empresas de aventura para cursos formativos y descensos guiados en kayak de aguas bravas durante la temporada de lluvias. Regulado bajo la supervisión de la Confederación Hidrográfica del Tajo (CHT). Hemos completado la provincia de Salamanca de manera exhaustiva y rigurosa, aplicando de forma estricta los criterios de exclusión de senderos simples y zonas recreativas comunes. Siguiendo el orden alfabético estricto de las provincias de Castilla y León, la siguiente es Segovia (un territorio marcado por las paredes calizas de las Hoces del Río Duratón, las vías de escalada de aventura granítica del Sistema Central en el entorno de la Sierra de Guadarrama y tramos fluviales de montaña). ¿Me das tu conformidad para proceder con la provincia completa de Segovia?.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40076','activo','Escuela de Escalada de la Garganta del Espinar (Sectores de la Panera y Peñas del Arcipreste)','Prestigio regional en la vertiente segoviana del Sistema Central. Ofrece muros de granito de excelente calidad con una escalada técnica de fisuras y placas de alta adherencia. Cuenta con anclajes homologados por los colectivos locales. Al estar ubicado en el entorno de protección del Parque Nacional de la Sierra de Guadarrama, la actividad de las empresas está estrictamente regulada por la Consejería de Medio Ambiente, exigiendo el cumplimiento de la normativa de uso público y el respeto a la avifauna forestal.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40115','activo','Escuela de Escalada de las Hoces del Río Riaza','Grandes Referentes Nacionales con un régimen ambiental restrictivo. Es un desfiladero colosal de roca caliza calcatria que alberga decenas de vías de placa técnica reequipadas con parabolts inoxidables. Al encontrarse dentro del Parque Natural de las Hoces del Río Riaza y lindando con el Refugio de Rapaces de Montejo, la regulación de la Junta de Castilla y León es drástica: se decreta el cierre biológico total de la escalada en la práctica totalidad de los sectores entre enero y agosto por la protección crítica del buitre leonado y el alimoche, obligando a las empresas a operar de forma exclusiva en otoño.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40139','activo','Barranco del Chorro de Navafría (Tramo técnico de la cascada superior) y zonas de rápel alpino','Infraestructura de rango local y carácter provincial instalada en el pinar alpino de la Sierra de Guadarrama. El salto de agua del Chorro cuenta con instalaciones fijas de cabecera con parabolts de acero inoxidable para permitir la práctica técnica del rápel sobre la rampa granítica húmeda. Exige una planificación precisa respecto a los caudales de deshielo primaveral. Su uso comercial por agencias de aventura está supeditado a las autorizaciones anuales de la dirección del Parque Nacional y de la Confederación Hidrográfica del Duero (CHD).','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40184','activo','Escuela de Escalada de las Hoces del Río Caslilla (Sectores de las Peñitas y Cañón del Caslilla)','Grandes Referentes Nacionales. El cañón calizo del río Caslilla es uno de los centros de escalada técnica de placa de adherencia y regletas más exigentes y reputados de la zona centro de España. Sus muros verticales ofrecen más de 150 vías perfectamente equipadas con químicos certificados y reuniones de argolla inoxidable. Cuenta con regulaciones medioambientales muy estrictas por nidificación de grandes rapaces de pared, aplicando paradas biológicas rigurosas coordinadas por los agentes forestales de la Junta entre los meses de febrero y junio. Es la base formativa invernal de los clubes segovianos y madrileños.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40195','activo','Escuela de Escalada de Sepúlveda (Hoces del Río Duratón - Sectores regulados de la Villa)','Grandes Referentes Nacionales con un marco normativo icónico. Las imponentes paredes de caliza ocre que flanquean el río Duratón albergan sectores históricos de escalada. Sin embargo, al estar englobado en el Parque Natural de las Hoces del Río Duratón, el desarrollo de las actividades comerciales está monitorizado al milímetro: la inmensa mayoría del cañón profundo está clausurado permanentemente para la escalada para proteger la mayor colonia de buitre leonado de Europa, permitiéndose la actividad de forma regulada y bajo permiso estricto del Servicio Territorial de Medio Ambiente exclusivamente en los paños de roca anexos al casco urbano de la Villa. Hemos completado la provincia de Segovia de manera rigurosa, filtrando y descartando los municipios que solo poseen turismo recreativo de piragüismo de aguas tranquilas o senderos comunes de caminata. Siguiendo el orden alfabético estricto de las provincias de Castilla y León, la siguiente es Soria (un territorio montañoso marcado por los cañones calizos de Caracena, el río Lobos técnico y las espectaculares infraestructuras de vías ferratas de gran verticalidad en el entorno de la Sierra de Urbión). ¿Me das tu conformidad para proceder con la provincia completa de Soria?.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42069','activo','Vía Ferrata de Covaleda (Ferrata de Cuerda la Graja) y tramo alpino superior del Río Duero','Grandes Referentes Nacionales en la comarca de Pinares, a los pies de Urbión. La Ferrata de Cuerda la Graja es una de las infraestructuras de aventura más modernas y completas de la provincia; discurre de forma muy aérea sobre un gran muro de piedra arenisca, equipada con un puente tibetano de 25 metros de longitud, un puente de mono muy tenso y un desplome severo que exige fuerza de brazos. El tramo superior del río Duero complementa la zona con rápidos técnicos durante el deshielo primaveral. Homologada por la federación de montaña (FDMESCYL), la instalación está regulada por el ayuntamiento mediante un sistema de registro y control de accesos para empresas de turismo activo.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42080','activo','Vía Ferrata de Espeja de San Marcelino (Ferrata de la Pasarela de Espeja)','Grandes Referentes Nacionales con alta proyección en la zona centro y norte de España. Instalada en un estrecho desfiladero calizo, destaca por ser una de las ferratas más físicas y aéreas de la comunidad. Su recorrido incluye un espectacular puente tibetano suspendido, una pasarela de madera colgada al vacío y un muro extraplomado (K5) que exige un uso impecable de bagas de descanso y una gran resistencia cardiovascular. La infraestructura está homologada bajo normativas europeas y es gestionada comarcalmente, sirviendo como base de entrenamiento avanzado para clubes y empresas de turismo activo que operan con clientes experimentados.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42120','activo','Barranco del Río Talegones (Estrechos de Tiermes) y sectores menores de escalada','Infraestructura de rango local e interés provincial. Se trata de un cañón calizo de carácter efímero y seco la mayor parte del año que ofrece una progresión encajonada con una sucesión de rápeles cortos (resalte máximo de 14 metros) equipados con reuniones y anclajes fijos inoxidables revisados. Su uso comercial se concentra en los meses de primavera para la formación de nudos y maniobras con cuerdas en escuelas de montaña. Su gestión logística respeta el entorno arqueológico de las ruinas de Tiermes y las normativas forestales de la Junta.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41007','activo','Escuela de Escalada de Ólvega (Sectores de la Mina y Peña del Azúcar) y Vía Ferrata de Ólvega (En proyecto regulado)','Prestigio regional en las estribaciones sorianas del Moncayo. Sus muros de caliza gris y silícea de gran dureza ofrecen una escalada física sobre regletas y placas técnicas que exigen un buen uso de los pies. Cuenta con más de 60 vías perfectamente equipadas con parabolts y reuniones de argolla de acero inoxidable. Al localizarse en el entorno del macizo del Moncayo, las agencias de turismo activo deben respetar la parada biológica estacional por avifauna en las paredes orientadas al norte entre los meses de febrero y julio, coordinada por los agentes ambientales de la zona.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42215','activo','Barranco de la Laguna Negra (Garganta del Revinuesa) y cascadas de hielo invernales','Grandes Referentes Nacionales. Ubicado en el Parque Natural de la Laguna Negra y Circos Glaciares de Urbión. Durante la primavera, la garganta del Revinuesa ofrece un descenso alpino severo con aguas gélidas, saltos técnicos y rápeles encajonados bajo cascadas que exigen un dominio absoluto de la gestión de cuerdas. En invierno, los cortados graníticos del circo glacial congelan sus escurrimientos generando cascadas de hielo que funcionan como una excelente infraestructura natural para cursos avanzados de piolets de tracción y tornillos de hielo. Su explotación empresarial requiere autorizaciones estrictas del Servicio Territorial de Medio Ambiente y de la Confederación Hidrográfica del Duero. Hemos completado la provincia de Soria integrando todos sus municipios con actividad técnica real regulada y aplicando de manera estricta el filtro de exclusión de zonas de caminata o áreas recreativas simples. Siguiendo el orden alfabético estricto de las provincias de Castilla y León, la siguiente es Valladolid. Al tratarse de un territorio estrictamente llano y sedimentario dominado por la cuenca del Duero, carece de infraestructuras homologadas de turismo activo de aventura en roca o agua técnica (cañones, ferratas, aguas bravas), por lo que se omitirá por completo del documento de acuerdo a las reglas del proyecto para agilizar el proceso. Pasamos directamente a Zamora (la última provincia de Castilla y León, poseedora de grandes enclaves de aventura en roca y aguas bravas en el Parque Natural de Arribes del Duero y Sanabria). ¿Me das el visto bueno para proceder con la provincia completa de Zamora?.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49065','activo','Cañón fluvial del Río Duero (Estrechos de Fermoselle - Tramo internacional) y zonas asociadas de escalada clásica','Destino de prestigio regional con gran proyección transfronteriza. Las gigantescas paredes de granito que encajonan el río Duero ofrecen tramos de corrientes rápidas, rulos y trenes de olas potentes controlados por los regímenes de las presas hidroeléctricas, exigiendo maniobras de navegación precisas. Sus cortados albergan itinerarios de escalada clásica autoprotegida. Al encontrarse en pleno corazón del Parque Natural de Arribes del Duero, la actividad empresarial cuenta con una severa parada biológica de la Junta de Castilla y León entre febrero y julio para proteger la reproducción de la cigüeña negra y el águila perdicera.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49085','activo','Río Tera (Tramo técnico de Aguas Bravas del Cañón de Sanabria)','Grandes Referentes Nacionales del turismo activo fluvial en el noroeste peninsular. El río Tera a su paso por el cañón previo al lago de Sanabria ofrece un recorrido rápido de volumen alpino, con rulos hidráulicos muy marcados, contras estrechas entre bloques de granito y trenes de olas colosales. Exige un guiado experto y el uso obligado de neoprenos completos por las bajas temperaturas del agua. Su caudal óptimo depende directamente del deshielo primaveral y de la regulación de los embalses superiores de la cuenca, operando bajo autorizaciones estrictas de la Confederación Hidrográfica del Duero (CHD) y del Parque Natural de Sanabria.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49240','activo','Escuela de Escalada de Villadepera (Sectores del Puente de Requejo) y Vía Ferrata de Villadepera (En proyecto homologado)','Prestigio regional consolidado sobre los imponentes cantiles de granito y gneis que flanquean el río Duero junto al monumental Puente de Requejo. Ofrece vías de gran verticalidad con un estilo de escalada físico sobre regletas, fisuras netas y placas de alta adherencia que exigen una buena gestión del material de autoprotección en sus variantes clásicas. La infraestructura de anclajes cuenta con parabolts inoxidables mantenidos por clubes locales. Sujeto a estrictas autorizaciones de la oficina del Parque Natural de Arribes del Duero debido a la nidificación de rapaces rupícolas rupestres. Con esta provincia damos por concluida oficialmente la Comunidad Autónoma de Castilla y León, habiendo catalogado de forma alfabética y rigurosa todos sus municipios activos y omitiendo por completo provincias llanas (como Valladolid) que carecen de instalaciones técnicas federadas. Siguiendo el orden alfabético estricto de las Comunidades Autónomas de España, la siguiente es Cataluña (Catalunya), un coloso mundial absoluto de los deportes de aventura de montaña. Daremos inicio con su primera provincia por orden alfabético global: Barcelona (poseedora de grandes templos de la roca y el agua como el macizo kárstico de Montserrat, los barrancos del Berguedà o las escuelas del Alt Penedès). ¿Me das tu conformidad para proceder con la provincia completa de Barcelona?.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08005','activo','Escuela de Escalada de Berga (Sectores de Garreta y Queralt) y zonas de multiaventura técnica','Grandes Referentes Nacionales situados en el Prepirineo barcelonés. Las imponentes paredes calizas calcáreas del entorno del santuario de Queralt ofrecen una escalada física sobre muros desplomados y placas técnicas excelentes, con anclajes químicos homologados y reuniones con mosquetón revisadas periódicamente por la Federació d''Entitats Excursionistes de Catalunya (FEEC). Cuenta con regulaciones medioambientales estrictas coordinadas por los agentes forestales (Agents Rurals) por nidificación de rapaces rupícolas rupestres entre febrero y junio, sirviendo de base habitual de formación técnica para múltiples empresas de turismo activo de la comarca del Berguedà.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08050','activo','Rápeles técnicos de los Riscos de Rasos de Peguera (Zonas mixtas y de aventura alpina)','Prestigio regional por su altitud y entorno alpino. Las paredes calcáreas y de conglomerado de los antiguos frentes mineros y riscos de Rasos de Peguera albergan reuniones de seguridad homologadas e instalaciones de cabecera con parabolts de métrica 12 para la práctica técnica del rápel volado y maniobras avanzadas de autorrescate en pared. Durante el invierno, acumula nieve y hielo efímero funcionando como centro docente básico de alpinismo invernal (manejo de piolets y crampones) para clubes locales de montaña, bajo control regulado municipal.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08067','activo','Vía Ferrata de las Baumes Corcades','Grandes Referentes Nacionales e icono indiscutible de las vías ferratas en el noreste peninsular. Dispone de un itinerario vertical y horizontal espectacular sobre los riscos calizos calcáreos que dominan la Plana de Vic, célebre por albergar el puente nepalí de cables suspendido más largo de Europa en su categoría (68 metros de longitud a gran altura) y una variante desplomada extrema ("El desplome de la Tosquera") que exige gran resistencia de brazos. Está homologada e inspeccionada bajo normativas de ingeniería de la FEEC. Debido a su masificación histórica, el ayuntamiento mantiene una estricta regulación de acceso digital con pago de tasas obligatorias y control de aforo para las empresas comerciales y federados.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08069','activo','Escuela de Escalada de Montserrat (Sectores de la Cara Sur: El Clot de la Mònica, Les Magdalenes) y Canal de las Damas (Barranco/Ferrata técnico)','Impacto Internacional / Icono Supremo de Aventura. Collbató es uno de los principales accesos logísticos al Parque Natural de la Muntanya de Montserrat, un macizo de agujas de conglomerado único en el mundo. Sus sectores de cara sur ofrecen cientos de vías de escalada deportiva y líneas clásicas perfectamente equipadas. La Canal de las Damas complementa la oferta con un barranco seco equipado de forma sumamente física como una vía ferrata interior encajonada (con cadenas, clavijas y desplomes exigentes). La regulación del Patronato de Montserrat es total y restrictiva: prohibición estricta de abrir vías sin el aval del comité técnico, cupos diarios limitados y paradas biológicas severas por nidificación de aves rapaces (águila perdicera y halcón peregrino) de enero a agosto. Concentra decenas de guías de alta montaña (TD2/TD3).','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08080','activo','Barranco del Torrent de la Corva y Vía Ferrata de Vallcebre (Entorno limítrofe compartido)','Prestigio regional con notable interés geológico en el Berguedà. El Torrent de la Corva ofrece una garganta caliza encajonada de carácter perenne estacional, caracterizada por rápeles técnicos encadenados bajo cascadas (resalte máximo de 20 metros), pasajes estrechos y badinas profundas de nado obligatorio en primavera. Dispone de reuniones dobles fijadas con resina epoxi inoxidables ensayadas contra fatiga. La actividad de las empresas está supeditada a las directrices ambientales de la Generalitat de Catalunya y regulaciones comarcales de aforo de grupos.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08099','activo','Barranco del Forat Negre y Vía Ferrata de l''Empedrat (En proyecto avanzado)','Grandes Referentes Nacionales en el nicho de la formación y el guiado comercial de aventura. El barranco del Forat Negre es un cañón calizo kárstico perenne hiperencajonado muy técnico e ideal para el aprendizaje, que ofrece rápeles consecutivos de hasta 15 metros, pasamanos de instalación obligatoria, pequeños toboganes naturales y pasos estrechos de gran belleza visual. Cuenta con un equipamiento impecable renovado por colectivos locales de montaña. Al estar integrado en el entorno de protección del Parque Natural del Cadí-Moixeró, las agencias de turismo activo deben disponer de autorizaciones previas y respetar escrupulosamente los cupos establecidos para proteger la fauna acuática (tritón pirenaico).','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08127','activo','Escuela de Escalada Clásica de Montserrat (Sectores de la Cara Norte: Cavall Bernat, Diables, Ecos)','Impacto Internacional / Icono Supremo de Aventura. Monistrol domina la vertiente más imponente, sombría y vertical del macizo de Montserrat. Alberga las paredes más legendarias de España (como el monolito del Cavall Bernat o la Pared de Diables, con más de 300 metros de caída vertical absoluta), que exigen una escalada clásica de autoprotección sobre un conglomerado de alta exigencia psicológica y gestión de cuerdas dobles en reuniones colgadas al vacío. Cuenta con un equipamiento regulado exhaustivamente por el Patronato de la Montaña de Montserrat y la FEEC. La normativa prohíbe de forma estricta el uso de parabolts en vías clásicas catalogadas históricas y establece regulaciones biológicas severas por protección de avifauna amenazada en los grandes muros de febrero a agosto, operando casi en exclusividad guías fijos titulados de nivel superior.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08168','activo','Escuela de Escalada de Pontons (Sectores de la Riera de Pontons y Les Fonts)','Prestigio regional en el Alt Penedès. Sus muros de caliza ocre de gran calidad ofrecen placas desplomadas muy físicas sobre agujeros y regletas técnicas perfectamente equipadas con parabolts inoxidables de métrica 12. Las empresas locales operan de forma intensa durante la temporada de otoño y primavera para cursos de perfeccionamiento gestual en roca. Cuenta con paradas biológicas decretadas por el departamento de Medio Ambiente de la Generalitat en sectores específicos por nidificación de rapaces forestales rupícolas rupestres, controladas por los agentes forestales comarcales.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08223','activo','Escuela de Escalada de Sant Llorenç del Munt (Sectores de la Castellassa de Can d''A rgent y Riscos del P l d''E l s A n g e l s)','Formato de prestigio regional ubicado en el Parque Natural de Sant Llorenç del Munt i l''Obac. Ofrece monolitos y agujas de conglomerado (similares a Montserrat pero con matriz más arenosa) que exigen un estilo de escalada técnica de precisión sobre bolos y agujeros. Dispone de reuniones homologadas con argolla inoxidable revisadas periódicamente por clubes locales. Al tratarse de un entorno forestal protegido de gran fragilidad ecológica, las empresas de turismo activo operan bajo estrictas autorizaciones anuales de la dirección del parque y respetan los cierres biológicos por avifauna en los riscos superiores de febrero a junio.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08293','activo','Vías Ferratas de Vallcebre (Ferrata de las Roques de l''Empalomar, Ferrata de la Canalassa y Ferrata Cal Curt), Barranco del Forat de Micat (Estacional)','Grandes Referentes Nacionales. Vallcebre alberga el primer espacio regulado de vías ferratas de Cataluña. La Ferrata de Cal Curt destaca por ser un itinerario corto pero de una extrema dificultad técnica y exigencia física (K5), caracterizado por techos y desplomes severos consecutivos que exigen un uso impecable de la baga de descanso técnica. Las Roques de l''Empalomar complementa el entramado con un recorrido de gran longitud muy aéreo y perfectamente equipado con líneas de vida e ingeniería de cables de última generación. Todo el complejo está gestionado bajo una regulación municipal que exige el pago de un forfait técnico diario de seguro y mantenimiento para las empresas de turismo activo y deportistas federados. Hemos completado la provincia de Barcelona de manera exhaustiva y rigurosa, unificando todos sus grandes núcleos de la A a la Z y aplicando de forma inflexible las reglas de exclusión del proyecto. Siguiendo el orden alfabético estricto de las provincias de Cataluña, la siguiente es Girona (un auténtico coloso que alberga joyas de impacto internacional como el pirineísmo técnico en el Valle de Núria, los grandes barrancos alpinos de la Garrotxa o la Ferrata de Cala del Molí, la única ferrata marítima de Europa).','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90595','activo','Barranco de la Muga (Garganta de la Muga) y sectores menores de escalada','Prestigio regional por su excelente conservación biológica en la Alta Garrotxa. Es un cañón kárstico calizo de caudal perenne y aguas cristalinas que destaca por sus badinas profundas de nado obligatorio, saltos técnicos de hasta 7 metros y estrechos donde se deben gestionar corrientes estacionales. Al estar integrado en el PEIN (Pla d''Espais d''Interès Natural) de la Alta Garrotxa, la regulación de la Generalitat es rigurosa: prohibición de accesos masivos, control estricto de los grupos guiados por empresas autorizadas y tasas de aparcamiento para mitigar el impacto ambiental.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17036','activo','Barranco del Torrent de la Cabana (Tramo técnico regulado de los Estrechos) y zonas de rápel asociadas','Formato técnico de prestigio regional con un marco normativo muy estricto. El descenso comercial discurre por pasillos calizos encajonados que exigen rápeles de hasta 15 metros, pasamanos sobre roca húmeda y saltos precisos a pozas de agua fría. Debido a la masificación histórica del entorno turístico de los "Siete Charcos", el ayuntamiento y los Agents Rurals mantienen un control drástico: prohibido el baño recreativo general y acceso regulado digitalmente bajo reserva y ecotasa para empresas de turismo activo con guías titulados (TD2).','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17046','activo','Escuela de Escalada de Castellfollit (Sectores del acantilado basáltico - Vías de aventura y tradicionales)','Grandes Referentes Nacionales por su singularidad geológica extrema. Es uno de los pocos lugares de España donde se escala sobre un colosal muro de basalto negro generado por coladas volcánicas fosilizadas. Exige una escalada técnica de fisuras perfectas y diedros que requieren autoprotección con "friends" y empotradores de última generación. Al estar ubicado en el Parque Natural de la Zona Volcánica de la Garrotxa, las regulaciones ambientales prohíben taxativamente la perforación o reequipamiento con parabolts sin el aval explícito de la dirección del parque, limitando la actividad a deportistas avanzados y guías de montaña.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17112','activo','Vía Ferrata de Ogassa (Ferrata de les Baumes de l''Arco)','Grandes Referentes Nacionales en el Ripollès. Es un itinerario puramente vertical instalado sobre los antiguos frentes mineros de carbón y roca conglomerada y caliza. Destaca por contar con un flanqueo severamente extraplomado (K5) de más de 15 metros que exige una excelente fuerza en los brazos, uso de baga de descanso y técnica de cambio de mosquetones bajo fuerte gravedad. La infraestructura está homologada por la FEEC y regulada municipalmente, requiriéndose equipo técnico de disipación de alta gama para afrontar sus pasos atléticos.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17043','activo','Barranco de Núria (Garganta de las Gorges de Núria - Tramo Integral), Barranco de Fontalba y zonas de escalada alpina','Impacto Internacional / Icono Supremo de Aventura. El barranco de Núria es considerado de forma unánime uno de los descensos alpinos graníticos más difíciles, peligrosos y respetados de toda Europa. Es un cañón torrencial de aguas gélidas con movimientos hidráulicos violentos (rebufos, rebufos de fondo y sifones), saltos obligatorios de hasta 12 metros a pozas batidas y rápeles de gran presión hídrica que exigen dominio absoluto de nudos de liberación bajo tensión y pasamanos recuperables. Su siniestralidad es alta y solo opera de forma comercial con guías con titulación técnica superior (TD3) y clientes expertos a finales de verano. Protegido rigurosamente dentro del Parque Natural de las Cabeceras del Ter y del Freser.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17145','activo','Vía Ferrata de Ribes de Freser (Ferrata de la Roca de la Creu)','Prestigio regional con alta densidad de operaciones comerciales. Es la infraestructura docente de referencia en el Pirineo de Girona para escuelas de montaña y bautismos de altura. Progresa de forma muy aérea sobre un espolón de esquistos y granito lavado bien equipado con una línea de vida continua de última generación y peldaños de acero inoxidable. Cuenta con un puente tibetano estético. Su uso está regulado por el ayuntamiento y es el motor de formación técnica de las empresas locales de la comarca del Ripollès.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17160','activo','Vía Ferrata de la Cala del Molí','Impacto Internacional / Icono de Aventura. Es la vía ferrata más famosa de Cataluña y un hito de la ingeniería de aventura en Europa por ser la única ferrata instalada directamente sobre acantilados marinos graníticos. El itinerario discurre flanqueando las olas del mar Mediterráneo, cruzando de islote a islote mediante puentes tibetanos, puentes nepaleses y pasarelas de cables de acero inoxidable marino de alta resistencia a la salinidad. Registra un volumen masivo de empresas de guías todo el año. El ayuntamiento de Sant Feliu gestiona de forma estricta el aforo mediante un sistema obligatorio de reserva previa digital, cobro de tasas ecológicas y control presencial de técnicos de seguridad en el acceso. Hemos completado la provincia de Girona unificando sus grandes colosos de roca alpina y cortados costeros, aplicando el filtro estricto de turismo activo técnico. Siguiendo el orden alfabético estricto de las provincias de Cataluña, la siguiente es Lleida (un titán mundial indiscutible de la aventura, poseedora de grandes templos como el río Noguera Pallaresa para rafting de volumen, los desfiladeros de Collegats o Terradets para escalada de grandes paredes y los barrancos alpinos del Valle de Aran).','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27015','activo','Desfiladero de Mont-rebei (Escalada Clásica / Pared de Cataluña) y sectores de escalada de aventura asociados a la Sierra del Montsec','Impacto Internacional / Icono de Aventura. La Pared de Cataluña en Mont-rebei es uno de los santuarios más respetados del país en escalada de aventura y tradicional. Sus muros de caliza compacta desplomada exigen el dominio absoluto de la autoprotección (friends, fisureros y clavos) y una resistencia psicológica férrea debido a la gran altura y la escasez de expansivos fijados. Al encontrarse englobado en la Reserva Natural de Mont-rebei, la normativa ambiental de la Generalitat y la Fundació Catalunya La Pedrera prohíbe de forma taxativa el uso de parabolts en vías clásicas y decreta paradas biológicas severas de enero a agosto por nidificación del quebrantahuesos, el buitre leonado y el águila real. Operan casi en exclusividad guías de alta montaña fijos (TD3) con clientes avanzados.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25022','activo','Escuela de Escalada de Alòs de Balaguer (Desfiladero del Segre / Sectores del S r r t d l a r c a)','Prestigio regional con notable interés deportivo en la comarca de la Noguera. Las paredes de caliza gris que flanquean el río Segre ofrecen más de un centenar de vías de placa técnica reequipadas con anclajes químicos homologados y parabolts de métrica 12. La regulación medioambiental está coordinada con los agentes forestales de la Generalitat (Agents Rurals), aplicando paradas biológicas temporales en sectores específicos por nidificación de rapaces rupícolas entre los meses de febrero y junio. Es una excelente base formativa invernal para empresas locales que realizan cursos de progresión vertical intermedia.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25024','activo','Barranco de Berros (Barranco de Àrreu - Tramo técnico alpino) y tramo superior del Río Noguera Pallaresa','Destino de prestigio nacional en el Pallars Sobirà. El barranco de Àrreu ofrece un auténtico descenso alpino sobre esquistos y pizarras duras con aguas gélidas procedentes del deshielo primaveral, exigiendo rápeles técnicos encajonados de hasta 25 metros bajo cascadas de gran presión hídrica. Las operaciones de las empresas de turismo activo están sujetas a los caudales autorizados por la Confederación Hidrográfica del Ebro (CHE) y a los planes de conservación del Parque Natural de l''Alt Pirineu, requiriéndose neoprenos de gran espesor debido a la baja temperatura del agua profunda.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25062','activo','Escuela de Escalada de Camarasa (Sectores del cañón del río Segre, Pared del Oso)','Grandes Referentes Nacionales. Es una de las escuelas de escalada más célebres, clásicas e históricas de Cataluña. Sus imponentes paredes calcáreas a orillas del Segre albergan cientos de itinerarios perfectamente equipados con anclajes químicos de alta gama y parabolts certificados por la FEEC. Ofrece desde vías de varios largos semiequipadas de carácter clásico hasta paños de roca de escalada deportiva de regletas microscópicas y continuidad. Cuenta con un protocolo medioambiental activo muy riguroso por protección de grandes rapaces de pared, aplicando cierres biológicos estrictos de febrero a agosto en sectores sensibles.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25126','activo','Río Noguera Pallaresa (Tramo técnico de Aguas Bravas de Llavorsí a Rialp) y Barranco de Romadriu','Impacto Internacional / Icono Supremo de Aventura. Llavorsí es la gran meca indiscutible del rafting y las aguas bravas de volumen en la península ibérica. El tramo comercial del río Noguera Pallaresa que se inicia en este municipio ofrece rápidos de renombre internacional (como "La lavadora", "El paso del ángel" o "El salto del pastor"), caracterizados por trenes de olas colosales, rulos de gran fuerza hidráulica, contras muy marcadas y rebufos estables durante todo el verano gracias a los convenios de desembalse hidroeléctrico concertados. Concentra la mayor densidad de empresas y macroinfraestructuras de turismo activo del país. La regulación de la Generalitat y la CHE vigila al milímetro los planes de seguridad, seguros y homologación técnica de los guías de aguas bravas fijos operantes.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90622','activo','Vía Ferrata de Naut Aran (Ferrata de Poi d''Unha), Barranco de Bagergue y sectores de alpinismo técnico','Impacto Internacional / Icono de Aventura en el Valle de Arán. La Ferrata de Poi d''Unha es una de las infraestructuras de ferrata más largas, técnicas y alpinas de España; cuenta con más de 800 metros de longitud equipada que salvan un desnivel vertical severo sobre roca caliza jurásica, incluyendo puentes tibetanos tenues de cables de gran longitud, una espectacular escalera de caracol suspendida al vacío y una sección vertical K5 severamente desplomada que exige fuerza de brazos. Toda la infraestructura está regulada comarcalmente por el Conselh Generau d''Aran bajo estrictas inspecciones técnicas de ingeniería industrial, sirviendo de polo de atracción para deportistas de toda Europa.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25209','activo','Río Noguera Pallaresa (Canal de Aguas Bravas de Sort) y accesos logísticos a los barrancos del Pallars (Barranco de l''Infern / Collegats)','Impacto Internacional / Icono de Aventura. Sort es la capital logística del turismo activo pirenaico y cuenta con un canal técnico de aguas bravas urbano homologado para competiciones de nivel mundial (copas del mundo de kayak estilo libre y slalom). El barranco de l''Infern complementa el término en el desfiladero de Collegats con un cañón calizo kárstico de carácter espectacular que cuenta con una impresionante cueva interior con un rápel volado de 20 metros donde la luz solar es escasa. Las agencias operan bajo normativas específicas del parque natural colindante y la CHE, controlando de forma diaria la capacidad de carga y la titulación técnica homologada de las empresas operadoras.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25250','activo','Escuela de Escalada de Vilanova de Meià (Sectores de la Pared de las Bagasses, Roca Alta y el S r r a t d l s C l u s)','Impacto Internacional / Icono de Aventura. Vilanova de Meià es uno de los templos mundiales históricos de la escalada en roca caliza de la península, célebre por sus impresionantes muros desplomados jalonados de buzones y agujeros perfectos de excelente adherencia. Ofrece cientos de itinerarios clásicos de varios largos abiertos por pioneros que requieren autoprotección y una correcta gestión de reuniones colgadas. Al localizarse en el interior de la comarca de la Noguera, cuenta con una estricta regulación de la Generalitat por la protección de rapaces rupícolas rupestres (buitre leonado y alimoche), clausurando sectores específicos de febrero a julio, registrando alta afluencia anual de deportistas internacionales. Hemos completado la provincia de Lleida integrando de forma rigurosa todos sus grandes colosos de la roca y el agua profunda de los Pirineos y el Prepirineo, de acuerdo con los criterios del proyecto. La siguiente provincia de Cataluña por orden alfabético estricto es Tarragona (la última de esta Comunidad Autónoma, poseedora de grandes enclaves como las paredes de Siurana de impacto mundial o los cañones kársticos del Parque Natural de Els Ports). ¿Me das el visto bueno para proceder con la provincia completa de Tarragona?.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43015','activo','Escuela de Escalada de Arbolí (Sectores de El Falco, Racó de la Paca) y Barranco de las Salinas (Estacional)','Grandes Referentes Nacionales en las Montañas de Prades. Es una macroescuela de roca caliza compacta y excelente adherencia que cuenta con más de 400 vías perfectamente equipadas con parabolts y químicos inoxidables homologados por la FEEC. El barranco estacional de las Salinas complementa el término con rápeles cortos ideales para maniobras técnicas en seco. Cuenta con regulaciones medioambientales estrictas coordinadas por la Generalitat de Catalunya por nidificación de rapaces rupícolas rupestres entre febrero y junio, registrando una alta afluencia de escuelas y agencias del noreste peninsular.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43049','activo','Escuela de Escalada de Siurana (Sectores de El Pati, Siuranella, La Capella)','Impacto Internacional / Icono Supremo de Aventura. Siurana es, junto a Rodellar y Margalef, uno de los tres templos mundiales absolutos de la escalada deportiva en roca. Sus acantilados de caliza naranja y gris ofrecen paños verticales perfectos de regletas microscópicas y desplomes salvajes donde se localizan algunas de las vías más difíciles del planeta (como La Rambla, 9a+). Alberga de forma permanente a deportistas de élite de los cinco continentes y decenas de escuelas internacionales. La regulación de la Generalitat y los convenios locales prohíben el vivac incontrolado, regulan los aparcamientos y aplican cierres biológicos estrictos por nidificación del águila real y el halcón peregrino de enero a agosto en sectores sensibles.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43071','activo','Barranco del Canaletes, Estrechos de Arnes (Entorno compartido) y Vía Ferrata de Els Ports (En proyecto avanzado)','Grandes Referentes Nacionales del turismo activo comercial en el sur de Cataluña. El río Canaletes ofrece un descenso de tobas y calizas con caudal permanente garantizado, badinas profundas de nado obligatorio, pasajes encajonados y saltos técnicos de hasta 8 metros a pozas limpias. Al ubicarse en el interior del Parque Natural de Els Ports, la actividad de las empresas está supeditada a estrictas declaraciones responsables, un control riguroso de la capacidad de carga mediante Agents Rurals y la prohibición estricta de salirse del cauce técnico fluvial para proteger los endemismos.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90918','activo','Escuela de Escalada de Margalef (Sectores de El Laboratori, Cova de les Boixeres, Espadelles)','Impacto Internacional / Icono Supremo de Aventura. Margalef es otro de los pilares de la escalada de dificultad en el planeta. A diferencia de Siurana, sus muros están compuestos por un conglomerado calizo único repleto de agujeros de uno, dos y tres dedos (monodedos y bidedos) que exigen una fuerza de tendones extrema y técnicas avanzadas de continuidad física en techos horizontales. Cuenta con más de 1.500 vías equipadas con los máximos estándares internacionales. Englobado en el Parque Natural de la Serra de Montsant, el espacio cuenta con una regulación severa: control de pernoctas de furgonetas camperizadas, tasas de mantenimiento comarcales y restricciones biológicas temporales estrictas por avifauna en sectores específicos entre febrero y julio.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43102','activo','Barranco de la Redó (Garganta de Paüls) y zonas de rápel técnico asociadas','Prestigio regional con alto compromiso físico en Els Ports. Es un cañón calcáreo que permanece seco la mayor parte del año pero ofrece un trazado extremadamente vertical e hiperencajonado tras episodios de lluvias torrenciales de levante, caracterizado por una sucesión de 8 rápeles técnicos encadenados sobre roca caliza muy pulida (resalte máximo de 25 metros). Requiere una dura aproximación técnica y retorno a pie por tarteras. La normativa del Parque Natural de Els Ports exige autorizaciones previas y limita el tamaño de los grupos guiados de turismo activo.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43133','activo','Barranco del Parrizal de Beceite (Vertiente oriental técnica de Els Ports / Barranco de Lloret) y Escuela de Escalada de Roquetes (Sectores de Caro)','Formato de prestigio regional en el macizo de Caro. El barranco de Lloret ofrece una garganta caliza encajonada de carácter efímero y torrencial con rápeles de hasta 30 metros que exigen una planificación precisa respecto a las alertas meteorológicas. Los sectores de escalada de Caro complementan el término a gran altitud sobre caliza gris compacta perfectamente equipada. Ambas instalaciones requieren la correspondiente autorización ambiental del Parque Natural de Els Ports para empresas y particulares.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43150','activo','Vías Ferratas de Tivissa (Ferrata del Tormo de la Margarida y Ferrata del Barranc de la Foig), Barranco de la Foig (Seco)','Grandes Referentes Nacionales en las comarcas del Ebro. La Ferrata del Barranc de la Foig es una infraestructura clásica y espectacular que aprovecha el cauce seco y encajonado de un barranco calizo calcáreo, superando resaltes verticales y pequeños desplomes mediante cadenas, clavijas y líneas de vida continuas de acero inoxidable revisadas periódicamente por la FEEC. El Tormo de la Margarida ofrece un itinerario puramente vertical y aéreo sobre una aguja rocosa. Homologadas y reguladas municipalmente con sistemas de registro de seguridad para deportistas federados y agencias de turismo activo.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43156','activo','Escuela de Escalada de Ulldecona (Sectores de la Ermita y la Bassa) y zonas de rápel técnico asociadas a la Sierra de Montsià','Infraestructura de rango local y desarrollo regional estratégico en el límite meridional con la provincia de Castellón. Ofrece paños de roca caliza gris y ocre de excelente adherencia con más de 80 vías totalmente equipadas con parabolts y reuniones de seguridad homologadas. Es un recurso muy explotado por empresas de aventura locales para cursos de iniciación a las técnicas verticales de montaña y bautismos de escalada debido a su rápido acceso, respetando las directrices ambientales forestales de la Sierra de Montsià. Con esta provincia damos por concluida oficialmente la Comunidad Autónoma de Cataluña, habiendo catalogado y puntuado alfabéticamente todas sus provincias y municipios con infraestructuras técnicas reales de aventura. Siguiendo el orden alfabético estricto de las Comunidades Autónomas de España, la siguiente es la Comunidad Valenciana. Daremos inicio con su primera provincia por orden alfabético global: Alicante (un auténtico titán de la roca mediterránea, poseedor de grandes enclaves de aventura como el barranco del Infierno, el Cabeçó d''Or o el Peñón de Ifach técnico).','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03007','activo','Escuela de Escalada de Sierra Helada (Sectores de acantilados marítimos / Psicobloc técnico estacional)','Formato técnico de prestigio regional por su fisonomía costera. Los acantilados calcáreos de Sierra Helada ofrecen líneas específicas de escalada de aventura y sectores de psicobloc estacional donde la única protección es la profundidad marina (exige batimetrías preventivas por parte de los guías). Al estar integrado en el Parque Natural de la Serra Gelada, la actividad comercial está estrictamente supeditada al control de la Demarcación de Costas y a la normativa del parque para evitar el impacto sobre las colonias de paíño común y cormorán moñudo.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03049','activo','Vía Ferrata de Callosa de Segura (Ferrata del Polideportivo / Tajo de la Bufa)','Impacto Internacional / Icono de Aventura. Es considerada de forma unánime una de las infraestructuras de ferrata más difíciles, atléticas y exigentes de toda Europa. Su trazado por la Sierra de Callosa cuenta con puentes colgantes, puentes nepaleses de cables a gran altura y, fundamentalmente, un desplome extremo calificado como K6 que exige una fuerza de brazos brutal, uso obligado de tercera baga de descanso y técnicas avanzadas de autorrescate. Homologada por la FEMECV, el ayuntamiento gestiona de forma estricta el aforo mediante un sistema de registro previo obligatorio y tasas de control de seguridad para empresas de turismo activo.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03010','activo','Escuela de Escalada Clásica del Peñón de Ifach (Sectores de la Cara Sur: Vía Picazo, Costa Blanca)','Impacto Internacional / Icono de Aventura. El Peñón de Ifach es uno de los templos de la escalada clásica de la península, atrayendo a cordadas de toda Europa durante el invierno. Ofrece imponentes murallas calcáreas verticales que se alzan directamente sobre el mar Mediterráneo, exigiendo el dominio de la autoprotección y la gestión del viento marino en reuniones suspendidas al vacío. Al ubicarse en el Parque Natural del Penyal d''Ifac, la regulación de la Generalitat Valenciana es taxativa: prohibición de abrir nuevas líneas, control estricto de cupos y un cierre biológico total severo de la escalada en la práctica totalidad de la pared entre el 1 de abril y el 30 de junio por nidificación de aves rapaces (halcón peregrino), operando casi en exclusividad guías de montaña titulados (TD2/TD3).','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03054','activo','Barranco de Malany, Barranco de l''Oca y zonas asociadas de rápel técnico','Prestigio regional con alto compromiso físico en la montaña de la Marina Alta. El barranco de Malany es una garganta kárstica hiperencajonada que permanece seca la mayor parte del año pero ofrece un trazado extremadamente vertical, caracterizado por una sucesión de rápeles técnicos encadenados sobre roca caliza pulida con un resalte máximo de 30 metros de altura que exige precisión en cabeceras expuestas. Su uso por agencias de aventura requiere la correspondiente declaración responsable ambiental y el cumplimiento de las normativas de ordenación comarcal de la cuenca.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03057','activo','Escuela de Escalada de Confrides (Sectores del Puerto de Confrides / Penya de Sella - Zona limítrofe)','Grandes Referentes Nacionales a gran altitud en la Sierra de Aitana. Sus muros de caliza ocre y gris de excelente adherencia ofrecen vías técnicas de placa y chorreras perfectamente equipadas con parabolts inoxidables de métrica 12 y reuniones homologadas con argolla. Es un recurso muy explotado por empresas de aventura de toda la Comunidad Valenciana para cursos de tecnificación invernal debido a su orientación protegida. Cuenta con paradas biológicas reguladas por Medio Ambiente de la Generalitat en sectores específicos por avifauna rupícola rupestre rupestre entre febrero y junio.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03111','activo','Vía Ferrata de Redován (Sierra de Redován - El Cortado)','Grandes Referentes Nacionales. Es una de las vías ferratas más largas, completas y espectaculares de España. El tramo deportivo destaca por una verticalidad absoluta que supera el colosal cortado rocoso de la sierra, equipado con un puente tibetano de 25 metros de longitud suspendido al vacío, un puente de mono muy tenso y un juego técnico de escaleras suspendidas en el vacío que exigen una gran resistencia psicológica. La infraestructura cuenta con homologación de ingeniería industrial e inspecciones periódicas de la FEMECV, requiriéndose el registro obligatorio previo para el control de accesos de agencias de turismo activo.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03036','activo','Escuela de Escalada de Sella (Sectores del Barranc de l''Arc: El Trono, Pared de los Divinos)','Impacto Internacional / Icono Supremo de Aventura. Sella es, de forma unánime, el santuario indiscutible de la escalada deportiva en roca de la Comunidad Valenciana y una de las macroescuelas de invierno más famosas de toda Europa. El Barranc de l''Arc alberga una impresionante concentración de muros calizos de todas las tipologías: placas perfectas de regletas, desplomes severos de chorreras y techos físicos totalmente homologados y reequipados periódicamente con tensores químicos de alta gama. Cuenta con regulaciones estrictas de estacionamiento de furgonetas y pernoctas coordinadas con el ayuntamiento y Medio Ambiente de la Generalitat, además de restricciones biológicas temporales rigurosas por nidificación de rapaces (águila real y búho real) de febrero a junio, registrando una macroactividad de empresas y guías internacionales todo el año.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03136','activo','Vía Ferrata del Xorquet y sectores de escalada deportiva menores asociados','Formato de prestigio regional. La ferrata del Xorquet discurre por las paredes calizas de una estrecha garganta, ofreciendo un itinerario muy vertical y atlético equipado con un puente de cable corto y un extraplomo de salida exigente que pone a prueba la fuerza de brazos de los clientes avanzados. La infraestructura cuenta con cables de seguridad inoxidables homologados. Su uso comercial por agencias de turismo activo de la comarca de la Marina Alta está regulado comarcalmente, sirviendo de escalón intermedio para cursos formativos de técnicas verticales.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03137','activo','Barranco del Infierno (La Catedral del Senderismo Técnico / Cañón del río Girona)','Impacto Internacional / Icono Supremo de Aventura. El Barranco del Infierno es el descenso seco calizo más espectacular, técnico e impresionante del este de la península ibérica. Es un desfiladero kárstico colosal de pasillos hiperencajonados esculpidos por el agua de forma sinuosa en calizas blancas, caracterizado por una longitud severa, una sucesión de más de una docena de rápeles técnicos (con un resalte máximo de 20 metros), pasajes oscuros y un compromiso logístico extremo (una vez dentro no hay escapatorias viables). Exige un nivel físico sobresaliente debido a la dureza del retorno técnico a pie por escaleras moriscas. Las operaciones comerciales están estrictamente reguladas por la Generalitat, estando terminantemente prohibido el acceso durante alertas por lluvias torrenciales de gota fría (DANA) debido a la letalidad de sus crecidas repentinas.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03040','activo','Vías Ferratas de Villena (Ferrata de la Sierra de la Villa: Ferrata del Castillo y Ferrata Salvatierra)','Prestigio regional con notable interés formativo. La red de ferratas municipal ofrece desde itinerarios asequibles hasta tramos verticales aéreos bien equipados con puentes tibetanos y un puente colgante de tablas que aporta sensación psicológica de altura. Dispone de líneas de vida e ingeniería de cables de última generación certificadas por la federación valenciana. Es una infraestructura clave utilizada por empresas de turismo activo de Alicante y Murcia para bautismos de pared y cursos de progresión vertical intermedia, operando bajo normativas municipales de conservación del entorno de la sierra.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90860','activo','Escuela de Escalada de Xaló (Sectores de Bérnia / Sierra de Bérnia - Forat de Bérnia) y Barranco de la ruda (Estacional)','Formato de prestigio regional en el interior de la Marina Alta. Las impresionantes crestas calcáreas de la Sierra de Bérnia ofrecen itinerarios deportivos de placa y líneas de aventura tradicionales semiequipadas que exigen el uso de empotradores intermedios. Cuenta con reuniones homologadas con argolla de acero inoxidable revisadas por clubes locales. Las agencias operan regularmente en la zona combinando el guiado en aristas con el descenso del barranco seco aneja, respetando la normativa ambiental de protección de la avifauna rupícola rupestre coordinada por la conselleria. Hemos completado la provincia de Alicante de manera exhaustiva y rigurosa, unificando todos sus grandes núcleos activos y aplicando fielmente los filtros de exclusión del proyecto. La siguiente provincia de la Comunidad Valenciana por orden alfabético estricto es Castellón (Castelló), poseedora de grandes enclaves de aventura en roca y agua como los estrechos del río Mijares en Montanejos o las ferratas de la comarca de Els Ports.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12031','activo','Escuela de Escalada de la Cantera de Borriol y sectores de la Sierra de Borriol','Infraestructura de rango local y provincial bien equipada sobre un frente de caliza compacta recuperado. Al carecer de grandes desniveles o itinerarios de varios largos de carácter alpino, funciona como el principal centro docente de la zona costera de Castellón para bautismos de escalada, prácticas de maniobras de cuerdas y formaciones técnicas de clubes, operando bajo las normativas municipales de seguridad y control ambiental.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12045','activo','Vía Ferrata de Cinctorres (Roca del Migdia)','Formato técnico de prestigio regional situado en la histórica comarca de Els Ports. Progresa de forma muy aérea sobre un farallón calcáreo vertical, equipado con escalones cincados fijados con resina epoxi de alta resistencia y una línea de vida continua certificada. Cuenta con un puente de mono de unos 12 metros de longitud. Es utilizada de forma regular por empresas de aventura locales para el guiado comercial de iniciación avanzada y bautismos de altura, respetando la normativa biológica comarcal de protección de aves rapaces.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12046','activo','Barranco del Salinas (Barranco de Cirat) y Barranco del Carbo (Zona limítrofe)','Prestigio regional en el Alto Mijares. El barranco es de carácter torrencial calizo y ofrece una progresión encajonada con una sucesión de 7 rápeles técnicos consecutivos, destacando un resalte vertical de 22 metros de altura en caída libre que exige un dominio preciso de las cabeceras. Cuenta con anclajes inoxidables con doble argolla revisados por la federación (FEMECV). Su uso empresarial está regulado por la Generalitat, sirviendo como un excelente recurso formativo para agencias de la provincia.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46118','activo','Barranco del Gorgo de la Escalera y zonas de rápel técnico asociadas','Prestigio regional con un alto volumen de operaciones comerciales. Es un desfiladero calizo de caudal permanente estacional que ofrece un descenso muy dinámico con rápeles cortos (resalte máximo de 10 metros), estrechos de nado obligatorio y saltos controlados a pozas profundas que exigen el uso de chaleco y casco. Cuenta con una estricta regulación de acceso y aforo coordinada con los agentes forestales de la Generalitat Valenciana para salvaguardar el ecosistema fluvial, registrando gran afluencia estival de agencias de turismo activo.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12079','activo','Escuela de Escalada de Montanejos (Hoces del Mijares: El Estrecho, Pared de los Diablos), Barranco de la Maimona y Tramo de Aguas Bravas del Río Mijares','Impacto Internacional / Icono Supremo de Aventura. Montanejos es uno de los grandes centros neurálgicos de los deportes de aventura y la roca vertical del este peninsular. El imponente Desfiladero de los Estrechos alberga más de 1.500 vías de escalada perfectamente equipadas sobre caliza gris y naranja de una calidad y adherencia excelentes. El Barranco de la Maimona complementa el enclave con pasillos hiperencajonados calizos de gran envergadura y rápeles técnicos. El río Mijares ofrece tramos con corrientes, trenes de olas y rulos técnicos garantizados todo el verano gracias a los desembolses de la presa superior de Arenoso, operando de forma diaria decenas de empresas de rafting. La regulación ambiental es exhaustiva: paradas biológicas rigurosas coordinadas por la Generalitat por protección del águila perdicera y el buitre leonado de febrero a julio, control estricto de accesos y obligatoriedad de registro oficial para las empresas de turismo activo operantes.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12080','activo','Escuela de Escalada de la Senda del Castillo y zonas de progresión vertical tradicionales de la comarca','Formato de prestigio regional. Los muros calcáreos que configuran los cortados geológicos del entorno monumental de Morella albergan vías de escalada técnica de placa perfectamente equipadas con parabolts inoxidables de métrica 12 y reuniones homologadas con argolla. Las empresas locales operan de forma regular utilizando estos sectores para cursos de formación técnica intermedia. Cuenta con restricciones medioambientales por nidificación de rapaces forestales rupícolas entre los meses de febrero y junio, coordinadas por los agentes ambientales de la conselleria.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12081','activo','Barranco del Salto de la Novia (Tramo del cañón del río Palancia) y zonas de rápel técnico','Prestigio regional con alto impacto visual y comercial. La espectacular cascada del Salto de la Novia cuenta con instalaciones fijas de cabecera con parabolts químicos inoxidables ensayados para permitir la práctica técnica del rápel sobre la colosal pared húmeda caliza de 30 metros de altura. Exige una planificación precisa respecto a los caudales fluviales estacionales del río Palancia. Su uso comercial por agencias de aventura está estrictamente supeditado a las autorizaciones anuales de la dirección de Medio Ambiente de la Generalitat y del ayuntamiento para el control de la seguridad.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12130','activo','Barranco del Río Carbo (Catarata del Carbo) y Escuela de Escalada de Penyagolosa (Sectores compartidos)','Grandes Referentes Nacionales a los pies del macizo de Penyagolosa. El barranco del río Carbo ofrece un descenso calizo de caudal permanente y aguas cristalinas hiperfrías con una sucesión de saltos técnicos, toboganes rápidos y rápeles encajonados bajo cascadas que exigen un buen nivel de natación defensiva. Dispone de equipamiento químico certificado. Al localizarse en el interior del Parque Natural de la Penyagolosa, la actividad empresarial requiere declaración responsable, permisos específicos y control estricto de los aforos diarios.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12142','activo','Vía Ferrata de Zucaina (Ferrata del Barranco del Agua / Los Estrechos) y zonas de aventura en roca','Prestigio regional en el Alto Mijares. Es una excelente infraestructura técnica municipal que progresa de forma muy aérea sobre las paredes calizas del desfiladero. Cuenta con un puente tibetano tenso de cables, una pasarela de madera suspendida al vacío y una salida deportiva con un ligero extraplomo que exige buena tracción de brazos de los clientes de turismo activo. Está homologada e inspeccionada periódicamente bajo normativas de ingeniería de la FEMECV, requiriéndose el registro previo obligatorio para el control de la seguridad comarcal. Hemos completado de manera exhaustiva y rigurosa la provincia de Castellón, filtrando de acuerdo a los criterios del proyecto y conservando exclusivamente las joyas de la roca y el agua de la provincia. La siguiente provincia de la Comunidad Valenciana por orden alfabético estricto es Valencia (València), la última de la región, poseedora de grandes enclaves de aventura en roca y agua como el río Cabriel técnico en Venta del Moro o las ferratas de la comarca de Los Serranos.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46038','activo','Vía Ferrata de La Pobleta (Andilla)','Infraestructura de rango local y formato provincial instalada sobre paredes de roca caliza compacta en la comarca de Los Serranos. Cuenta con un itinerario vertical limpio equipado con escalones de acero cincado, una línea de vida continua homologada y un puente tibetano corto de unos 12 metros de longitud que aporta sensación aérea. Es un recurso muy explotado por empresas de aventura de Valencia capital para bautismos de altura y formación técnica de iniciación, operando bajo regulaciones municipales coordinadas de aforo.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46039','activo','Barranco del Gorgo de la Escalera (Tramo técnico del río Anna)','Prestigio regional con un alto volumen de facturación y operaciones comerciales en la Canal de Navarrés. Es un desfiladero calizo de caudal permanente que ofrece un descenso muy dinámico y estético, ideal para el guiado comercial, con tres rápeles técnicos consecutivos (resalte máximo de 25 metros bajo una gran cascada), estrechos de nado obligatorio y saltos controlados a pozas profundas. Cuenta con una estricta regulación de acceso y aforo coordinada con los agentes forestales de la Generalitat Valenciana y el ayuntamiento (con cobro de ecotasa de acceso) para salvaguardar el ecosistema fluvial, registrando gran afluencia estival de agencias de turismo activo.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46077','activo','Escuela de Escalada de Buñol (Sectores del Barranco de Carcalín y Pared de la Jarra) y Barranco de Carcalín (Estacional)','Grandes Referentes Nacionales. El impresionante cañón calizo del Barranco de Carcalín es una de las escuelas de escalada más densas, técnicas e históricas de la provincia, albergando más de 300 vías perfectamente equipadas con químicos y parabolts inoxidables de métrica 12. El cauce seco del barranco complementa la oferta con una sucesión de rápeles e instalaciones de fortuna ideales para escuelas de montaña. Cuenta con paradas biológicas rigurosas decretadas por la conselleria en sectores específicos por nidificación de rapaces rupícolas rupestres entre febrero y junio, registrando una alta densidad de cursos formativos de técnicos de montaña de la federación (FEMECV).','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46079','activo','Escuela de Escalada del Cañón del Río Tuejar y zonas de rápel técnico asociadas al Acueducto de Peña Cortada','Formato de prestigio regional en la comarca de Los Serranos. Las imponentes paredes de caliza ocre que flanquean el entorno monumental y geológico de Peña Cortada albergan itinerarios deportivos técnicos de placa perfectamente equipados. Las agencias operan regularmente en la zona para cursos de iniciación a las técnicas verticales de montaña y bautismos de escalada debido a su rápido acceso, respetando de forma estricta las directrices de Medio Ambiente por protección de avifauna rupícola y los planes de conservación arqueológica.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46112','activo','Escuela de Escalada de Chulilla (Hoces del Río Turia / Sectores del Oasis, El Muro de las Lamentaciones, Canyada de la Mina)','Impacto Internacional / Icono Supremo de Aventura. Chulilla es uno de los santuarios mundiales absolutos de la escalada deportiva en roca caliza, atrayendo de forma permanente a deportistas de élite de los cinco continentes durante los meses de otoño, invierno y primavera. Las monumentales Hoces del Río Turia ofrecen murallas verticales de caliza naranja y gris de hasta 160 metros de caída absoluta, famosas por albergar líneas de continuidad extrema de más de 40 metros de longitud sobre regletas perfectas y chorreras técnicas. Cuenta con más de 1.000 vías equipadas con los máximos estándares internacionales. La regulación de la Generalitat Valenciana es exhaustiva: prohibido taxativamente el vivac incontrolado, estacionamiento de furgonetas camperizadas regulado y cierres biológicos estrictos por nidificación del águila perdicera y el halcón peregrino de enero a agosto en los sectores del cañón profundo (como los Puentes Colgantes), operando de forma continua múltiples guías internacionales.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46099','activo','Barranco de la Otonel (Cañón de los Chorradores de Otonel), Barranco del Bujete y Vía Ferrata de Cortes de Pallás (En proyecto avanzado)','Grandes Referentes Nacionales en el interior de la provincia. El barranco de Otonel es uno de los descensos acuáticos calizos más espectaculares y técnicos de la comunidad, caracterizado por una garganta kárstica hiperencajonada que ofrece un caudal permanente o estacional regulado, con una impresionante sucesión de más de una docena de rápeles (destacando el colosal rápel final de 30 metros de altura que vuela directamente sobre el embalse de Cortes). Exige un dominio absoluto de la gestión de cuerdas en cabeceras expuestas y pasamanos de instalación obligatoria. Su uso está estrictamente regulado en las directrices ambientales de la Junta y la Confederación Hidrográfica del Júcar (CHJ), requiriéndose la tramitación previa de autorizaciones y el uso obligatorio de neopreno completo debido a las bajas temperaturas estacionales del agua.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46131','activo','Escuela de Escalada de Gandia (Sectores del Barranc del B r n l / Marxuquera)','Grandes Referentes Nacionales. La macroescuela caliza de Marxuquera es el santuario indiscutible de la roca de invierno en la comarca de La Safor, famosa por sus muros desplomados jalonados de chorreras y placas técnicas de excelente adherencia. Cuenta con más de 200 vías perfectamente equipadas con químicos certificados y parabolts de métrica 12 mantenidos por colectivos locales de montaña y la federación. Al localizarse en el interior de un entorno costero-montañoso de gran valor, la regulación de la conselleria aplica paradas biológicas temporales estrictas por nidificación de rapaces rupícolas rupestres entre los meses de febrero y junio, registrando alta afluencia anual de escuelas y agencias formativas de toda España.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46133','activo','Escuela de Escalada de Gestalgar (Sectores de la Peña María) y Barranco del Regajo (Estacional)','Prestigio regional consolidado sobre los imponentes farallones calcáreos de la Peña María a orillas del río Turia. Ofrece vías de gran verticalidad y placas técnicas de adherencia microscópica perfectamente equipadas por colectivos locales y reuniones con mosquetón revisadas periódicamente por la FEMECV. El barranco estacional del Regajo complementa el término con rápeles cortos. Cuenta con un estricto protocolo medioambiental coordinado con los agentes ambientales de la zona por protección de aves rapaces nidificantes (búho real y águila real), clausurando sectores específicos entre febrero y junio.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46142','activo','Barranco del Agua (Jalance) y zonas de aventura subacuática técnica en las Hoces del Júcar','Formato de prestigio regional en el Valle de Ayora. El barranco ofrece una fisonomía de estrecha garganta kárstica caliza muy encajonada que exige técnicas de pasamanos en cabeceras húmedas, rápeles técnicos encadenados y badinas profundas de nado obligatorio durante la primavera tras lluvias estacionales intensas. Dispone de reuniones fijas de acero inoxidable ensayadas contra fatiga. Al estar integrado en el entorno de protección de las Hoces del Júcar, las agencias de turismo activo operan bajo declaraciones responsables y control de accesos de la conselleria.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46206','activo','Vía Ferrata de Quesa (Ferrata de los Cañones de Júcar / Los Charcos de Quesa). *','Grandes Referentes Nacionales en la comarca de La Canal de Navarrés. Es una excelente e impresionante infraestructura técnica municipal que progresa de forma muy aérea sobre las paredes calizas del desfiladero de los Charcos de Quesa. Cuenta con un largo puente tibetano tenso de cables, una tirolina técnica de unos 30 metros de longitud (que requiere polea para cable de acero tándem speed) y una variante deportiva avanzada con un extraplomo muy exigente que pone a prueba la fuerza de brazos de los clientes avanzados. Está homologada e inspeccionada bajo normativas de ingeniería de la FEMECV, requiriéndose el registro previo obligatorio a través del ayuntamiento para el control de la seguridad y el aforo diario de las empresas de turismo activo operadoras.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46246','activo','Barranco del Río Verde (Tous) y Escuela de Escalada de Tous (Sectores de la Cantera y Pared de la presa)','Prestigio regional con notable interés geológico e hidrológico. El barranco del río Verde ofrece un descenso calizo de caudal permanente de origen kárstico y aguas transparentes con una sucesión de saltos técnicos, toboganes naturales y rápeles encajonados que exigen un buen nivel de natación defensiva. Dispone de reuniones e instalaciones fijas de anclajes aprobados por colectivos locales de montaña. Al localizarse en el interior de las zonas de reserva de la comarca de la Ribera Alta, la actividad empresarial requiere declaración responsable y control de accesos coordinado con la conselleria y la CHJ.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46254','activo','Río Cabriel (Cañón de las Hoces del Cabriel - Tramo técnico de Aguas Bravas de Tamayo a los Cuchillos / El Retorno)','Impacto Internacional / Icono de Aventura. El río Cabriel a su paso por las espectaculares e imponentes Hoces de los Cuchillos de Venta del Moro es el gran templo indiscutible y absoluto del rafting y las aguas bravas de toda la zona centro y este de la península ibérica, concentrando la mayor densidad de empresas de turismo activo operantes de la comunidad. Ofrece rápidos técnicos consolidados comerciales de gran volumen (como "El purgatorio", "El paredón" o "El caos de bloques"), caracterizados por trenes de olas potentes, rulos hidráulicos de gran fuerza y contras muy marcadas que exigen un guiado experto en balsas comerciales de rafting. Su caudal óptimo está garantizado durante todo el verano gracias a los desembolses de la presa superior de Contreras. Al encontrarse englobado en el Parque Natural de las Hoces del Cabriel (Reserva de la Biosfera), la regulación ambiental es sumamente estricta y restrictiva: los puntos de embarque y desembarque están tasados, el tamaño de los grupos guiados está numerado al milímetro y las empresas operan bajo autorizaciones previas del Parque y de la Confederación Hidrográfica del Júcar, manteniendo un control diario de la capacidad de carga mediante guardas forestales del espacio protegido. Con esta provincia damos por concluida oficialmente la Comunidad Autónoma de la Comunidad Valenciana, habiendo catalogado y puntuado alfabéticamente todas sus provincias y municipios activos bajo los parámetros más estrictos de este proyecto nacional de auditoría de turismo activo técnico. Siguiendo el orden alfabético estricto de las Comunidades Autónomas de España, la siguiente es Extremadura. Daremos inicio con su primera provincia por orden alfabético global: Cáceres (un territorio inmenso de montaña atlántica peninsular marcado por el relieve de la Sierra de Gredos extremeña, los barrancos del Valle del Jerte, la mítica Garganta de los Infiernos o las escuelas de escalada de Monfragüe y el entorno calizo/granítico del norte cáceres).','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90841','activo','Garganta de San Gregorio (Barranco de San Gregorio)','Prestigio regional en la comarca de La Vera. Es un descenso sobre granito lavado que recoge las aguas de escorrentía de la Sierra de Gredos, ofreciendo un trazado técnico encajonado con una sucesión de 6 rápeles (con un resalte máximo de 18 metros en cascada), toboganes rápidos y marmitas de gigante que exigen un control riguroso en primavera. Cuenta con reuniones dobles fijadas con parabolts inoxidables ensayados. Al localizarse en un entorno forestal protegido, la actividad de las empresas requiere declaración responsable previa ante la Junta de Extremadura y la Confederación Hidrográfica del Tajo (CHT).','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10024','activo','Vía Ferrata de Baños de Montemayor (Ruta de la Plata / Cantera del Valle del Ambroz)','Prestigio regional con notable proyección en el norte de Extremadura y Castilla y León. Instalada sobre un antiguo frente de cantera granítica muy aérea, cuenta con un recorrido vertical limpio equipado con líneas de vida e ingeniería de cables de última generación, jalonado por un puente tibetano de 20 metros y una variante deportiva con un extraplomo exigente que pone a prueba la fuerza de brazos. Está homologada e inspeccionada bajo normativas de ingeniería de la FEXME, requiriéndose el registro previo obligatorio a través del ayuntamiento para el control de la seguridad de las agencias de turismo activo.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10035','activo','Garganta de las Nogaledas (Barranco de las Nogaledas - Tramos Superior e Inferior)','Grandes Referentes Nacionales y el descenso acuático comercial más repetido e importante de todo el norte de Extremadura. Ubicado en pleno Valle del Jerte, es un cañón de granito de caudal permanente garantizado durante la primavera y el verano, caracterizado por una espectacular sucesión de más de una docena de rápeles técnicos consecutivos (con un resalte máximo de 25 metros bajo cascadas atronadoras), estrechos de nado obligatorio y saltos controlados a pozas profundas. Cuenta con un equipamiento impecable con tensores químicos de alta gama. Su uso comercial por decenas de empresas de turismo activo está estrictamente regulado por la Dirección General de Sostenibilidad de la Junta, requiriéndose autorizaciones y el uso obligatorio de neopreno completo debido a la baja temperatura estacional del agua de montaña.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10072','activo','Escuela de Escalada de Eljas (Sectores de los Riscos de las Torres / Sierra de Gata)','Formato de prestigio regional en el extremo occidental de la Sierra de Gata, colindando con Portugal. Sus imponentes paredes de granito de grano grueso ofrecen una escalada física sobre regletas, fisuras y placas técnicas de gran adherencia. Cuenta con más de 60 vías perfectamente equipadas con parabolts inoxidables de métrica 12 y reuniones homologadas con argolla revisadas por la federación autonómica. Al encontrarse en una zona de Especial Protección para las Aves (ZEPA), las empresas de turismo activo deben respetar la parada biológica estacional por avifauna en sectores específicos entre febrero y julio, coordinada por los agentes ambientales locales.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10079','activo','Garganta Mayor (Barranco de la Garganta Mayor / Tramo de las Pilitas y las Ollas técnicas)','Prestigio regional con alto interés comercial en la comarca de La Vera. El barranco ofrece una fisonomía de garganta granítica encajonada de carácter perenne estacional, caracterizada por rápeles técnicos cortos (resalte máximo de 15 metros), toboganes naturales de gran velocidad esculpidos en la roca y pasajes estrechos de gran belleza geológica que exigen técnicas de pasamanos en cabeceras húmedas. Cuenta con un protocolo medioambiental coordinado con los guardas forestales de la Junta para supervisar los aforos diarios. Es un recurso altamente explotado por agencias locales de aventura debido a su excelente accesibilidad y vistosidad.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10107','activo','Reserva Natural de la Garganta de los Infiernos (Barranco de Los Hoyos / Los Infiernos Acceso Técnico Regulado)','Impacto Internacional / Icono Supremo de Aventura. El barranco de Los Hoyos en el interior de la Garganta de los Infiernos es considerado de forma unánime uno de los descensos graníticos de alta montaña más espectaculares, técnicos e impresionantes del centro peninsular. Es un desfiladero colosal de pasillos hiperencajonados esculpidos por la erosión fluvial en granitos puros, caracterizado por una sucesión de rápeles técnicos de hasta 30 metros de altura bajo cascadas de gran presión, saltos obligatorios de gran precisión, marmitas profundas batidas por la corriente y toboganes gigantescos. Al ubicarse en el corazón de una Reserva Natural Especial, la regulación medioambiental de la Junta de Extremadura es de las más estrictas de España: el acceso técnico está limitado a un cupo diario riguroso gestionado de forma digital, las empresas de guías profesionales operan bajo licencias ambientales específicas y está completamente prohibido salirse de los canales técnicos fluviales habilitados para salvaguardar la flora y fauna endémica.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10110','activo','Garganta de Cuacos (Barranco de la Garganta de Cuacos) y zonas de aventura en alta montaña asociadas','Grandes Referentes Nacionales. Es un descenso de carácter netamente alpino y torrencial que recoge directamente las aguas de deshielo del macizo central de la Sierra de Gredos extremeña. Ofrece una progresión muy encajonada sobre grandes bloques de granito lavado con aguas gélidas, caracterizada por rápeles encadenados bajo cascadas de fuerte presión, pasamanos de instalación obligatoria en cabeceras expuestas y gestión de movimientos hidráulicos peligrosos si el río va crecido. Solo es abordable de forma comercial por agencias especializadas con guías avanzados (TD2) y clientes de nivel técnico contrastado en primavera avanzada o principios de verano, bajo autorizaciones estrictas de la CHT y Medio Ambiente.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10113','activo','Escuela de Escalada de Madroñera (Sectores del Cancho del Castillo)','Infraestructura de rango local e interés provincial situada en el entorno penillanero trujillano. Ofrece paños de roca granítica compacta de excelente adherencia con más de 50 vías reequipadas con parabolts y reuniones de seguridad homologadas con argolla por clubes locales de montaña y la FEXME. Carece de grandes itinerarios de varios largos de carácter alpino, pero funciona como un excelente recurso formativo de proximidad para bautismos de escalada, cursos de gestualidad y maniobras básicas de progresión vertical seca para las agencias del centro de la provincia, operando bajo regulaciones municipales de aforo.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10115','activo','Escuela de Escalada de Los Barruecos (Sectores de las Peñas del Tesoro y Charca del Barrueco de Arriba)','Grandes Referentes Nacionales. El Monumento Natural de Los Barruecos alberga uno de los paisajes graníticos moldeados en domos y "bolos" más espectaculares e icónicos de España. Sus batolitos de granito grueso ofrecen una escalada en bloque (búlder) sumamente física y técnica sobre romos exigentes, regletas ásperas y techos distribuidos en múltiples sectores homologados y catalogados por los manuales de montaña. Las agencias y escuelas técnicas operan de forma intensa para cursos de gestualidad en roca de alta fricción. Al localizarse en un espacio protegido de alto valor ecológico e histórico (con importantes colonias de cigüeña blanca), cuenta con una estricta regulación de la Junta de Extremadura que prohíbe el cepillado agresivo de la roca, limita sectores temporalmente de forma biológica y prohíbe el vivac incontrolado.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10175','activo','Escuela de Escalada de Serradilla (Sectores de las Paredes de la Garganta del Fraile / Monfragüe - Zona limítrofe periférica)','Grandes Referentes Nacionales con un régimen ambiental restrictivo extremo debido a su vecindad con el Parque Nacional de Monfragüe. Sus imponentes paredes verticales de cuarcita armoricana de una dureza extrema ofrecen una escalada física sobre regletas y fisuras netas de excelente calidad que exigen una buena gestión de la técnica gestual. Cuenta con reuniones homologadas con argolla inoxidable y parabolts revisados por la federación. Al encontrarse en la zona de influencia y reserva del Parque Nacional y áreas de cría críticas del buitre negro, el águila imperial ibérica y el alimoche, la regulación de la Junta es drástica: se decreta el cierre biológico total de la escalada en la práctica totalidad de los sectores entre los meses de enero y agosto, obligando a las agencias a operar de forma exclusiva en la temporada de otoño e invierno bajo visados ambientales anuales estrictos. Hemos completado la provincia de Cáceres de manera exhaustiva y rigurosa, unificando todos sus grandes núcleos de la A a la Z y aplicando de forma inflexible las reglas de exclusión del proyecto. La siguiente provincia de Extremadura por orden alfabético estricto es Badajoz (la última de esta Comunidad Autónoma, que cuenta con zonas técnicas muy específicas de escalada y ferratas sobre las cuarcitas de las sierras centrales badajocenses, como en Alange o Cabeza del Buey).','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90474','activo','Escuela de Escalada de Alange (Sectores de las Paredes de la Umbría y el Castillo)','Grandes Referentes Nacionales y el principal santuario de la roca en la provincia de Badajoz. Sus imponentes paredes de cuarcita armoricana, situadas junto al embalse de Alange, ofrecen una escalada sumamente física sobre regletas, fisuras y desplomes de excelente calidad. Cuenta con más de un centenar de vías perfectamente equipadas con químicos certificados y parabolts inoxidables mantenidos por la FEXME. Al encontrarse dentro de una Zona de Especial Protección para las Aves (ZEPA) y cerca de restos arqueológicos, cuenta con una estricta regulación de la Junta de Extremadura que aplica paradas biológicas rigurosas coordinadas por los agentes forestales entre los meses de febrero y julio por nidificación de rapaces rupícolas (alimoche y halcón peregrino).','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06007','activo','Vía Ferrata de Almorchón (Sierra de Almorchón) y Escuela de Escalada de Almorchón','Prestigio regional con notable interés deportivo en la comarca de La Serena. La Vía Ferrata es una infraestructura moderna instalada sobre los espectaculares riscos de cuarcita del peñón de Almorchón, equipada con escalones cincados, líneas de vida continuas de acero inoxidable y un puente tibetano que aporta sensación aérea. Los sectores de escalada anexos ofrecen líneas técnicas de autoprotección. Toda la instalación está sujeta a los planes de conservación de la avifauna de la Junta, requiriéndose el registro previo municipal obligatorio para el control de la seguridad y el aforo de las empresas de turismo activo operadoras.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14036','activo','Escuela de Escalada de la Sierra de Hornachuelos (Sectores del Estrecho)','Infraestructura de rango local y formato provincial bien equipada sobre un frente de cuarcitas compactas de gran dureza. Ofrece paños de roca con vías de placa y fisuras verticales netas que sirven de excelente plataforma docente para las empresas locales que realizan cursos de iniciación a las técnicas de aseguramiento y bautismos de escalada en roca. Su uso comercial está supeditado a las directrices ambientales de la Junta de Extremadura para salvaguardar el hábitat de rapaces forestales rupícolas rupestres rupícolas durante la primavera.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06100','activo','Vía Ferrata de Peñalsordo (Peñón de Peñalsordo) y zonas de rápel técnico asociadas','Infraestructura de rango local y desarrollo provincial estratégico. Dispone de un itinerario vertical limpio sobre roca cuarcítica que supera un desnivel de 50 metros con una línea de vida continua de última generación y peldaños de acero inoxidable bien dimensionados. Cuenta con pasos de notable verticalidad aéreos pero sin desplomes atléticos, lo que la convierte en una instalación muy rentable para las empresas de aventura de la comarca para el guiado comercial de grupos escolares o turismo familiar técnico que busca una aproximación segura a la altura.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06161','activo','Escuela de Escalada de ZarzaCapilla (Sectores de la Sierra de las Cruces)','Formato de prestigio regional en el extremo oriental de la provincia. Los crestones de cuarcita de la Sierra de las Cruces ofrecen muros de gran verticalidad y placas técnicas de adherencia perfectamente equipadas con parabolts y reuniones de seguridad homologadas con argolla por colectivos locales de montaña. La regulación de uso obliga al respeto estricto de las restricciones biológicas estacionales por avifauna en sectores específicos entre febrero y junio, coordinadas por la Consejería de Agricultura, Desarrollo Rural, Población y Territorio. Con esta provincia damos por concluida oficialmente la Comunidad Autónoma de Extremadura, habiendo catalogado de forma alfabética y rigurosa todos sus municipios activos y omitiendo cualquier recurso puramente recreativo. Siguiendo el orden alfabético estricto de las Comunidades Autónomas de España, la siguiente es Galicia. Es un territorio atlántico colosal caracterizado por sus grandes ríos de aguas bravas estables, cañones encajonados sobre granito lavado y escuelas de escalada de fisuras tradicionales, y daremos inicio con su primera provincia por orden alfabético global: A Coruña (poseedora de grandes enclaves como las escuelas de escalada granítica costera en el Monte Louro o las ferratas de la comarca).','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01004','activo','Escuela de Escalada de Boiro (Sectores del Monte Pindo - Extensión Sur / Rías Baixas)','Formato técnico de prestigio regional. Sus muros y bloques graníticos de grano grueso ofrecen una escalada adherente y física sobre regletas y fisuras, equipada con parabolts inoxidables homologados por la Federación Galega de Montañismo (FGM). La regulación medioambiental exige un estricto control debido a la presencia de hábitats protegidos por la Red Natura 2000. Es utilizada por empresas de turismo activo de las rías para cursos de perfeccionamiento técnico gestual y bautismos en roca natural.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01007','activo','Escuela de Escalada del Monte Pindo (Sectores de la Moa y el Pedrullón) y Barranco del Río Xallas (Desembocadura de Ézaro - Entorno compartido técnico)','Grandes Referentes Nacionales e icono de la aventura gallega. El colosal Olimpo Celta (Monte Pindo) ofrece murallas y agujas de granito rosa perfectas para la escalada clásica de autoprotección con friends y fisureros en reuniones expuestas. Por su parte, las secciones técnicas asociadas al río Xallas exigen maniobras de cuerda complejas y control estricto de caudales torrenciales condicionados por los desembalses de la central hidroeléctrica superior. La regulación de la Xunta de Galicia es estricta al tratarse de un Espacio Natural Protegido, requiriéndose declaraciones responsables obligatorias para empresas comerciales.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15036','activo','Escuela de Escalada de Cabo Prior (Sectores de acantilados costeros)','Prestigio regional con notable singularidad geológica. Las paredes graníticas y de gneis de Cabo Prior caen verticales sobre el océano Atlántico, ofreciendo itinerarios técnicos de placa expuestos al viento y a la corrosión salina. Toda la infraestructura cuenta con anclajes químicos de acero inoxidable de alta gama (calidad marina A4/316) revisados periódicamente por colectivos locales para garantizar la seguridad. Las empresas operan de forma regular evitando los periodos de nidificación de avifauna marina regulados por Augas de Galicia y Medio Ambiente de la Xunta.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15045','activo','Barranco del Río Santa Baia y Barranco del Río Nuveira','Grandes Referentes Nacionales. Mazaricos es uno de los epicentros del barranquismo en Galicia. Sus descensos sobre granito lavado ofrecen un caudal permanente excelente, caracterizado por una sucesión de rápeles técnicos consecutivos (con un resalte máximo de 20 metros bajo cascadas potentes), toboganes rápidos esculpidos por la erosión y saltos limpios a pozas profundas. Cuenta con reuniones homologadas de acero inoxidable ensayadas contra fatiga. Exige el uso obligatorio de neopreno completo debido a las bajas temperaturas del agua y la tramitación de permisos específicos ante la Consellería de Medio Ambiente.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15053','activo','Escuela de Escalada del Monte Louro (Sectores de la Ensenada)','Prestigio regional consolidado sobre el impresionante domo granítico del Monte Louro, que domina la entrada de la ría de Muros y Noia. Ofrece paños de roca con una adherencia microscópica excepcional y fisuras netas perfectamente equipadas con químicos certificados. Al tratarse de un Espacio Natural Protegido e Interés Paisajístico, la actividad de las empresas de turismo activo está estrictamente monitorizada por los agentes ambientales, aplicando paradas biológicas temporales por protección de rapaces y aves costeras entre los meses de febrero y junio.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15062','activo','Vía Ferrata de Outes (Vía Ferrata do Freixo)','Infraestructura de rango local y desarrollo provincial estratégico. Dispone de un itinerario vertical limpio sobre un farallón granítico que supera un desnivel de 60 metros con una línea de vida continua y peldaños de acero inoxidable bien fijados con resina epoxi de alta resistencia. Cuenta con un pequeño puente de cable corto que añade sensación aérea. Es muy utilizada por las agencias de turismo activo locales para bautismos de altura y cursos básicos de progresión vertical de media jornada, operando bajo regulaciones y tasas de control municipal. Hemos completado la provincia de A Coruña integrando todos sus municipios con actividad técnica real regulada y aplicando de manera estricta el filtro de exclusión de zonas recreativas simples. Siguiendo el orden alfabético estricto de las provincias de Galicia, la siguiente es Lugo (un territorio inmenso marcado por el relieve alpino de los Ancares, los cañones profundos de la Ribeira Sacra y ríos potentes de aguas bravas). Si estás de acuerdo, facilítame el visto bueno para proceder con la provincia completa de Lugo.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90548','activo','Escuela de Escalada de Carballedo (Sectores de los Penedos do Sil) y cañón fluvial del Río Sil (Tramo compartido Ribeira Sacra)','Prestigio regional. Ubicada en los imponentes cortados graníticos que caen sobre el cañón del Sil, esta escuela ofrece vías de adherencia y fisuras que requieren una buena gestión de los pies. Cuenta con parabolts inoxidables homologados y reuniones revisadas por la Federación Galega de Montañismo (FGM). Al encontrarse dentro de la Red Natura 2000 y el espacio protegido de la Ribeira Sacra, las empresas de turismo activo operan bajo estrictas autorizaciones estacionales de la Xunta de Galicia, respetando los periodos de nidificación de avifauna (como el águila real y el búho real) de febrero a junio.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27017','activo','Barranco del Río Ferreiriño, Barranco del Río Carballido y Escuela de Escalada de O Courel','Grandes Referentes Nacionales. O Courel es uno de los grandes santuarios de la aventura en el noroeste peninsular. Sus cañones excavados sobre calizas compactas y pizarras duras ofrecen descensos de carácter alpino con aguas gélidas y caudales potentes durante la primavera. El barranco del Ferreiriño destaca por una sucesión de 8 rápeles técnicos consecutivos (con un resalte máximo de 22 metros bajo cascadas) que exigen un dominio absoluto de la gestión de cuerdas. Al estar catalogado como Geoparque Mundial de la UNESCO, la actividad de las empresas está estrictamente monitorizada por la Consellería de Medio Ambiente, requiriéndose declaraciones responsables rigurosas para el guiado de grupos.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27030','activo','Barranco del Río Masma (Catarata de Santo Estevo do Ermo) y zonas de rápel técnico estacional','Formato técnico de prestigio regional en la Mariña Lucense. El barranco es de carácter torrencial, ofreciendo un trazado encajonado de gran belleza geológica con rápeles de hasta 20 metros de altura que vuela sobre las cascadas del entorno de Santo Estevo. Cuenta con reuniones e instalaciones fijas inoxidables revisadas periódicamente por clubes locales de montaña. Su uso comercial por agencias de aventura se concentra en los meses de invierno y primavera aprovechando el régimen de lluvias, operando bajo las correspondientes autorizaciones medioambientales y municipales.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27034','activo','Río Navia (Tramo técnico de Aguas Bravas de Navia de Suarna) y zonas de escalada menor asociadas a Os Ancares','Prestigio regional en el entorno de la Reserva de la Biosfera de Os Ancares Lucenses. El río Navia se encaja de forma abrupta ofreciendo un descenso rápido con trenes de olas continuos, rulos hidráulicos y contras marcadas entre bloques de piedra que exigen maniobras de navegación de alta precisión técnica. Es un punto de entrenamiento clásico para clubes locales y empresas de aventura durante la primavera. Las operaciones comerciales están sujetas a la normativa de la Confederación Hidrográfica del Cantábrico (CHC) y Medio Ambiente de la Xunta, requiriéndose neoprenos de gran espesor debido a las bajas temperaturas del agua alpina.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27041','activo','Río Miño (Tramo técnico de Aguas Bravas del río Miño superior / Peares) y Escuela de Escalada de Pantón','Prestigio regional con notable tráfico comercial en la confluencia de los ríos Miño y Sil. El tramo fluvial ofrece corrientes dinámicas, trenes de olas potentes y contras marcadas reguladas por los desembalses de las centrales hidroeléctricas superiores, garantizando caudal técnico óptimo para el guiado comercial de rafting en la época estival. Los sectores de escalada anexos disponen de anclajes químicos revisados por colectivos de montaña. Regulado por Augas de Galicia y vigilado por los planes de conservación de la Ribeira Sacra, registrando un volumen constante de operaciones de agencias de turismo activo.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27050','activo','Barranco del Río Soldón, Vía Ferrata de Quiroga (En proyecto avanzado / O Regueiro) y Escuela de Escalada de Quiroga','Grandes Referentes Nacionales dentro del Geoparque Mundial Montañas do Courel. El barranco del río Soldón ofrece un descenso sobre granito lavado de caudal permanente estacional con rápeles encadenados de hasta 18 metros de altura, pasajes encajonados y badinas profundas de nado obligatorio en primavera. Los sectores de escalada cuentan con equipamiento impecable mediante parabolts de acero inoxidable de métrica 12. Toda la actividad de las empresas está regulada de forma estricta por la Xunta de Galicia para evitar el impacto ambiental sobre los endemismos y la avifauna del entorno de montaña, sirviendo de base técnica de operaciones en la zona sur lucense.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27052','activo','Vía Ferrata de Ribas de Sil (Ferrata de Loureiro) y tramo técnico del Río Sil inferior','Infraestructura de rango regional bien equipada sobre un espolón de granito y pizarra que domina de forma aérea el cañón del río Sil. Cuenta con un recorrido predominantemente vertical de 70 metros de desnivel equipado con líneas de vida continuas de acero inoxidable y peldaños ensayados contra fatiga. Dispone de pasos con notables vistas al valle pero sin exigencias físicas extremas. Su uso comercial es elevado, sirviendo a las agencias locales para bautismos de altura y formación de técnicos deportivos de iniciación, operando bajo las normativas del ayuntamiento y las directrices ambientales de la Ribeira Sacra. Hemos completado la provincia de Lugo de manera exhaustiva y rigurosa, unificando todos sus grandes núcleos activos y aplicando fielmente los filtros de exclusión del proyecto. La siguiente provincia de Galicia por orden alfabético estricto es Ourense, poseedora de grandes enclaves de aventura en roca y agua como los barrancos alpinos del Parque Natural Baixa LimiaSerra do Xurés o las ferratas y tramos de aguas bravas de la comarca del Ribeiro.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90509','activo','Barranco del Río Brul','Prestigio regional. Es uno de los descensos más estéticos de la provincia, excavado sobre granito muy compacto. Cuenta con una sucesión de 6 rápeles técnicos (con un resalte máximo de 15 metros), toboganes rápidos y marmitas profundas de nado obligatorio. Exige neopreno completo debido a la baja temperatura del agua, que mantiene un caudal óptimo durante la primavera. Las empresas operan bajo autorización expresa de la Consellería de Medio Ambiente y de la Confederación Hidrográfica del MiñoSil.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90521','activo','Escuela de Escalada de Carballeda (Sectores de Sobradelo / Peña Trevinca)','Prestigio regional con proyección nacional al situarse en el entorno del macizo de Peña Trevinca (el techo de Galicia). Sus paredes de pizarra y cuarcita ofrecen una escalada física sobre regletas y fisuras muy netas. Dispone de reuniones homologadas con argolla y parabolts inoxidables revisados por la Federación Galega de Montañismo (FGM). Cuenta con regulaciones medioambientales estrictas coordinadas por la Xunta de Galicia para proteger el hábitat de rapaces rupícolas de alta montaña, aplicando paradas biológicas entre febrero y junio.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34003','activo','Barranco del Río Edo y zonas asociadas de la Ribeira Sacra','Formato técnico de prestigio regional. El barranco discurre encajonado en un entorno de granito y pizarras, ofreciendo rápeles técnicos de hasta 18 metros de altura, pequeños pasamanos de instalación obligatoria en cabeceras húmedas y badinas que exigen nado defensivo en primavera. Su equipamiento cuenta con anclajes fijos inoxidables homologados. La actividad de las empresas está sujeta a las autorizaciones ambientales de la Xunta dentro del espacio protegido de la Ribeira Sacra.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32042','activo','Barranco del Río Fecha (Corgas da Fecha) y Escuela de Escalada del Xurés','Grandes Referentes Nacionales con alta proyección internacional por su carácter transfronterizo. El barranco de la Fecha es el descenso alpino sobre granito por excelencia en el sur de Galicia, famoso por salvar un desnivel brutal mediante cascadas colosales y rápeles encadenados muy técnicos (destacando un resalte vertical de 30 metros expuesto a la fuerza del agua). Al ubicarse en el corazón del Parque Natural Baixa Limia-Serra do Xurés, la regulación medioambiental es severa: los cupos diarios de deportistas y empresas están limitados digitalmente por la Xunta de Galicia para proteger el tritón ibérico y la flora rupícola endémica, requiriéndose neoprenos completos y guías titulados.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32046','activo','Barranco del Río Cerves (Tramos Superior e Inferior)','Grandes Referentes Nacionales y uno de los cañones con mayor volumen de guiado comercial del noroeste. El río Cerves ha esculpido las famosas pozas de Melón en un granito rosa muy pulido, ofreciendo un caudal permanente excelente, saltos técnicos de hasta 8 metros, toboganes naturales de gran velocidad y un rápel final espectacular de 30 metros de altura en caída vertical. Dispone de un equipamiento impecable mediante tensores químicos inoxidables homologados. Las agencias operan diariamente de primavera a otoño bajo autorizaciones estrictas de la Confederación Hidrográfica y Medio Ambiente, controlando de forma rigurosa la capacidad de carga del espacio natural.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32052','activo','Vía Ferrata de Nogueira de Ramuín (Ferrata do Sil / San Lourenzo) y sectores de escalada de los Cañones del Sil','Prestigio regional con excelente proyección y motor del turismo activo en la Ribeira Sacra ourensana. La Vía Ferrata es una infraestructura moderna instalada de forma muy aérea sobre los paredones graníticos que caen a plomo sobre el río Sil, equipada con una línea de vida continua de última generación y puentes tibetanos de cable de gran longitud que aportan una gran sensación psicológica de altura. Los sectores de escalada anexos ofrecen líneas técnicas de adherencia en placas perfectas. Ambas instalaciones requieren el visado ambiental de la Xunta debido a la extrema protección paisajística y biológica del entorno.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32056','activo','Río Miño (Tramo técnico de Aguas Bravas de Frieira a Barca de Trobo) y zonas de kayak de aventura','Prestigio regional fluvial en la frontera con Portugal. Este tramo del río Miño ofrece corrientes dinámicas, trenes de olas muy constantes y rulos técnicos regulados por los desembolses de la central hidroeléctrica superior, lo que garantiza un caudal abundante y estable para el rafting comercial incluso durante los meses de verano. Cuenta con una infraestructura logística pública homologada de embarque. Las actividades de las empresas están coordinadas por Augas de Galicia y reguladas bajo estrictas medidas de seguridad internacional debido al carácter fronterizo del cauce. Hemos completado la provincia de Ourense integrando todos sus municipios con actividad técnica real de roca y agua profunda, aplicando fielmente las directrices del proyecto. La siguiente provincia de Galicia por orden alfabético estricto es Pontevedra (la última de la comunidad autónoma, poseedora de grandes ríos de aguas bravas comerciales como el Miño en Arbo o el Ulla, y barrancos graníticos como el del río Verdugo).','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90533','activo','Río Miño (Tramo internacional de Aguas Bravas de los Pesqueiros: Arbo a Frieira / Melgaço)','Impacto Internacional / Icono de Aventura. El río Miño a su paso por Arbo es el gran templo indiscutible del rafting comercial y las aguas bravas de gran volumen en toda Galicia, concentrando la mayor densidad de empresas de turismo activo de la región. El tramo destaca por sus imponentes "pesqueiras" romanas (estructuras de piedra que encajonan el agua) que generan rápidos técnicos muy estables con trenes de olas potentes, rulos y contras marcadas que exigen un guiado experto en balsas de rafting. Su caudal masivo está garantizado durante todo el verano gracias a la regulación de los embalses de la cuenca. Al ser un río fronterizo con Portugal, la normativa de seguridad de las capitanías marítimas y de Augas de Galicia es severa, requiriéndose guías profesionales titulados (TD2).','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90537','activo','Barranco del Río Tea (Garganta de Fofe) y Escuela de Escalada de Covelo','Prestigio regional en la comarca de O Condado. El barranco de Fofe ofrece un excelente descenso sobre granito lavado con un caudal perenne muy estético, caracterizado por rápeles técnicos de hasta 15 metros, toboganes rápidos y marmitas de gigante profundas de nado obligatorio. Dispone de reuniones homologadas con doble argolla de acero inoxidable revisadas por la FGM. Al encontrarse dentro de una Zona de Especial Conservación (ZEC) del río Tea, la actividad de las empresas está supeditada a autorizaciones anuales de la Xunta de Galicia para mitigar el impacto sobre el ecosistema fluvial.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36019','activo','Barranco del Río Parada y Barranco del Río Verdugo (Tramos encajonados)','Grandes Referentes Nacionales en el interior de la provincia. El barranco del río Parada es uno de los descensos graníticos de fuerte caudal estacional más espectaculares y exigentes del sur de Galicia. Ofrece una progresión muy vertical y encajonada que recoge de forma torrencial las copiosas lluvias de la Serra do Suído, exigiendo rápeles técnicos de hasta 30 metros de altura bajo cascadas de gran presión y pasamanos de instalación obligatoria sobre cabeceras expuestas resbaladizas. Su uso comercial por agencias de aventura se concentra en otoño y primavera, requiriéndose permisos explícitos ambientales y neoprenos completos de gran espesor.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36039','activo','Escuela de Escalada de las Canteras de Atios (Frentes de Granito Rosa Porriño)','Grandes Referentes Nacionales. Es la escuela de escalada en roca granítica más densa, técnica e histórica de la provincia de Pontevedra. Se localiza sobre los antiguos frentes inactivos de las colosales canteras de granito rosa, ofreciendo paños completamente verticales y diedros perfectos que exigen una escalada física de regletas netas, adherencia microscópica y bidedos. Alberga más de un centenar de vías perfectamente equipadas con químicos certificados por la Federación Galega de Montañismo. Cuenta con regulaciones de acceso coordinadas con las comunidades de montes y el ayuntamiento para garantizar la seguridad de los deportistas y de las empresas formativas.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90848','activo','Barranco del Río Verdugo (Estrechos de Ponte Caldelas) y zonas de rápel técnico','Formato de prestigio regional. El río Verdugo se encaja en este término abriendo un pasillo calizo y granítico de caudal permanente de gran belleza geológica. El descenso exige técnicas de natación en corrientes, pasos de oposición en paredes pulidas por el agua y saltos técnicos de hasta 6 metros a pozas profundas con casco y chaleco obligatorio. Cuenta con anclajes inoxidables de seguridad homologados. Las agencias locales lo explotan de forma continua durante la primavera y el verano debido a su excelente accesibilidad y alta rentabilidad logística, operando bajo declaraciones responsables ante Augas de Galicia. Con esta provincia damos por concluida oficialmente la Comunidad Autónoma de Galicia, habiendo catalogado y puntuado alfabéticamente todas sus provincias y municipios activos bajo los parámetros más estrictos de este proyecto nacional de auditoría de turismo activo técnico. Siguiendo el orden alfabético estricto de las Comunidades Autónomas de España, la siguiente es la Comunidad de Madrid. Al ser una comunidad uniprovincial.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28030','activo','Escuela de Escalada del Pico de la Miel y Aguja de los Lanchares','Grandes Referentes Nacionales. El Pico de la Miel es un monumental domo granítico de grano grueso que constituye la cuna de la escalada clásica de fisuras y diedros en la sierra norte de Madrid (con vías míticas como la Ezequiel o la Julito). Exige el uso riguroso de empotradores mecánicos para la autoprotección intermedia, aunque dispone de reuniones reequipadas con parabolts inoxidables de métrica 12. Al estar integrado en la zona periférica de protección de la Sierra de Guadarrama, las empresas de turismo activo operan bajo normativas medioambientales de la Comunidad de Madrid que decretan paradas biológicas estrictas por nidificación de aves rapaces (alimoche y águila real) en paños específicos de febrero a julio.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28082','activo','Escuela de Escalada de La Pedriza (Sectores de El Yelmo, El Pájaro, Las Torres)','Impacto Internacional / Icono Supremo de Aventura. La Pedriza del Manzanares es el mayor complejo granítico de morfología dómica de Europa y el santuario mundial indiscutible de la escalada en placa de adherencia microscópica. Su estilo de escalada prescinde de agarres netos y exige un dominio absoluto del equilibrio sobre el granito rosa pulido, con alejes considerables entre seguros que elevan el compromiso psicológico. Cuenta con sectores míticos de varios largos como el risco del Pájaro o el colosal Yelmo. Al estar ubicado en el corazón del Parque Nacional de la Sierra de Guadarrama (y Reserva de la Biosfera), la regulación ambiental es la más estricta de la región: control absoluto de acceso de vehículos por barrera y cupo, prohibición radical del vivac y acampada, y cierres biológicos masivos e inflexibles por nidificación del buitre leonado de enero a agosto en riscos clave. Concentra el mayor volumen de guías de alta montaña (TD2/TD3) y cursos de formación federativa del centro peninsular.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28107','activo','Escuela de Escalada del Pontón de la Oliva (Sectores del Cañón del Lozoya - Límite provincial)','Grandes Referentes Nacionales. A diferencia de la tónica granítica madrileña, Patones ofrece un imponente desfiladero de roca caliza calcatria de coloración ocre, famoso por sus desplomes atléticos jalonados de agujeros y chorreras técnicas de gran continuidad. Cuenta con cientos de vías perfectamente homologadas y equipadas con tensores químicos de alta gama. Su uso por parte de clubes, escuelas de montaña y agencias comerciales es masivo debido a su idoneidad para la escalada invernal. La regulación de la Comunidad de Madrid y el Canal de Isabel II gestiona de forma férrea el estacionamiento y prohíbe la escalada estacional en paños específicos orientados al norte por la nidificación de grandes rapaces de pared entre febrero y junio.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28120','activo','Cascadas de Hielo de Peñalara (Circo de Peñalara / Pared de dos Hermanas - Accesos Técnicos de Alta Montaña)','Grandes Referentes Nacionales. El Circo Glacial de Peñalara, situado a más de 2.000 metros de altitud, es la escuela histórica de formación invernal de la zona centro de España. Durante los meses más fríos, los escurrimientos de la pared de Dos Hermanas y del circo kárstico se congelan por completo, generando cascadas de hielo efímeras y corredores mixtos que funcionan como una excelente infraestructura natural para cursos formativos avanzados de piolets de tracción, tornillos de hielo y autoprotección extrema bajo condiciones invernales severas. Al encontrarse en la Zona de Máxima Reserva del Parque Nacional de la Sierra de Guadarrama, la actividad comercial requiere visados ambientales obligatorios emitidos por el patronato y está limitada estrictamente en número de alumnos por guía de alta montaña.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28143','activo','Barranco del Puerto de Somosierra (Chorrera de los Litueros / Nacimiento del Río Duratón)','Prestigio regional con notable exclusividad por ser el único barranco acuático e instalado técnicamente de toda la Comunidad de Madrid. El descenso discurre sobre un cauce granítico lavado que recoge las aguas de escorrentía del puerto, ofreciendo una progresión muy vertical caracterizada por tres rápeles encadenados muy estéticos (destacando el colosal rápel final de 30 metros de altura que desciende directamente por la cascada de la Chorrera de los Litueros). Cuenta con reuniones de seguridad de doble argolla inoxidables ensayadas contra fatiga. Las empresas de turismo activo operan intensamente durante los meses de primavera aprovechando el deshielo y las lluvias, requiriéndose la declaración responsable correspondiente ante la Confederación Hidrográfica del Duero (CHD) y Medio Ambiente. Con esta provincia damos por concluida oficialmente la Comunidad de Madrid, habiendo catalogado y puntuado alfabéticamente todas sus localidades con actividad real certificada e infraestructuras técnicas homologadas de roca y agua. Siguiendo el orden alfabético estricto de las Comunidades Autónomas de España, la siguiente es la Región de Murcia. Al ser una comunidad uniprovincial.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30008','activo','Escuela de Escalada de Sierra Espuña (Sectores de las Paredes de Leyva - Compartido con Totana)','Grandes Referentes Nacionales. Las monumentales e históricas Paredes de Leyva constituyen uno de los templos de la escalada clásica y de autoprotección de la zona sur y levante peninsular. El imponente muro de caliza gris y ocre ofrece cientos de itinerarios de varios largos de gran continuidad física que exigen una correcta gestión de friends y fisureros en largos intermedios, disponiendo de reuniones homologadas con argolla de acero inoxidable. Al ubicarse en el corazón del Parque Natural de Sierra Espuña, la regulación ambiental de la Comunidad Autónoma es estricta: existen paradas biológicas severas por nidificación de rapaces rupícolas (como el águila real y el halcón peregrino) de febrero a junio, registrando una alta densidad de escuelas y guías formativos.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30011','activo','Río Segura (Tramo de Aguas Bravas del Valle de Ricote: Cieza a Blanca) y Vía Ferrata del Cabezo de la Jordana','Prestigio regional con un altísimo volumen de facturación turística comercial. El río Segura a su paso por el Valle de Ricote ofrece trenes de olas continuos y rápidos comerciales idóneos para el guiado de balsas de rafting estival, garantizando un caudal óptimo gracias a las sueltas agrícolas de los embalses superiores de la cuenca. La ferrata del Cabezo de la Jordana complementa la oferta con un trazado muy estético equipado con líneas de vida e ingeniería de cables de última generación, puente tibetano de cables y pasos aéreos estables. Las empresas operan bajo declaraciones responsables estrictas reguladas por la Confederación Hidrográfica del Segura (CHS).','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30019','activo','Cañón de Almadenes (Tramo técnico de Aguas Bravas del río Segura) y Barranco de los Almadenes (Seco)','Grandes Referentes Nacionales. El monumental Cañón de Almadenes es un desfiladero colosal de paredes calizas de más de 100 metros de altura esculpido por el río Segura. Ofrece pasos de volumen y corrientes potentes de gran fuerza hidráulica ideales para el rafting y kayak avanzado, junto con un barranco seco asociado perfectamente equipado para rápeles técnicos. Al estar catalogado como Espacio Natural Protegido y albergar pinturas rupestres Patrimonio de la Humanidad, la regulación de la Región de Murcia es exhaustiva: el acceso fluvial comercial está tasado, prohibiéndose salirse del cauce técnico delimitado y obligando a las agencias a operar con guías profesionales titulados (TD2).','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30020','activo','Escuela de Escalada de la Sierra de la Pila (Sectores de la Cueva de la Excomunión y Cortado de la Algüeda)','Prestigio regional. Los imponentes cantiles de caliza gris del Parque Regional de la Sierra de la Pila albergan sectores técnicos de gran calidad, caracterizados por placas desplomadas muy físicas sobre agujeros y regletas perfectas equipadas con parabolts inoxidables de métrica 12. Las agencias operan regularmente en otoño y primavera para cursos de tecnificación gestual en roca. Cuenta con paradas biológicas decretadas por Medio Ambiente de la Región de Murcia por nidificación de grandes rapaces de pared entre febrero y junio, controladas estrictamente por los agentes forestales.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30029','activo','Escuela de Escalada de Mula (Sectores del Ferrari, Sector Abuelo) y Barranco de la Cierva (Estacional)','Grandes Referentes Nacionales. Es una de las macroescuelas de escalada en roca caliza más densas, técnicas e importantes de la Región de Murcia, albergando cientos de vías perfectamente equipadas con químicos certificados por la federación de montaña (FMRM). El barranco seco complementa el término con rápeles cortos ideales para la docencia básica de nudos y maniobras con cuerdas. Cuenta con una estricta regulación ambiental por avifauna en las paredes del cañón durante la primavera, funcionando como el principal centro docente de formación de técnicos de la región debido a su excelente clima invernal.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30039','activo','Escuela de Escalada Clásica de Leyva (Macizo de Sierra Espuña - Núcleo Técnico Occidental) y Vía Ferrata de Totana (En proyecto avanzado)','Grandes Referentes Nacionales. Comparte la gestión técnica de las míticas Paredes de Leyva con Alhama. Totana capitaliza el acceso logístico a las vías clásicas históricas abiertas por los pioneros de la vertical en el sur peninsular (vías de autoprotección que exigen el uso riguroso de empotradores mecánicos, fisureros y gestión de reuniones flotantes en puentes de roca). El espacio cuenta con un protocolo ambiental idéntico bajo la dirección del Parque Regional de Sierra Espuña, controlando al milímetro la capacidad de carga de los sectores rocosos y prohibiendo de forma taxativa el equipamiento descontrolado. Con esta provincia damos por concluida oficialmente la Región de Murcia, habiendo catalogado y puntuado alfabéticamente todas sus localidades activas con infraestructuras homologadas. Siguiendo el orden alfabético estricto de las Comunidades Autónomas de España, la siguiente es la Comunidad Foral de Navarra (Nafarroa). Al ser una comunidad uniprovincial.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90720','activo','Barranco del Río Latsa (Arantza) y circuitos de multiaventura técnica en roca','Prestigio regional en la comarca de Cinco Villas. Es un descenso sobre roca granítica y esquistos que ofrece un caudal permanente muy estético, caracterizado por una sucesión de rápeles cortos (resalte máximo de 12 metros), toboganes naturales de gran velocidad y resaltes encajonados que recogen aguas frías. Dispone de equipamiento de anclajes inoxidables revisado por colectivos locales. Su uso comercial por agencias de turismo activo está supeditado a las declaraciones responsables de la Confederación Hidrográfica del Cantábrico y Medio Ambiente del Gobierno de Navarra.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31050','activo','Barranco del Infierno (Valle del Baztan / Oronoz-Mugairi) y tramo técnico de aguas bravas del Río Bidasoa','Formato de prestigio regional con notable tráfico comercial. El barranco ofrece una progresión caliza muy encajonada y sombría de carácter perenne, con rápeles técnicos encadenados bajo cascadas (resalte máximo de 15 metros) y badinas profundas que exigen nado defensivo. El río Bidasoa complementa el término con corrientes idóneas para el aprendizaje de kayak de aguas bravas. La actividad empresarial está estrictamente regulada por la normativa del Gobierno de Navarra para proteger especies endémicas como el desmán ibérico, controlando el aforo de grupos comerciales.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90725','activo','Escuela de Escalada de Etxauri (Sectores de la Pared del Astrónomo, Kale borroka, El Kiriako)','Impacto Internacional / Icono Supremo de Aventura. Etxauri es, de forma unánime, la escuela de escalada en roca caliza más importante, densa e histórica de Navarra y un referente indiscutible en toda Europa. Sus colosales murallas calcáreas de excelente adherencia ofrecen una inmensa concentración de vías técnicas de placa, regletas microscópicas, diedros perfectos y desplomes de continuidad totalmente equipados con químicos certificados y parabolts de métrica 12. La regulación medioambiental del Gobierno de Navarra es sumamente estricta: se aplican cierres biológicos severos e inflexibles por nidificación de grandes rapaces rupícolas (quebrantahuesos, águila real, halcón peregrino y buitre leonado) en paños críticos entre los meses de enero y agosto, registrando una macroactividad de empresas y cursos de formación técnica todo el año.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31159','activo','Río Irati (Tramo técnico de Aguas Bravas de la Foz de Lumbier) y zonas asociadas de escalada clásica de aventura','Grandes Referentes Nacionales con alta proyección internacional. El río Irati se encajona de forma monumental atravesando la Foz de Lumbier, abriendo un desfiladero colosal con paredes de caliza de más de 150 metros. Ofrece rápidos técnicos comerciales con trenes de olas potentes y rulos estables regulados por los desembalses de la presa superior de Itoiz, garantizando caudal técnico óptimo en época estival para rafting e hidrospeed. La regulación medioambiental es máxima al estar catalogado como Reserva Natural: prohibido taxativamente salirse de los canales de navegación e interferir con la colosal colonia de buitre leonado, requiriéndose visados ambientales anuales estrictos para todas las agencias inscritas. Con esta provincia damos por concluida oficialmente la Comunidad Foral de Navarra, habiendo catalogado y puntuado alfabéticamente todas sus localidades con actividad real certificada e infraestructuras técnicas de roca y agua. Siguiendo el orden alfabético estricto de las Comunidades Autónomas de España, la siguiente es el País Vasco (Euskadi). Daremos inicio con su primera provincia por orden alfabético global: Álava (Araba), poseedora de grandes enclaves de aventura en roca y agua técnica (como las escuelas de escalada calcárea de Egino, los barrancos estacionales kársticos de la sierra de Entzia o el entorno técnico asociado a la cordillera Cantábrica).','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50007','activo','Escuela de Escalada de Egino (Sectores del Tubo de la Leze y Pared de la Hoya) y Barranco de la Leze (Cueva-Barranco técnica)','Impacto Internacional / Icono Supremo de Aventura. La Leze es una de las joyas de la geografía de aventura europea por su fisonomía única: es un barranco subterráneo que cruza de lado a lado la Sierra de Altzania por el interior de una inmensa cueva. El descenso exige progresión estricta con frontales, neoprenos completos por badinas profundas de aguas gélidas y una decena de rápeles técnicos encadenados (resalte máximo de 25 metros) en oscuridad absoluta y atmósfera confinada (Compromiso V, sin escapatorias). Los sectores exteriores de Egino son la cuna de la escalada clásica alavesa. Toda la actividad de las empresas de turismo activo está estrictamente regulada por la Diputación Foral de Álava al estar integrado en el Parque Natural de Aizkorri-Aratz, requiriéndose declaraciones responsables diarias, cupos de grupo tasados y material técnico certificado.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50020','activo','Vía Ferrata de Sobrón (Tramo de Kuartango / Crestas de la Sierra de Arcamo) y sectores asociados','Grandes Referentes Nacionales en los límites occidentales de la provincia. La infraestructura aprovecha las imponentes aristas calcáreas de los cortados de la sierra, ofreciendo un trazado puramente vertical, muy atlético y expuesto que exige fuerza de brazos en sus desplomes consecutivos y una impecable técnica de cambio de mosquetones en tensión. Cuenta con líneas de vida e ingeniería de cables de acero inoxidable certificadas periódicamente bajo los máximos estándares de la federación vasca (EMF-FVM). Es utilizada regularmente por empresas de turismo activo del País Vasco y Burgos para el guiado avanzado de clientes, operando bajo registros de seguridad municipal.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01902','activo','Vía Ferrata de Sobrón (Tramo Deportivo de Lantarón) y Escuela de Escalada de Sobrón','Grandes Referentes Nacionales. Junto con el tramo de Kuartango, conforma el complejo de aventura de Sobrón, uno de los mayores polos económicos de turismo activo de Álava. La ferrata discurre por una afilada cresta caliza con pasos muy aéreos, puentes tibetanos y una gran tirolina técnica regulada. La escuela de escalada anexa ofrece muros de caliza de excelente adherencia perfectamente equipados con parabolts de métrica 12. La regulación de la Diputación Foral de Álava y el ayuntamiento exige el cumplimiento de las normativas de seguridad, estando condicionado el acceso por paradas biológicas temporales estrictas debido a la nidificación de grandes aves rapaces en las paredes del desfiladero del Ebro.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50037','activo','Escuela de Escalada de Valdegovía (Sectores de Villanueva de Valdegovía: La Cantera, El Techo)','Grandes Referentes Nacionales. Es la macroescuela de escalada deportiva en roca caliza más densa, técnica e importante de la provincia de Álava, atrayendo de forma regular a escaladores de todo el norte peninsular. Sus muros desplomados y placas perfectas de regletas ofrecen líneas de excelente continuidad y fuerza equipadas con químicos certificados por la Federación Vasca de Montaña. Al encontrarse englobado en un entorno de alto valor ecológico cercano al Parque Natural de Valderejo, la regulación ambiental es estricta: existen cierres biológicos severos por protección de rapaces rupícolas rupestres (alimoche y buitre leonado) de febrero a junio en sectores sensibles, registrando alta actividad de escuelas formativas de técnicos de montaña. Hemos completado la provincia de Álava integrando todos sus municipios con actividad real certificada e infraestructuras técnicas en roca y agua, manteniendo los filtros más rígidos del proyecto. Siguiendo el orden alfabético estricto de las provincias del País Vasco, la siguiente es Guipúzcoa (Gipuzkoa), poseedora de grandes enclaves de aventura en roca y agua como las ferratas de la comarca del Alto Deba, la mítica escuela de escalada caliza de Araotz en Oñati o los descensos alpinos.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21001','activo','Vía Ferrata de Murugain (Aretxabaleta / Arrasate) y sectores de escalada deportiva menores','Infraestructura de rango regional bien equipada sobre un espolón de roca caliza compacta en la comarca del Alto Deba. Cuenta con un trazado vertical limpio con un desnivel positivo de 80 metros, equipado con peldaños de acero inoxidable fijados con resina epoxi de alta resistencia, una línea de vida continua y un pequeño puente tibetano intermedio que aporta valor aéreo y psicológico al recorrido. Es un recurso intensamente explotado por empresas de aventura locales y de Vizcaya para bautismos de altura y formación técnica de iniciación.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90258','activo','Escuela de Escalada de Ataun (Sectores de Jentilbaratza y Ausa Gaztelu) y simas de progresión vertical técnica','Prestigio regional con notable solera montañera en la comarca del Goierri. Las imponentes crestas calizas que coronan el entorno del parque ofrecen itinerarios deportivos exigentes y líneas clásicas de autoprotección que exigen el uso de friends intermedios. Cuenta con reuniones homologadas con argolla y parabolts inoxidables revisados periódicamente por la EMF-FVM. Al encontrarse dentro del Parque Natural de Aralar, la actividad empresarial de las agencias de turismo activo está estrictamente supeditada al control de los guardas forestales y a las regulaciones de la Diputación, aplicando paradas biológicas por nidificación de rapaces entre febrero y junio.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90700','activo','Barranco del Río Agauntza (Estrechos técnicos del Agauntza) y zonas de rápel técnico alpino asociadas','Formato técnico de prestigio regional en las faldas de la Sierra de Aralar. El barranco es de carácter calizo kárstico, ofreciendo un descenso muy dinámico encajonado de gran fuerza hídrica durante los meses de invierno y primavera tras las copiosas lluvias cantábricas. El trazado exige rápeles encadenados bajo cascadas (con un resalte máximo de 15 metros), nado defensivo en badinas frías y pasamanos obligatorios en cabeceras húmedas resbaladizas. Dispone de equipamiento fijo de anclajes inoxidables homologados ensayados contra fatiga. Las empresas operan bajo autorizaciones ambientales estrictas de la Xunta/Diputación y de la Confederación Hidrográfica del Cantábrico (CHC).','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90672','activo','Vía Ferrata de Leintz-Gatzaga (Ferrata de Gatzaga / Castillo de Dorleta)','Prestigio regional con excelente proyección en el norte peninsular. Es una excelente infraestructura técnica municipal instalada de forma muy aérea sobre un muro calcáreo vertical que domina el histórico puerto. Cuenta con un largo puente tibetano de cables perfectamente tensado, pasos de flanqueo lateral expuestos y una variante deportiva avanzada con un extraplomo exigente que pone a prueba la fuerza de brazos de los clientes. Está completamente homologada bajo normativas de ingeniería de la federación vasca, requiriéndose el registro previo obligatorio a través del ayuntamiento para el control de la seguridad de las agencias comerciales.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21014','activo','Escuela de Escalada de Araotz (Sectores de la Cueva de Sandaili, Atxorrotx, El Convento) y Barranco de Arantzazu','Impacto Internacional / Icono Supremo de Aventura. Araotz en Oñati es la gran meca histórica e indiscutible de la escalada deportiva en roca caliza del País Vasco y uno de los centros de alto rendimiento natural más célebres de Europa (cuna de la dificultad vasca popularizada por leyendas como Patxi Usobiaga). Ofrece muros y bóvedas calizas de dimensiones colosales, famosas por sus desplomes de chorreras brutales, techos y placas técnicas perfectamente equipadas con tensores químicos de alta gama. El barranco estacional de Arantzazu complementa el término con rápeles cortos. Al ubicarse en el Parque Natural de Aizkorri-Aratz, la regulación ambiental es la.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90542','activo','Escuela de Escalada de Atxarte (Sectores de Eguzkiagirre, Labargorri, Desfiladero de Atxarte)','Grandes Referentes Nacionales. Atxarte es el santuario histórico de la escalada en roca de Vizcaya. Es un desfiladero kárstico colosal de roca caliza gris perfecta situado en el Parque Natural de Urkiola. Ofrece cientos de vías deportivas de placa técnica de regletas y fisuras de autoprotección en grandes agujas exentas. Su regulación medioambiental por la Diputación Foral de Bizkaia y el Gobierno Vasco es sumamente severa: parada biológica obligatoria de febrero a agosto en la práctica totalidad de las paredes por la anidación de aves rapaces protegidas (alimoche y buitre leonado), obligando a las empresas y escuelas de montaña a concentrar su actividad formativa en la temporada de otoño.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48051','activo','Vía Ferrata de Lanestosa (Ferrata de los T r r s d l R y)','Infraestructura de rango local y desarrollo provincial estratégico para dinamizar el municipio más pequeño de Vizcaya. Dispone de un itinerario vertical limpio sobre roca caliza que supera un desnivel de 65 metros con una línea de vida continua, puentes tibetanos cortos y peldaños de acero inoxidable bien fijados con resina epoxi. Es muy utilizada por las agencias de turismo activo locales para bautismos de altura comerciales y cursos básicos de progresión en pared de media jornada, operando bajo normativas y tasas de control municipal.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90261','activo','Barranco de Sintxita (Macizo del Gorbeia) y zonas de aventura en alta montaña','Formato de prestigio regional en las faldas vizcaínas del Parque Natural del Gorbeia. El barranco es un descenso de carácter torrencial que recoge las copiosas lluvias de las cumbres, ofreciendo rápeles encajonados de hasta 18 metros bajo cascadas y pozas que exigen técnicas de nado defensivo en primavera. Dispone de equipamiento de anclajes inoxidables de seguridad homologados por la federación vasca. Las agencias operan bajo autorizaciones ambientales y planes de control de aforo diarios gestionados por la Diputación para proteger especies endémicas fluviales.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90958','activo','Barranco de Uguna (Cascada de Uguna) y Barranco de Lanbreabe','Grandes Referentes Nacionales en el nicho de los cañones del norte. El barranco de Uguna ofrece un descenso espectacular en un entorno de hayedo cerrado sobre areniscas y rocas duras, caracterizado por una brutal verticalidad que salva la colosal cascada de Uguna. Exige rápeles encadenados muy técnicos de hasta 30 metros de altura expuestos a la fuerza del agua y pasamanos de instalación obligatoria en cabeceras húmedas resbaladizas. Su uso comercial por agencias especializadas se concentra en primavera, requiriéndose la correspondiente declaración responsable ambiental y el cumplimiento estricto de las directrices del Parque Natural del Gorbeia. Con esta provincia damos por concluida oficialmente la Comunidad Autónoma del País Vasco, habiendo catalogado y puntuado alfabéticamente todas sus provincias y municipios activos bajo los parámetros más estrictos de este proyecto nacional de auditoría de turismo activo técnico. Siguiendo el orden alfabético estricto de las Comunidades Autónomas de España, la siguiente es La Rioja. Al ser una comunidad uniprovincial.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90270','activo','Barranco del Río Najerilla (Estrechos de Anguiano / Barranco de las Cuevas) y zonas de escalada asociadas','Prestigio regional en la comarca de Anguiano. El descenso discurre por pasillos calizos hiperencajonados de gran valor geológico, ofreciendo rápeles técnicos de hasta 15 metros, pasamanos de instalación obligatoria en rocas húmedas y badinas que exigen nado defensivo durante la primavera. El equipamiento cuenta con anclajes fijos inoxidables revisados periódicamente por la Federación Riojana de Montañismo. La actividad de las empresas de turismo activo está supeditada a autorizaciones anuales de la Consejería de Sostenibilidad y Transición Ecológica del Gobierno de La Rioja y de la Confederación Hidrográfica del Ebro (CHE).','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90930','activo','Escuela de Escalada de Arnedillo (Sectores de las Paredes del Cidacos: Frontón, Castillo, Escalerilla) y Vía Ferrata de Arnedillo','Grandes Referentes Nacionales e icono histórico indiscutible de la roca en La Rioja. Las monumentales murallas de caliza jurásica gris que flanquean el río Cidacos albergan una de las escuelas de escalada más célebres y visitadas del norte peninsular. Cuenta con sectores perfectos de placas técnicas de regletas, diedros y desplomes de continuidad totalmente equipados con químicos certificados. La Vía Ferrata complementa la zona con un trazado vertical aéreo bien asegurado con ingeniería de cables moderna. Al ubicarse en una zona de Especial Protección para las Aves (ZEPA), la regulación ambiental es sumamente rigurosa: se aplican cierres biológicos estrictos por nidificación del buitre leonado y el halcón peregrino en paños sensibles entre los meses de febrero y agosto, registrando una alta densidad de escuelas y guías formativos todo el año.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26061','activo','Barranco del Río Ciloria (Barranco de Ezcaray - Tramo superior) y sectores de escalada menores en la Sierra de la Demanda','Prestigio regional con marcado carácter alpino. El barranco es de carácter torrencial, ofreciendo un trazado encajonado sobre pizarras y rocas duras que recoge las aguas de deshielo primaveral de las cumbres de la Demanda, exigiendo rápeles técnicos encadenados bajo cascadas (resalte máximo de 18 metros). Durante los meses de invierno, las zonas más altas funcionan como excelente infraestructura docente para cursos de alpinismo básico. Su uso comercial por agencias de turismo activo requiere la correspondiente declaración responsable ambiental comarcal para controlar el impacto en los valles de alta montaña.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26112','activo','Vía Ferrata de Ortigosa de Cameros (Ferrata de Juana Mier) y zonas asociadas de progresión vertical técnica','Infraestructura de rango local y desarrollo provincial estratégico instalada sobre las paredes de caliza que flanquean el cañón urbano del pueblo. Dispone de un itinerario de peldaños de acero inoxidable bien fijados con resina epoxi de alta resistencia, una línea de vida continua homologada y un espectacular puente tibetano de cables de unos 20 metros de longitud que aporta gran sensación aérea. Es un recurso muy rentable y explotado por agencias riojanas para bautismos de altura comerciales y cursos de progresión en pared de media jornada, operando bajo registros de seguridad municipal.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26119','activo','Escuela de Escalada de Préjano (Sectores de la Cantera y Paredes de Préjano) y tramos de rápel técnico asociados','Formato de prestigio regional en la cuenca del Cidacos. Sus muros de caliza ocre ofrecen una escalada física sobre regletas netas y placas técnicas de gran adherencia perfectamente equipadas con parabolts de acero inoxidable de métrica 12 y reuniones homologadas con argolla. Las empresas locales operan regularmente en la zona para cursos de iniciación avanzada. Cuenta con restricciones medioambientales por la presencia de avifauna rupícolas protegida coordinadas por la Dirección General de Biodiversidad, clausurando sectores específicos entre febrero y julio.','inventario_turismo_activo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26165','activo','Vía Ferrata de Viguera (Ferrata del Castillo de Viguera) y Escuela de Escalada de las Peñas de Viguera','Grandes Referentes Nacionales en el Valle del Iregua. Es una de las infraestructuras de ferrata más largas y aéreas del norte de España. El itinerario progresa sobre un colosal muro calizo vertical, caracterizado por una variante deportiva avanzada con un paso extraplomado exigente que requiere excelente resistencia de brazos y uso de baga de descanso técnica. Toda la instalación cuenta con homologación de ingeniería industrial certificada por la federación. Su explotación comercial por agencias de turismo activo está estrictamente supeditada al control de Medio Ambiente y a la parada biológica total por nidificación de rapaces rupícolas entre los meses de febrero y agosto. Con este bloque damos por concluida oficialmente la Comunidad Autónoma de La Rioja, habiendo catalogado y puntuado alfabéticamente todas sus localidades activas con infraestructuras homologadas. La última gran región que nos queda por procesar en este orden alfabético global de Comunidades Autónomas de España es la uniprovincial comunidad autónoma de Cantabria que ya fue procesada, por lo que la siguiente de la lista oficial es el archipiélago ya culminado y pasamos directamente a Ceuta y Melilla, o bien podemos dar el cierre global al documento. ¿Deseas que realicemos alguna comprobación técnica final o prefieres proponer nuevas opciones? Si quieres, puedo: • Generar un resumen de auditoría de los destinos de impacto internacional (notas 95-100).','inventario_turismo_activo_pdf');
